INSERT INTO public.biblioteca_vectores (id,coleccion,materia,contenido,num_articulo,fuente,metadata,embedding,jurisdiccion,fuente_tipo,es_norma_vigente,revision_pendiente,instrumento_id,num_articulo_norm,hash_contenido,ingest_batch,ingested_at) VALUES
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:51','mayalex_normativos','08_TRIBUTARIO','DOMICILIO TRIBUTARIO DE LAS PERSONAS JURÍDICAS Y ENTIDADES. El domicilio tributario de las personas jurídicas y demás entidades sin personalidad jurídica, es el que declare ante la Administración Tributaria, conforme al orden siguiente:

1) El de su domicilio social señalado en el documento contentivo de su personalidad o personería jurídica;

2) El lugar donde se encuentre su dirección o administración efectiva;

3) El lugar donde se halle el centro principal de su actividad, en caso de no conocerse dicha dirección o administración;

4) El lugar donde ocurra el hecho generador, en caso de no existir domicilio conforme a los numerales anteriores; y,

5) El que elija el sujeto activo, en caso de existir más de un domicilio en el sentido de este Artículo, previa notificación al obligado tributario.','51','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":51,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"1c27a05712c16e0babf5193f0e077b83e58fb569b77a8796dba3a3bc0cf7ca48","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a51","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','51','1c27a05712c16e0babf5193f0e077b83e58fb569b77a8796dba3a3bc0cf7ca48','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:52','mayalex_normativos','08_TRIBUTARIO','DOMICILIO TRIBUTARIO EN EL PAÍS DE LAS PERSONAS DOMICILIADAS EN EL EXTRANJERO. El domicilio tributario en el país de las personas naturales o jurídicas y demás entidades sin personalidad jurídica domiciliadas en el extranjero es el que declare ante la Administración Tributaria, conforme al orden siguiente:

1) Sí tienen lugar fijo de negocios o establecimiento permanente en el país, el que se establece según los artículos anteriores para las personas naturales o jurídicas y demás entidades sin personalidad jurídica;

2) En los demás casos, tienen el domicilio tributario de su representante legal en el país;

3) A falta de representante legal domiciliado en el país, tienen como domicilio tributario el lugar donde ocurra el hecho generador del tributo; y,

4) El que elija el sujeto activo, en caso de existir más de un domicilio en el sentido de este Artículo, previa notificación al obligado tributario.','52','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":52,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"b47e90966a2d8427ce86b932c787c01f3a9ba9524ce8c0cdcb7d3d3c8c9a5489","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a52","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','52','b47e90966a2d8427ce86b932c787c01f3a9ba9524ce8c0cdcb7d3d3c8c9a5489','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:53','mayalex_normativos','08_TRIBUTARIO','DECLARACIÓN Y CAMBIO DE DOMICILIO TRIBUTARIO.

1) Los obligados tributarios tienen la obligación de declarar su domicilio tributario y el cambio o rectificación del mismo, en la forma y condiciones establecidas en este Código;

2) El domicilio tributario se debe considerar subsistente en tanto su cambio no fuere notificado a la Administración Tributaria; y,

3) La Administración Tributaria puede cambiar o rectificar de oficio el domicilio tributario de los obligados tributarios mediante la comprobación pertinente, atendiendo las reglas establecidas en los artículos anteriores y previa notificación al obligado tributario.','53','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":53,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"43c7e5e77bf9333fe8a8a3af4b8a105a4a540585e8fabc4f051910bc555bae42","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a53","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','53','43c7e5e77bf9333fe8a8a3af4b8a105a4a540585e8fabc4f051910bc555bae42','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:54','mayalex_normativos','08_TRIBUTARIO','DOMICILIO TRIBUTARIO ÚNICO. Para efectos tributarios y aduaneros, toda persona natural, jurídica o entidad sólo debe tener un domicilio.','54','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":54,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"57a3aa882f8aaecbe610c109bf9cd747f0536f22ca7970992ba3c317cee0369e","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a54","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','54','57a3aa882f8aaecbe610c109bf9cd747f0536f22ca7970992ba3c317cee0369e','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:55','mayalex_normativos','08_TRIBUTARIO','DERECHOS Y GARANTÍAS DE LOS OBLIGADOS TRIBUTARIOS. Además de los que establezcan otras leyes, son derechos de los obligados tributarios, los siguientes:

1) Derecho a ser tratado con decoro, respeto, dignidad, imparcialidad y ética por el personal al servicio de la Secretaría de Estado en el Despacho de Finanzas (SEFIN), Superintendencia Tributaria Aduanera, Administración Tributaria y Administración Aduanera;

2) Derecho a inscribirse y obtener su Registro Tributario Nacional (RTN). La expedición por primera vez debe ser inmediata y gratuita, de conformidad con el procedimiento contenido en este Código. Cuando se expida por medios electrónicos su emisión y reposiciones deben ser gratuitas;

3) Derecho al carácter reservado de los datos, informes y antecedentes tributarios y aduaneros, así como de la información contenida en las declaraciones, informes y estudios de los obligados tributarios presentados ante la Secretaría de Estado en el Despacho de Finanzas (SEFIN), Superintendencia Tributaria Aduanera, Administración Tributaria y Administración Aduanera, en los términos previstos en Ley;

4) Derecho a ser informado por escrito y verbalmente; y ser asistido personalmente, por la Secretaría de Estado en el Despacho de Finanzas (SEFIN), Superintendencia Tributaria Aduanera, la Administración Tributaria y Administración Aduanera, en el ejercicio de sus derechos y el cumplimiento de sus obligaciones;

5) Derecho a realizar todas las peticiones y cuestiones que se formulen en los procedimientos de aplicación de los tributos, así como a obtener acceso a los expedientes y demás causas instruidas ante las instancias administrativas competentes;

6) Derecho a obtener a su costa copia de:

a) Los documentos que conforman los expedientes siempre y cuando no estén en proceso de resolución;

b) Las declaraciones, informes y estudios que el Obligado Tributario haya presentado;

c) Demás actuaciones realizadas en los términos previstos en la Ley, excepto las derivadas de investigaciones tributarias que no se hayan concluido; y, d) Derecho de obtener copia íntegra de todas las actuaciones contenidas en el expediente, la que debe ser entregada una vez que la respectiva instancia administrativa haya concluido una auditoría y se notifique la resolución correspondiente.

7) Presentar denuncias o quejas ante la Comisión Nacional de los Derechos Humanos (CONADEH) y otras instancias competentes, cuando la instancia administrativa correspondiente no garantice o respete sus derechos;

8) Derecho a no proporcionar los documentos ya presentados en cualquier diligencia, expediente o tramitación, que se encuentren en poder de la Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Superintendencia Tributaria Aduanera, la Administración Tributaria o la Administración Aduanera;

9) Derecho de repetición de los pagos realizados y devolución de los pagos en exceso que procedan dentro del plazo establecido en este Código;

10) Derecho a que se aplique de oficio o a petición de parte, la prescripción de la acción correspondiente, para determinar obligaciones, imponer sanciones y exigir el pago de la deuda tributaria o aduanera en los casos previstos en el presente Código;

11) Derecho a conocer el estado de las actuaciones administrativas y de la tramitación de los procedimientos en que sea parte y tener acceso físico a los mismos;

12) Derecho a que se identifique el personal de la Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Superintendencia Tributaria Aduanera, la Administración Tributaria y la Administración Aduanera, bajo cuya responsabilidad se ejecutan los procedimientos en que sea parte;

13) Derecho a ser informado al inicio de las actuaciones de comprobación o fiscalización, sobre la naturaleza y alcance de las mismas, así como de sus derechos y obligaciones en el curso de tales actuaciones y que se desarrollen en los plazos legales;

14) Derecho a la rectificación de declaraciones de acuerdo con lo dispuesto en este Código;

15) Derecho a que ninguna actuación material limite los derechos establecidos en este

Código y demás leyes tributarias y aduaneras, sin que previamente haya sido adoptada y legalmente comunicada la decisión que sirva de fundamento jurídico;

16) Derecho a impugnar las resoluciones emitidas por la Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Superintendencia Tributaria Aduanera, la Administración Tributaria y la Administración Aduanera, que les afecten, de acuerdo a lo establecido en el presente Código y a obtener un pronunciamiento expreso de las mismas en los plazos contenidos en el presente Código;

17) Derecho a la presunción de inocencia, al debido proceso, a ser oído y vencido en juicio y al derecho de defensa; y,

18) Derecho a presentar alegaciones y pruebas, dentro de los plazos de Ley. Son pruebas válidas a favor del obligado tributario, cualquier información que haya sido publicada en medios electrónicos oficiales de la Administración Tributaria o de la Administración Aduanera, cuando aplique.

Los obligados tributarios pueden actuar por si mismos o, por medio de representante procesal o apoderado legal.

Los derechos antes enunciados no excluyen los consignados en otras leyes y los derivados de Tratados o Convenciones Internacionales.','55','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":55,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"b6369d2d23b4374805f53a1fb3d94e5a672f97b9524e65e0555b7e8c24f6f464","ubicacion":["CAPÍTULO V","DERECHOS DE LOS OBLIGADOS TRIBUTARIOS"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a55","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','55','b6369d2d23b4374805f53a1fb3d94e5a672f97b9524e65e0555b7e8c24f6f464','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:56','mayalex_normativos','08_TRIBUTARIO','DERECHOS DE INFORMACIÓN A FAVOR DEL OBLIGADO TRIBUTARIO Y OBLIGACIÓN DE ASISTENCIA DEL ESTADO PARA FACILITAR EL CUMPLIMIENTO VOLUNTARIO. La Administración Tributaria y la Administración Aduanera deben proporcionar asistencia a los obligados tributarios en el cumplimiento voluntario de sus obligaciones, por conducto de los medios que estime pertinentes, en particular sus sitios u otros mecanismos electrónicos y, para ello debe:

1) Facilitar a los obligados tributarios programas informáticos de asistencia para la confección y presentación de declaraciones, autoliquidaciones y comunicaciones de datos, así como para el cumplimiento de otras obligaciones;

2) Explicar las normas tributarias y aduaneras utilizando en lo posible un lenguaje claro y accesible y, en los casos en que sean de naturaleza compleja, elaborar y distribuir por medios físicos o electrónicos, folletos explicativos a los obligados tributarios;

3) Elaborar, socializar y distribuir los formularios de declaración en forma que puedan ser cumplimentados por los obligados tributarios e informando las fechas y lugares de presentación;

4) Difundir, publicar y mantener actualizados los trámites y requisitos de todas las actuaciones que por mandato de este Código, de otras leyes o de reglamentos deban realizarse ante instancias administrativas específicas de naturaleza tributaria y aduanera, debiendo además publicar los flujogramas de los procesos correspondientes, detallando las instancias y dependencias que deben dictaminar y pronunciarse por cada proceso;

5) Señalar en forma precisa cuál es el documento a presentar, en los requerimientos mediante los cuales se exija a los obligados tributarios la presentación de declaraciones, comunicaciones, informes y demás documentos a que estén obligados;

6) Difundir y mantener actualizada toda la información que se refiera a instructivos, software de ayuda, trámites, normas procedimentales para la aplicación de reglamentos en materia tributaria y aduanera, entre otros, en su portal electrónico;

7) Sistematizar por fechas y ejes temáticos la legislación, reglamentos y demás normas promulgadas y vigentes, de manera que faciliten su conocimiento por parte de los obligados tributarios. Asimismo, debe mantener por separado, todas aquellas normas que hayan sido derogadas para consulta permanente;

8) Mantener a disposición de los obligados tributarios, por medios electrónicos y similares, las versiones actualizadas de las normas procedimentales tributarias y aduaneras. Las Administraciones deben actualizar sus archivos de normas en un plazo no mayor a diez (10) días hábiles después de su publicación en el Diario Oficial “La Gaceta”;

9) Difundir entre los obligados tributarios los recursos y medios de defensa que se pueden hacer valer contra las resoluciones y actos de carácter general emitidos por entidades públicas relacionadas con la materia tributaria y aduanera;

10) Promover talleres de capacitación a obligados tributarios de los diferentes sectores sociales y de la economía del país, sobre la aplicación de las normas tributarias y aduaneras; así mismo, instalar mesas de ayuda e instrucción tributaria y aduanera durante los principales períodos de presentación de declaraciones o cuando se pretenda aprobar nuevas leyes de carácter tributario o aduanero;

11) Difundir, publicar y mantener actualizada la información sobre las metas de recaudación tributaria y el comportamiento de los ingresos por tributo; toda la información relacionada con las importaciones por conducto de las aduanas del país, informando como mínimo sobre los bienes y mercancías importadas, sus posiciones arancelarias y tributos pagados; así como todas las estadísticas que la Secretaría de Estado en el Despacho de Finanzas (SEFIN) y de la Administración Tributaria y Administración Aduanera produzcan sobre el cumplimiento de metas de los ingresos, evasión tributaria, el comportamiento de los obligados tributarios, entre otros;

12) Publicar y mantener actualizados con periodicidad anual, los programas, proyectos y planes operativos de las diferentes unidades de trabajo. Asimismo, los criterios de clasificación de las diferentes categorías de obligados tributarios, los criterios para la realización de las funciones de cobranza; y,

13) Realizar cualquier otra acción tendiente a lograr los objetivos señalados.','56','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":56,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"7d68a94a15712db411ec4577e2ea2fe77b6eb84d3ac571c43d8e89f173f36035","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a56","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','56','7d68a94a15712db411ec4577e2ea2fe77b6eb84d3ac571c43d8e89f173f36035','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:57','mayalex_normativos','08_TRIBUTARIO','DEFENSORÍA ESPECIAL DE PROTECCIÓN AL OBLIGADO TRIBUTARIO. Créase la Defensoría Especial de Protección al Obligado Tributario, como una unidad o dependencia adscrita al Comisionado Nacional de los Derechos Humanos (CONADEH), a fin que en el marco de sus atribuciones en la defensa de los derechos fundamentales de las personas naturales o jurídicas, dotados o no de personalidad jurídica vele por los derechos de los obligados tributarios, ante las autoridades tributarias y aduaneras.','57','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":57,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"5fe8295226d661d12007e8c421fabf1cbd0c892770be24bbb5bd560699b376a2","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a57","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','57','5fe8295226d661d12007e8c421fabf1cbd0c892770be24bbb5bd560699b376a2','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:58','mayalex_normativos','08_TRIBUTARIO','DEBERES Y OBLIGACIONES EN GENERAL. Constituyen deberes y obligaciones de los obligados tributarios, sean sujetos de imposición o no, entre otros, los siguientes:

1) Inscribirse en los registros de la Administración Tributaria y Administración Aduanera, a los que deben aportar los datos necesarios y notificar sus modificaciones dentro de los plazos legalmente establecidos;

2) Inscribirse en los registros de la Secretaría de Estado en el Despacho de Finanzas (SEFIN) de conformidad a lo que establezca la Ley, a los que deben aportar los datos necesarios y notificar sus modificaciones conforme a lo establecido en el presente Código. En caso de incumplimiento de esta disposición, la Secretaría de Estado en el Despacho de Finanzas (SEFIN) debe imponer las sanciones directamente o, a su discreción, debe comunicar dicho incumplimiento a la Administración Tributaria o a la Administración Aduanera para que proceda a imponer las sanciones correspondientes;

3) Presentar declaraciones, notificaciones, autoliquidaciones y otros documentos que requiera la Administración Tributaria y la Administración Aduanera para el cumplimiento de sus funciones;

4) Llevar en su domicilio tributario, los libros de contabilidad y registros tributarios que las normas correspondientes establezcan, debiendo conservarlos por un período de cinco (5) años para los obligados tributarios inscritos en el Registro Tributario Nacional y por un período de siete (7) años para los demás casos;

5) Atender las comunicaciones y notificaciones por vía electrónica o cualquier otro medio válido, conforme a derecho, realizadas por la Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Superintendencia Tributaria Aduanera, la Administración Tributaria y la Administración Aduanera, según corresponda;

6) Respaldar las operaciones de enajenación o transferencia de bienes y de prestación de servicios mediante comprobantes extendidos en forma legal;

7) Suministrar a la Secretaría de Estado en el Despacho de Finanzas (SEFIN), Superintendencia Tributaria Aduanera, la Administración Tributaria y la Administración Aduanera, según corresponda, en la forma y plazos contenidos en Ley, la información que requieran para el cumplimiento de sus funciones; y,

8) Atender a la Secretaría de Estado en el Despacho de Finanzas (SEFIN), Superintendencia Tributaria Aduanera, la Administración Tributaria y la Administración Aduanera, según corresponda y prestarles la debida colaboración en el desarrollo de sus funciones.','58','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":58,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"6bd977a3714fbfb293bb894353915400083bcf899d47e183660097f2741b161c","ubicacion":["TÍTULO TERCERO","DEBERES DE LOS OBLIGADOS TRIBUTARIOS, SERVIDORES PÚBLICOS Y","OTROS OBLIGADOS TRIBUTARIOS","CAPÍTULO I","OBLIGACIONES DE LOS OBLIGADOS TRIBUTARIOS","SECCIÓN PRIMERA","DISPOSICIONES GENERALES"],"constancias":[{"nota":8,"tipo":"FE_DE_ERRATAS","texto":"Artículo 58. Se corrige letra “y” escrita en mayúscula originalmente inicio del numeral 1). Mediante Fe de Errata publicada en el Diario Oficial La Gaceta No.34,347 de fecha 25 de mayo de 2017.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a58","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','58','6bd977a3714fbfb293bb894353915400083bcf899d47e183660097f2741b161c','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:59','mayalex_normativos','08_TRIBUTARIO','CLASIFICACIÓN DE LOS CONTRIBUYENTES. La Administración Tributaria mediante Acuerdo Ejecutivo, en coordinación con la Administración Aduanera, debe determinar categorías de obligados tributarios; así como, establecer procedimientos para el cumplimiento de sus deberes instituidos por las normas tributarias y aduaneras reglamentarias. En tales acuerdos, debe publicar todos los criterios utilizados para la categorización de los obligados tributarios. Esta categorización debe realizarla y publicarla, al menos cada dos (2) años.','59','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":59,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"d76cda4bfef650cec8c26f91ac7e9d5e4ff82225138e515245650facd178e660","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a59","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','59','d76cda4bfef650cec8c26f91ac7e9d5e4ff82225138e515245650facd178e660','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:60','mayalex_normativos','08_TRIBUTARIO','DEBER DE COLABORACIÓN. La Administración Tributaria y la Administración Aduanera, en el marco de su competencia, conforme a los Acuerdos Nacionales Interinstitucionales con otras instituciones de la Administración Pública del país, con entidades privadas sin fines de lucro o con instituciones u organizaciones sin fines de lucro representativas de sectores o intereses sociales, laborales, empresariales o profesionales, entre otras, puede recibir colaboración en lo siguiente:

1) Emisión del Registro Tributario Nacional (RTN) y la inscripción en otros registros especializados ordenados por Ley;

2) Asistencia en la realización de autoliquidaciones, declaraciones y comunicaciones;

3) Presentación de cualquier documentación con trascendencia tributaria o aduanera, para fines de ser turnados para su resolución:

4) Campañas de información; y,

5) Realización de estudios o informes relacionados con la materia tributaria o aduanera.','60','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":60,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"20cfacf98f43112466774979970bbe40c54ef2ed42cd4062f8656e7c6faaa45d","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a60","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','60','20cfacf98f43112466774979970bbe40c54ef2ed42cd4062f8656e7c6faaa45d','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:61','mayalex_normativos','08_TRIBUTARIO','DEBER DE LA DENUNCIA PÚBLICA Y SU TRAMITACIÓN.

1) La denuncia pública interpuesta ante la Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Superintendencia Tributaria Aduanera, la Administración Tributaria o la Administración Aduanera debe ser realizada por las personas naturales o jurídicas, con relación a hechos o situaciones que conozcan y puedan ser constitutivos de infracciones administrativas o delitos tributarios o de otro modo puedan tener trascendencia para la gestión de los tributos; y,

2) La denuncia recibida en la Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Superintendencia Tributaria Aduanera, la Administración Tributaria o la Administración Aduanera, debe ser trasladada a los órganos competentes para llevar a cabo las actuaciones que procedan.','61','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":61,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"cf8c12d1e465393b8accf7fc477878187f8bcaf8cb7dae00e1326325591ece53","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a61","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','61','cf8c12d1e465393b8accf7fc477878187f8bcaf8cb7dae00e1326325591ece53','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:62','mayalex_normativos','08_TRIBUTARIO','DECLARACIONES Y MANIFESTACIONES.

1) El obligado tributario debe presentar las declaraciones, autoliquidaciones e informes establecidos en la Ley;

2) En las declaraciones necesariamente se debe señalar la dirección exacta en la que deben hacerse las notificaciones, salvo que aquella ya se hubiera registrado, según corresponda; y,

3) Cualquier información que se requiera a los obligados tributarios, en el marco de sus atribuciones legales, se deben denominar “Manifestaciones” y la omisión a presentarlas se debe sancionar conforme a lo dispuesto en este Código.','62','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":62,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"33ec61326fa92cdde71dea5fc01d442417ff4b78157f3cd5d4e7c1ddaf44e3ec","ubicacion":["SECCIÓN SEGUNDA","OBLIGACIONES FORMALES DE LOS OBLIGADOS TRIBUTARIOS"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a62","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','62','33ec61326fa92cdde71dea5fc01d442417ff4b78157f3cd5d4e7c1ddaf44e3ec','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:63','mayalex_normativos','08_TRIBUTARIO','OBLIGACIONES FORMALES DE LOS OBLIGADOS TRIBUTARIOS. Los obligados tributarios deben facilitar las tareas de revisión, verificación, control, fiscalización, investigación, determinación y cobro que realice la Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Superintendencia Tributaria Aduanera, la Administración Tributaria o la Administración Aduanera, en el cumplimiento de sus funciones, observando los deberes que les impongan las leyes, los reglamentos y la propia normativa interna. En especial deben:

1) Conservar y respaldar todas las operaciones de enajenación, transferencia y prestaciones de bienes y servicios mediante la emisión de comprobantes extendidos en forma legal;

2) Llevar libros de contabilidad y registros referidos a las actividades y operaciones vinculadas con la tributación en los términos establecidos en el Artículo siguiente y por la Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Superintendencia Tributaria Aduanera, la Administración Tributaria o la Administración Aduanera. A los fines del valor probatorio de los registros efectuados, las mismas deben estar respaldadas por los comprobantes de las transacciones realizadas;

3) Conservarlos libros contables y registros especiales, documentos y antecedentes de los hechos generadores, archivos electrónicos, programas, subprogramas y demás registros procesados mediante sistemas electrónicos o de computación en forma ordenada y mantenerlos en su domicilio fiscal a disposición inmediata de la Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Superintendencia Tributaria Aduanera, la Administración Tributaria o la Administración Aduanera, cuando se lo soliciten o cuando se presenten en su domicilio tributario servidores públicos debidamente acreditados, a efecto de solicitar documentación o información de carácter tributario. Dicha información se debe conservar por un plazo de cinco (5) años para los obligados tributarios inscritos en el Registro Tributario Nacional (RTN) y por un período de siete (7) años para los demás casos;

4) La disponibilidad inmediata implica que los registros contables deben ser exhibidos en la ejecución de operativos masivos, en el mismo momento de la solicitud y tiene el propósito de confirmar que efectivamente los obligados tributarios están llevando en forma correcta dichos registros;

5) Cuando terceros sean los encargados de la elaboración de la contabilidad de los obligados tributarios, la Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Superintendencia Tributaria Aduanera, la Administración Tributaria o la Administración Aduanera mediante citación debe otorgar un plazo de cinco (5) días hábiles siguientes a la solicitud, para que presenten los documentos;

6) Presentar en tiempo las declaraciones juradas que determinen las leyes tributarias y aduaneras; así como las manifestaciones informativas e informes, en la forma y medios que establezca la Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Superintendencia Tributaria Aduanera, la Administración Tributaria o la Administración Aduanera;

7) Proporcionar copia de la información y documentación en la forma requerida por la Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Superintendencia Tributaria Aduanera, la Administración Tributaria o la Administración Aduanera, con la salvaguarda de las limitaciones, prohibiciones y condiciones contenidas en la Ley de Transparencia y Acceso a la Información Pública, de las declaraciones emitidas por el Instituto de Acceso a la Información Pública (IAIP), así como de cualquier legislación que proteja la información del obligado tributario;

8) Poner a disposición toda la información y documentación relacionada con el equipamiento de computación y los programas de sistema (o software básico o de base) y a los programas de aplicación (o software de aplicación) que se utilicen en los sistemas informáticos de registro y contabilidad de las operaciones vinculadas con la materia imponible, ya sea que el procesamiento se efectúe en equipos propios, arrendados o que el servicio sea prestado por terceros. Esta forma de disposición no implica la entrega física o electrónica de manuales, códigos fuentes, copias, respaldos o cualquier otra forma de entrega de equipos y programas, ni tampoco la facilidad de establecer conexiones remotas por cualquier medio o forma física o electrónica; la facultad de la Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Superintendencia Tributaria Aduanera, la Administración Tributaria o la Administración Aduanera, se limita a su observación en el lugar donde éstos se encuentren. Tales instituciones no pueden realizar copias de software o programas, ni tampoco compartir los conocimientos e información verificados; asimismo, responden por los daños y perjuicios que cause la conducta negligente de cualquier servidor público en perjuicio del obligado tributario. De igual manera pueden consultar puntualmente las bases de datos de los obligados tributarios para cumplir con sus funciones de inspección, control, verificación y fiscalización;

9) Permitir la utilización de programas y utilitarios de aplicación en auditoría tributaria y aduanera de propiedad de la Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Superintendencia Tributaria Aduanera, la Administración Tributaria o la Administración Aduanera, en los servicios de computación propios o de terceros, en momentos en que no obstaculice el normal desarrollo de la actividad del obligado tributario. Los obligados tributarios tienen el derecho de estar presentes, con la asistencia de las personas y profesionales que estimen conveniente, en la ejecución de los programas o utilitarios. Estos programas o utilitarios no pueden instalarse de forma permanente o temporal sin la presencia de los técnicos de la institución que lo practique y del personal que el obligado tributario estime incorporar,

10) Notificar por escrito o por medios electrónicos legalmente reconocidos y autorizados por la Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Superintendencia Tributaria Aduanera, la Administración Tributaria o la Administración Aduanera, cualquier cambio que sea susceptible de producir una modificación de su responsabilidad tributaria o aduanera, sin perjuicio que éstas comprueben la veracidad de los cambios notificados;

11) Notificar por escrito o por medios electrónicos legalmente reconocidos y autorizados por la Secretaría de Estado en el Despacho de Finanzas (SEFIN), Superintendencia Tributaria Aduanera, la Administración Tributaria o la Administración Aduanera, según corresponda, en la forma y plazos previstos en este Código o en las leyes tributarias y aduaneras, su domicilio tributario, la ubicación exacta de los establecimientos o locales en que realiza las actividades generadoras de sus obligaciones tributarias y los sitios en que almacenan bienes o documentos, así como de los cambios de actividades o del cese, fusiones, absorciones o traspasos de la empresa. La disposición contenida en este numeral, se debe aplicar sin perjuicio de la verificación y fiscalización que ejerzan;

12) Atender dentro de los cinco (5) días hábiles siguientes, los llamamientos o citatorios que, por escrito o por medios electrónicos, realice la autoridad competente; y,

13) Los demás que determinen las leyes y sus reglamentos.','63','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":63,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"28d9ce45e4f32695429de661474965442d8c9b6549e63001914b4ef0582cbca1","ubicacion":[],"constancias":[{"nota":9,"tipo":"FE_DE_ERRATAS","texto":"Artículo 63. Numeral 8) Se corrige repetición de la palabra “la” en noveno párrafo. Mediante Fe de Errata publicada en el Diario Oficial La Gaceta No.34,347 de fecha 25 de mayo de 2017.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a63","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','63','28d9ce45e4f32695429de661474965442d8c9b6549e63001914b4ef0582cbca1','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:64','mayalex_normativos','08_TRIBUTARIO','OBLIGACIÓN DE LLEVAR CONTABILIDAD. Los obligados tributarios deben llevar contabilidad conforme las reglas siguientes:

1) Llevar y mantenerlos registros contables que determinen las leyes, los respectivos reglamentos y las Normas Internacionales de Información Financiera generalmente aceptadas en Honduras;

2) Los asientos en la contabilidad deben ser hechos con la claridad debida, se deben efectuar dentro de los treinta (30) días siguientes a la fecha en que se realizó el hecho generador de la operación; y,

3) Llevar y mantener la contabilidad en su domicilio tributario, sin perjuicio de haber contratado servicios de contabilidad dentro del país.','64','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":64,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"54d1bbf440e9d463ee1f29f6689a8ac7c74e80711b3abae6114943fa3b32dd45","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a64","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','64','54d1bbf440e9d463ee1f29f6689a8ac7c74e80711b3abae6114943fa3b32dd45','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:65','mayalex_normativos','08_TRIBUTARIO','OBLIGACIÓN DE EXTENDER DOCUMENTOS FISCALES. Los obligados tributarios deben extender documentos fiscales por las actividades que realicen y hacerlos en la forma que permita identificar a quien los expida y en su caso reciba y, la operación de que se trate de acuerdo con lo que al efecto establezcan las leyes o los reglamentos tributarios y aduaneros.','65','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":65,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"31c74a3fde77b0ebc1e7f9ad192ed0d655978f1fa79c57926cb30061228677b1","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a65","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','65','31c74a3fde77b0ebc1e7f9ad192ed0d655978f1fa79c57926cb30061228677b1','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:66','mayalex_normativos','08_TRIBUTARIO','OBLIGACIÓN DE INSCRIBIRSE EN EL REGISTRO TRIBUTARIO NACIONAL.

1) Las personas naturales, jurídicas y las organizaciones o entidades que carecen de personalidad jurídica, pero que realizan actividades que las convierten en obligados tributarios, deben inscribirse en el Registro Tributario Nacional (RIN) que al efecto lleva la Administración Tributaria, conforme con lo dispuesto en el marco legal aplicable;

2) La expedición de este documento debe ser inmediata y gratuita por primera vez, sin necesidad de aportar documentos de soporte alguno, salvo la Tarjeta de Identidad, Pasaporte o Carné de Residente, para las personas naturales; así como el documento que acredite el domicilio. La expedición del documento puede ser física o electrónica; en caso de ser electrónico la emisión y reposiciones deben ser gratuitas. La solicitud y entrega de este documento debe ser personalísima. No obstante, puede ser solicitada y entregada a un tercero siempre y cuando presente poder o carta poder por el obligado tributario debidamente autenticada. Se exceptúa de este procedimiento las solicitudes y entregas del Registro Tributario Nacional (RTN) que se hagan por medios electrónicos, utilizando la firma electrónica;

3) En el caso de las personas naturales su Registro Tributario Nacional (RTN) es el mismo número que el de inscripción en el Registro Nacional de las Personas (RNP) y tiene la duración de su vida natural. La Administración Tributaria debe suscribir los convenios necesarios con el Registro Nacional de las Personas (RNP) para incorporar a las personas naturales que nazcan, se asienten o se naturalicen en Honduras. Para fines del cumplimiento de las funciones de la Administración Tributaria, el Registro Tributario Nacional (RTN) asignado se debe activar en los sistemas de la misma, en el momento en que el obligado tributario ejecute actos con trascendencia tributaria;

4) Las demás personas naturales, deben obtener el Registro Tributario Nacional (RTN) mediante el procedimiento contenido en el presente Artículo;

5) Las personas jurídicas deben inscribirse en el Registro Tributario Nacional (RTN) en el mismo acto de su registro o incorporación, debiendo emitírseles de forma automática el número de identificación tributaria, sin requerirles ningún requisito adicional. No puede exigirse como requisito previo la obtención del Registro Tributario Nacional (RTN) de los socios o accionistas, sean éstas personas naturales o jurídicas, residentes, domiciliados o no en el territorio nacional. No obstante, debe presentar el documento acreditativo de la identificación de los socios o accionistas. El Registro Tributario Nacional (RTN) de las personas jurídicas, con o sinfines de lucro y aquellas organizaciones o entidades que carecen de personalidad jurídica, se deben cancelar únicamente en los casos en que conforme a la Ley la persona jurídica haya sido disuelta y liquidada; y,

6) Los extranjeros residentes y las personas jurídicas extranjeras domiciliadas, que realicen actuaciones con trascendencia tributaria, deben solicitar su inscripción en el Registro Tributario Nacional (RTN), mediante un formulario especial simplificado que debe emitir la Administración Tributaria. El Registro Tributario Nacional (RTN) de las personas jurídicas extranjeras domiciliadas se debe cancelar cuando su acuerdo de cancelación para operar en el país se inscriba en el Registro Mercantil correspondiente.','66','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":66,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"3323c30839e35a51e5052f0bcc29fb273af283acd4f7d8170a440e8d22adc570","ubicacion":[],"constancias":[{"nota":10,"tipo":"FE_DE_ERRATAS","texto":"Artículo 66. Numeral 2) Se corrige la palabra “deben” por la palabra “debe”. Mediante Fe de Errata publicada en el Diario Oficial La Gaceta No.34,347 de fecha 25 de mayo de 2017.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a66","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','66','3323c30839e35a51e5052f0bcc29fb273af283acd4f7d8170a440e8d22adc570','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:67','mayalex_normativos','08_TRIBUTARIO','OBLIGACIONES EN CASO DE INICIO EN LA ACTIVIDAD.

1) Las personas naturales, jurídicas y las organizaciones o entidades que carecen de personalidad jurídica, susceptibles de ser gravadas con tributos, deben presentar ante la Administración Tributaria, dentro de los cuarenta (40) días calendarios siguientes a la fecha de inicio de sus actividades, una Declaración Jurada sobre tal evento; y,

2) La declaración en referencia se debe hacer en formularios que para el efecto establezca la Administración Tributaria.','67','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":67,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"8e79a0952092d7cf0dc24205297cadc686e909627cadb9a154e90c1490aa3690","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a67","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','67','8e79a0952092d7cf0dc24205297cadc686e909627cadb9a154e90c1490aa3690','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:68','mayalex_normativos','08_TRIBUTARIO','OBLIGACIONES EN CASO DE CESE DE ACTIVIDADES.

1) Los obligados tributarios que por cualquier causa cesen en las actividades generadoras de las obligaciones tributarias, deben presentar dentro de los sesenta (60) días calendarios siguientes a la fecha de su acaecimiento la Declaración Jurada sobre tal evento y cuando corresponda deben pagar en la institución financiera autorizada;

2) Dentro del plazo antes señalado, el obligado tributario debe notificar ante la

Administración Tributaria el cese de las actividades, acompañando los correspondientes estados financieros, sin perjuicio de la verificación posterior;

3) Para las personas naturales, el Registro Tributario Nacional (RTN) sólo puede cancelarse por causa de muerte, siempre que no existan obligaciones tributarias pendientes con el Estado o hasta que las actividades mercantiles o profesionales del causante hayan cesado o se transfieran a un tercero. Para estos efectos, con la periodicidad que la Administración Tributaria convenga con el Registro Nacional de las Personas (RNP), debe remitirse la información de las defunciones de todas las personas naturales, nacionales y extranjeras domiciliadas o residentes. La Administración Tributaria lo debe comunicar a la Secretaría de Estado en los Despachos de Finanzas (SEFIN), Superintendencia Tributaria Aduanera y la Administración Aduanera, para los fines que a esta correspondan, y,

4) Para las personas jurídicas, el Registro Tributario Nacional (RTN) solamente puede cancelarse cuando ésta sea disuelta y liquidada y no existan obligaciones tributarias o aduaneras pendientes con el Estado.','68','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":68,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"91215ea8b5d920b6615621e16a2f4b880fd9c1434cae78b193c0f2ed383d242b","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a68","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','68','91215ea8b5d920b6615621e16a2f4b880fd9c1434cae78b193c0f2ed383d242b','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:69','mayalex_normativos','08_TRIBUTARIO','DEBERES GENERALES DE LOS SERVIDORES PÚBLICOS DE LA SECRETARÍA DE ESTADO EN EL DESPACHO DE FINANZAS, LA SUPERINTENDENCIA TRIBUTARIA ADUANERA, DE LA ADMINISTRACIÓN TRIBUTARIA Y DE LA ADMINISTRACIÓN ADUANERA.

1) Cuando los servidores públicos soliciten documentación o información de carácter tributario o aduanero, con el propósito de confirmar que efectivamente los obligados tributarios están llevando en la forma correcta los registros contables establecidos por la Ley, deben levantar acta del estado de dichos registros, debiendo ser firmada por el servidor público y por el obligado tributario o su representante legal, expresando su conformidad o inconformidad parcial o total con el contenido de la misma. En caso de que el obligado tributario o su representante se nieguen a firmar el acta, este hecho debe ser consignado en la misma. Esta acta constituye medio probatorio para los efectos legales posteriores que sustancie el Estado o los obligados tributarios;

2) En caso que se encuentren indicios de la comisión de un delito tributario, la Autoridad superior de la Secretaría de Estado en el Despacho de Finanzas (SEFIN), Superintendencia Tributaria Aduanera, Administración Tributaria o Administración Aduanera, según el caso, debe comunicarlo al Ministerio Público para que éste realice las investigaciones que correspondan en el marco de sus competencias legales.','69','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":69,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"61996b141255f6e4ee712622d27aef4b681bd4cbb10d873ed039ec115b3bf4d7","ubicacion":["SECCIÓN TERCERA","DE LAS OBLIGACIONES FORMALES DE LOS SERVIDORES PÚBLICOS Y OTROS","OBLIGADOS TRIBUTARIOS"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a69","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','69','61996b141255f6e4ee712622d27aef4b681bd4cbb10d873ed039ec115b3bf4d7','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:70','mayalex_normativos','08_TRIBUTARIO','DEBERES DE RESERVA DE LOS SERVIDORES PÚBLICOS Y OTROS COLABORADORES DE LA SECRETARÍA DE ESTADO EN EL DESPACHO DE FINANZAS, LA SUPERINTENDENCIA TRIBUTARIA ADUANERA, DE LA ADMINISTRACIÓN TRIBUTARIA Y DE LA ADMINISTRACIÓN ADUANERA.

1) Los servidores públicos que intervengan en los diversos trámites relativos a la aplicación de las disposiciones tributarias y aduaneras, están obligados a guardar absoluta reserva en lo concerniente a las declaraciones y datos suministrados por los obligados tributarios o por terceros, así como de la información obtenida en el ejercicio de las facultades de fiscalización. Dicha reserva no comprende los casos en que deban suministrar datos a:

a) Las autoridades judiciales mediante el oficio correspondiente, en procesos de orden penal o para la ejecución de resoluciones judiciales que tengan el carácter de firmes;

b) Las autoridades judiciales encargadas de la protección de menores e incapacitados, así como de las que conozcan de pensiones alimenticias;

c) El Ministerio Público (MP) y la Procuraduría General de la República (PGR), para la lucha contra el delito fiscal, contra el fraude en la obtención o percepción de ayudas o subvenciones y contra el fraude en la cotización y recaudación de las cuotas de los sistemas de seguridad social, así como en la obtención y disfrute de prestaciones a cargo de dichos sistemas, siempre y cuando exista un expediente en investigación;

d) El Ministerio Público (MP) y la Comisión Nacional de Bancos y Seguros (CNBS), para la prevención del lavado de activos, infracciones monetarias y financiación del terrorismo;

e) El Tribunal Supremo Electoral (TSE), respecto de personas que aspiren a cargos de elección popular;

f) Los restantes organismos que administren tributos, en tanto la información esté estrictamente vinculados con la fiscalización y percepción de los gravámenes de sus respectivas jurisdicciones, de conformidad con lo establecido en la Constitución de la República o las leyes que correspondan y sean aplicables en lo conducente;

g) El Tribunal Superior de Cuentas (TSC) para sus funciones de control de la gestión de la Secretaría de Estado en el Despacho de Finanzas (SEFIN), Superintendencia Tributaria Aduanera, Administración Tributaria o Administración Aduanera, en el ejercicio de sus funciones fiscalizadoras que por Ley le corresponden; y, h) Las Administraciones Tributarias o Aduaneras de otros países en cumplimiento de la asistencia administrativa mutua en sus respectivas materias, acordada en los Convenios de Derecho Internacional sobre la materia de este Código, incluyendo convenios o acuerdos internacionales para evitar la doble imposición en materia de patrimonio e Impuesto Sobre la Renta.

i) La Secretaría de Estado en el Despacho de Finanzas (SEFIN), Superintendencia Tributaria Aduanera, Administración Tributaria o Administración Aduanera, en el uso de sus facultades otorgados por la Ley.

j) El Banco Central de Honduras (BCH) para compilación de estadísticas macroeconómicas, monetarias, fiscales y financieras como parte del cumplimiento de sus facultades que le son otorgadas por la Ley.

2) La reserva tampoco debe comprender la información relativa a la deuda tributaria o aduanera firme de los obligados tributarios que no haya sido pagada o garantizada u objeto de un plan de pagos que esté en situación de incumplimiento. Para estos efectos, no se debe considerar “firme” un crédito si está aún en vía de revisión en sede administrativa o judicial; Tampoco se debe considerar “firme” el crédito si un Tribunal Judicial ha dictado una medida cautelar con el fin que la Administración Tributaria o la Administración Aduanera cese provisionalmente en una actividad, se abstenga temporalmente de realizar una conducta o de prohibición temporal de interrumpir o de cesar en la realización de una prestación que viniera llevándose a cabo;

3) Los obligados tributarios inconformes con la publicación de sus datos, pueden llevar a cabo la aclaración o rectificación ante la Secretaría de Estado en el Despacho de Finanzas (SEFIN), Superintendencia Tributaria Aduanera, Administración Tributaria O Administración Aduanera conforme al procedimiento contenido en el Reglamento aprobado por el Presidente de la República por conducto de la Secretaría de Estado en el Despacho de Finanzas (SEFIN); en el cual pueden aportar las pruebas que a su derecho convenga. Las referidas instituciones deben resolver la solicitud en un plazo no mayor a diez (10) días hábiles; y, en caso que se resuelva a favor del reclamante, se debe proceder a eliminar la información publicada que corresponda, sin perjuicio de responder por los daños y perjuicios causados al obligado tributario que determine un juez competente y, además, sin perjuicio de la acción penal que proceda por configurarse un delito contra el honor, situación de responsabilidad que recae en el servidor público que directa o indirectamente haya intervenido en la entrega de la información publicada o haya sido el autorizante de su publicación;

4) Con independencia de las responsabilidades penales o civiles que pudieran derivarse para el servidor público infractor, la infracción de este particular deber de sigilo, se considera falta disciplinaria muy grave; y,

5) En todo caso, el obligado a quien se refiere la información puede dar su consentimiento por escrito, para que ésta sea compartida o divulgada.','70','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":70,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"37b6aa47db8eb6955c890d203d67eedad7580b2a620cb0d50677c37a1a424b4d","ubicacion":[],"constancias":[{"nota":11,"tipo":"ADICION","texto":"Artículo 70. Adicionar inciso j). Mediante Decreto No.170-2019 de fecha 12 de diciembre de 2019 y publicado en el Diario Oficial La Gaceta el 25 de enero del 2020.","decretos":["170-2019"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a70","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (artículo adicionado): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','70','37b6aa47db8eb6955c890d203d67eedad7580b2a620cb0d50677c37a1a424b4d','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:71','mayalex_normativos','08_TRIBUTARIO','DEBERES DE COLABORACIÓN DE LOS SERVIDORES PÚBLICOS AJENOS A LA SECRETARÍA DE ESTADO EN EL DESPACHO DE FINANZAS (SEFIN), SUPERINTENDENCIA TRIBUTARIA ADUANERA, ADMINISTRACIÓN TRIBUTARIA O ADMINISTRACIÓN ADUANERA.

1) Las autoridades, de todos los niveles de la organización política del Estado cualquiera que sea su naturaleza, los jefes o encargados de oficinas civiles o militares y de los demás entes públicos territoriales, los organismos autónomos, descentralizados y empresas públicas, auxiliares de la Administración Pública, personas jurídicas de derecho privado que por propiedad o gestión sean controladas por la Administración Pública, entes u Órganos que por razones de eficiencia o economía ejercen una o más funciones administrativas públicas, las cámaras y corporaciones, colegios y asociaciones profesionales, las mutuales de previsión social; las demás entidades públicas, incluidas las gestoras de la Seguridad Social y quienes, en general, ejerzan funciones públicas, están obligados a suministrar a la Secretaría de Estado en el Despacho de Finanzas (SEFIN), Superintendencia Tributaria Aduanera, Administración Tributaria y Administración Aduanera, cuantos datos y antecedentes con trascendencia tributaria o aduanera éstas requieran por requerimientos concretos y a prestarles a sus servidores públicos el apoyo, concurso, auxilio y protección para el ejercicio de sus funciones;

2) Lo dispuesto en este Artículo se entiende sin perjuicio de lo establecido como salvaguardas en las leyes generales y especiales que regulen a cada una de las instituciones del Estado requeridas por la Secretaría de Estado en el Despacho de Finanzas (SEFIN), Superintendencia Tributaria Aduanera, Administración Tributaria o Administración Aduanera. En estos casos, se debe solicitar al Juez competente que autorice la entrega de la información que se requiera;

3) Asimismo, deben denunciar ante el Ministerio Público los delitos tributarios que lleguen a su conocimiento en cumplimiento de sus funciones;

4) Cuando encuentren indicios de delitos tributarios, dichos servidores públicos que conozcan de ellos los deben poner, por el medio pertinente, de inmediato en conocimiento del Ministerio Público, para los efectos legales correspondientes;

5) A las mismas obligaciones quedan sujetos los partidos políticos, sindicatos y asociaciones civiles y demás asociaciones empresariales; y,

6) Los Juzgados y Tribunales de la República deben facilitar a la Secretaría de Estado en el Despacho de Finanzas (SEFIN), Superintendencia Tributaria Aduanera, Administración Tributaria o Administración Aduanera, de oficio o a requerimiento de la misma, cuantos datos con trascendencia tributaria o aduanera se desprendan de las actuaciones judiciales que conozcan, respetando, en todo caso, las restricciones que la Ley contemple.','71','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":71,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"facca207682c48f61956a461067a2dd1583f2a286a2e59e7bd5b42cc9ee19803","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a71","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','71','facca207682c48f61956a461067a2dd1583f2a286a2e59e7bd5b42cc9ee19803','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:72','mayalex_normativos','08_TRIBUTARIO','DEBERES DE INFORMACIÓN DE OTROS OBLIGADOS TRIBUTARIOS.

1) Los obligados tributarios, personas naturales o jurídicas y unidades económicas o entes colectivos, de derecho público o privado, están obligados a cooperar con la Secretaría de Estado en el Despacho de Finanzas (SEFIN), Superintendencia Tributaria Aduanera, Administración Tributaria o Administración Aduanera, en el ámbito de sus competencias, en las funciones de verificación, determinación, investigación, fiscalización y cobranza, debiendo proporcionarle toda clase de datos, informes o antecedentes con trascendencia tributaria o aduanera, derivados directamente de sus relaciones económicas, profesionales o financieras con otras personas, que le sean requeridos por ellas, salvo aquellos datos, información y documentación protegida por la Ley y este Código;

2) De acuerdo con lo previsto en el numeral anterior, en particular:

a) Los agentes de retención y percepción, así como los obligados por pagos en especie, están obligados a presentar informes de las cantidades satisfechas a otras personas en concepto de rendimientos del trabajo, del capital y de actividades empresariales o profesionales; y, b) Las sociedades, asociaciones, colegios profesionales u otras entidades que entre sus funciones realicen la de cobro por cuenta de sus socios, asociados o colegiados, de honorarios profesionales o de otros derivados de la propiedad intelectual o industrial o los derechos de autor, están obligados a informar de estos rendimientos y a ponerlos en conocimiento de la Administración Tributaria, salvo las protecciones y reservas de datos, información y documentación protegida por la Ley y este Código.

3) Las obligaciones a las que se refiere el numeral anterior deben cumplirse, en atención a requerimientos individualizados, por parte del titular de la Secretaría de Estado en el Despacho de Finanzas (SEFIN), Superintendencia Tributaria Aduanera, la Administración Tributaria y la Administración Aduanera, en la forma y plazos determinados por la Ley;

4) Cuando se trate de requerimientos individualizados relativos a los movimientos de cuentas corrientes, depósitos de ahorro y a plazo, préstamos y créditos y, demás operaciones activas y pasivas, a cargo de los bancos y sociedades financieras, cajas de ahorro, cooperativas de crédito y cuantas personas naturales o jurídicas, y demás entidades sin personalidad jurídica, que realicen operaciones crediticias, éstos se deben efectuar por conducto de las entidades reguladoras principales. Los requerimientos individualizados deben detallarlos datos identificativos del cheque u orden de pago de que se trate o, bien las operaciones objeto de investigación, los obligados tributarios afectados y el período de tiempo a que se refieren; y,

5) Los profesionales no pueden invocar el secreto profesional a efecto de impedir una posible comprobación de sus propias situaciones tributarias o aduaneras.','72','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":72,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"dee7220530c6e5c5747da2520c9f98bf529640f5cf3ec55b1c53255e19a6854b","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a72","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','72','dee7220530c6e5c5747da2520c9f98bf529640f5cf3ec55b1c53255e19a6854b','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:73','mayalex_normativos','08_TRIBUTARIO','OBLIGACIÓN DE RESERVA.

1) Los agentes de retención o percepción de tributos, así como aquéllos a quienes la Administración Tributaria o Aduanera, les encomiende el procesamiento de información tributaria o aduanera; gestiones de cobro o percepción de tributos, están obligados a mantener reserva o confidencialidad sobre tales hechos en los términos previstos en este Código; y,

2) La violación de lo prescrito en esta norma debe ser sancionada de conformidad con lo dispuesto en el Código Penal.','73','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":73,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"d25518a9244877d03f87441a3530ca7f1eff654fc8675c799502d92f911c4492","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a73","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','73','d25518a9244877d03f87441a3530ca7f1eff654fc8675c799502d92f911c4492','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:74','mayalex_normativos','08_TRIBUTARIO','OBLIGACIÓN DE PRESENTAR DECLARACIONES Y ENTERAR TRIBUTOS.

1) Las cantidades percibidas por los agentes retenedores o perceptores deben enterarse a la Tesorería General de la República (TGR) o a la institución bancaria que la Secretaría de Estado en el Despacho de Finanzas (SEFIN) haya facultado para el efecto, dentro de los plazos señalados en las leyes tributarias o aduaneras especiales y en los formularios que determine la Administración Tributaria o la Administración Aduanera, según corresponda; y,

2) Al realizar el entero a que se refiere el numeral anterior, el agente retenedor debe presentar una Declaración Jurada de las operaciones realizadas, en la forma que para el efecto determine la Ley.','74','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":74,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"28289c5f3addad8c53e1d22b174dedc7fad3956151c9587cf4e53427d4494515","ubicacion":["SECCIÓN CUARTA","OBLIGACIONES DE LOS AGENTES RETENEDORES O PERCEPTORES"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a74","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','74','28289c5f3addad8c53e1d22b174dedc7fad3956151c9587cf4e53427d4494515','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:75','mayalex_normativos','08_TRIBUTARIO','OBLIGACIÓN DE ENTREGAR DOCUMENTOS FISCALES. Los agentes de retención o percepción están obligados a dar a cada obligado tributario un documento fiscal de la suma retenida en concepto de tributo, de conformidad con los requerimientos del marco legal vigente aplicable.','75','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":75,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"bc22d3e012ea136b6daa975683e3de2d60f9845d0294e04789eb28446cd1354c","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a75","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','75','bc22d3e012ea136b6daa975683e3de2d60f9845d0294e04789eb28446cd1354c','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:76','mayalex_normativos','08_TRIBUTARIO','OBJETO DE LAS ACTUACIONES Y PROCEDIMIENTOS. Las actuaciones o procedimientos contenidos en este Título tienen como objeto facilitara los obligados tributarios el cumplimiento voluntario de sus obligaciones tributarias, verificar su correcto cumplimiento o exigirlo cuando no se haya realizado o lo haya sido en forma incompleta o incorrecta.','76','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":76,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"41ac6912f75ba6087b109d9ed38bc1d63050ce02698a991251bc7e80f0cd60a9","ubicacion":["TÍTULO CUARTO","ACTUACIONES Y PROCEDIMIENTOS EN MATERIA TRIBUTARIA OADUANERA","CAPÍTULO I","DISPOSICIONES GENERALES SECCIÓN PRIMERA","DISPOSICIONES PRELIMINARES"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a76","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','76','41ac6912f75ba6087b109d9ed38bc1d63050ce02698a991251bc7e80f0cd60a9','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:77','mayalex_normativos','08_TRIBUTARIO','VERIFICACIÓN O FISCALIZACIÓN DE LOS DATOS Y HECHOS CONSIGNADOS. Los datos y hechos consignados por los obligados tributarios en sus declaraciones y manifestaciones administrativas deben ser objeto de verificación, comprobación o fiscalización por parte de la Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Superintendencia Tributaria Aduanera, la Administración Tributaria o la Administración Aduanera, según el caso, de acuerdo con los procedimientos establecidos en el marco legal vigente aplicable.','77','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":77,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"c9272c16bd75e9f5b4e724bb3c136809b2efc9d437e91586c246db5e74012688","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a77","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','77','c9272c16bd75e9f5b4e724bb3c136809b2efc9d437e91586c246db5e74012688','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:78','mayalex_normativos','08_TRIBUTARIO','EXIGIBILIDAD Y UNIDAD DE LA OBLIGACIÓN TRIBUTARIA O ADUANERA.

1) Las obligaciones tributarias o aduaneras son exigibles por la vía administrativa a partir del día siguiente a aquel en que termine el plazo o término legal para pagar; y,

2) La deuda u obligación tributaria o aduanera, según el caso, es una sola, no importando que la cosa debida sea fraccionable o que sean dos (2) o más los obligados tributarios.','78','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":78,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"926208c4e2c24226966ab50476eae3ea150f30b5614011a1a5d7aea126269b89","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a78","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','78','926208c4e2c24226966ab50476eae3ea150f30b5614011a1a5d7aea126269b89','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:79','mayalex_normativos','08_TRIBUTARIO','ACCESO A LAS ACTUACIONES. Los interesados tienen acceso a las actuaciones administrativas y pueden consultarlas y obtener a su costa copias o fotografía de los documentos contenidos en el expediente instruido sin más exigencia que la justificación de su identidad y legitimación, excepto cuando se trate de actuaciones de comprobación, fiscalización e investigación y éstas no estén concluidas, en tal caso, tendrán acceso al expediente después de la conclusión de dichas actuaciones mediante resolución, para que puedan ejercer su derecho de defensa o bien cumplir con la adecuada aplicación de los tributos, salvo en los casos de investigaciones remitidas por la Secretaría de Estado en el Despacho de Finanzas (SEFIN), Superintendencia Tributaria Aduanera, Administración Tributaria o Administración Aduanera a otras autoridades administrativas y sin perjuicio de los derechos del obligado tributario en el proceso de fiscalización.','79','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":79,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"2db8ca570bf93b36b9ff02886bea0d4b2b570ed8fdf001aa998e462e0a76cccd","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a79","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','79','2db8ca570bf93b36b9ff02886bea0d4b2b570ed8fdf001aa998e462e0a76cccd','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:80','mayalex_normativos','08_TRIBUTARIO','MEDIDAS PARA MEJOR PROVEER.

1) La autoridad competente debe impulsar de oficio el procedimiento. En cualquier estado del trámite puede disponer de medidas para el mejor proveer, en cuyo caso se debe suspender por un máximo de dos (2) meses el cómputo de los plazos administrativos para la conclusión del trámite correspondiente, sin posibilidad de dictar una nueva suspensión, con excepción de los plazos especiales que contiene el presente Código;

2) En el caso de los trámites relacionados con el régimen de imprentas y facturación, operaciones aduaneras u otras relacionadas con la operatividad ordinaria de los obligados tributarios o aquellas en que la Secretaría de Estado en el Despacho de Finanzas (SEFIN), Superintendencia Tributaria Aduanera, Administración Tributaria o Administración Aduanera, según el caso, deben resolver de plano sin tramitación alguna, no corresponde la autorización de medidas para mejor proveer; y,

3) Ningún órgano de la Secretaría de Estado en el Despacho de Finanzas (SEFIN), de la Superintendencia de la Administración Tributaria Aduanera, de la Administración Tributaria o de la Administración Aduanera, debe exigir de los particulares documentos o información para acreditar extremos, hechos o actos que consten o deban constar en sus propios registros o archivos o los que existan en otras entidades de la Administración Pública.','80','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":80,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"12db641c5c7c6496e6591e78868b44e42b9b9cf9e372b83fa5d226e3cf774c7f","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a80","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','80','12db641c5c7c6496e6591e78868b44e42b9b9cf9e372b83fa5d226e3cf774c7f','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:81','mayalex_normativos','08_TRIBUTARIO','TIEMPO DE LAS ACTUACIONES.

1) La Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Superintendencia Tributaria Aduanera, la Administración Tributaria y la Administración Aduanera, deben cumplir sus obligaciones legales y reglamentarias en días y horas hábiles. Sin embargo, pueden habilitar horas y días inhábiles o continuar en horas o días inhábiles una diligencia iniciada en horas y días hábiles;

2) La habilitación de días y horas inhábiles debe ser decretada mediante Acuerdo debidamente motivado por el titular de la institución, el cual debe ser notificado al afectado, previo a ejecutar cualquier actuación al amparo del mismo; y,

3) Bajo ninguna circunstancia pueden decretarse habilitaciones en días y horas inhábiles de forma general, exceptuando aquellos casos en que la Secretaría de Estado en el Despacho de Finanzas (SEFIN), Administración Tributaria o Administración Aduanera, en el cumplimiento de sus funciones de fiscalización, tenga contemplado la realización de programas, operativos, inspecciones, verificaciones y comprobaciones masivas. En estos casos excepcionales la habilitación debe durar el período comprendido para la ejecución de dichas actividades y no puede exceder de tres (3) meses.','81','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":81,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"58f6775c1d4fa125f6fb6e08c32c6751a20d3475bdb550146501bfd9d9e5d6ad","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a81","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','81','58f6775c1d4fa125f6fb6e08c32c6751a20d3475bdb550146501bfd9d9e5d6ad','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:82','mayalex_normativos','08_TRIBUTARIO','UTILIZACIÓN DE TECNOLOGÍAS ELECTRÓNICAS, INFORMÁTICAS Y TELEMÁTICAS.

1) La Secretaría de Estado en el Despacho de Finanzas (SEFIN), Superintendencia Tributaria Aduanera, Administración Tributaria o Administración Aduanera debe priorizar la utilización de las técnicas y medios electrónicos, informáticos y telemáticos necesarios para el desarrollo de sus actividades y el ejercicio de sus competencias, atribuciones y facultades, con las limitaciones que las leyes establezcan; y,

2) Las actuaciones y procedimientos en los que se utilicen técnicas y medios electrónicos, informáticos y telemáticos deben garantizar la identificación de los obligados tributarios y de los servidores públicos u órganos de las referidas instituciones; y,

3) En todo caso las relacionadas instituciones deben dar a conocer al obligado tributario de las tecnologías electrónicas, informáticas y telemáticas que se utilizan y en caso de no hacerlo la información electrónica no puede ser utilizada en contra de éste.','82','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":82,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"6e946b96c6539a0b3238957f1e53e054145ccc82a34dd6ee5a8120afb31b171c","ubicacion":[],"constancias":[{"nota":12,"tipo":"FE_DE_ERRATAS","texto":"Artículo 82. Numeral 3) Se corrige la palabra “debe” por la palabra “deben”. Mediante Fe de Errata publicada en el Diario Oficial La Gaceta No.34,347 de fecha 25 de mayo de 2017.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a82","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','82','6e946b96c6539a0b3238957f1e53e054145ccc82a34dd6ee5a8120afb31b171c','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:83','mayalex_normativos','08_TRIBUTARIO','EQUIVALENCIA DE SOPORTES DOCUMENTALES.

1) Los documentos emitidos, cualquiera que sea su soporte, por medios electrónicos, informáticos o telemáticos por la Secretaría de Estado en el Despacho de Finanzas (SEFIN), Superintendencia Tributaria Aduanera, Administración Tributaria o Administración Aduanera o los que éstas emitan como copias de originales almacenados por estos mismos medios, así como las imágenes electrónicas de los documentos originales o sus copias, tienen la misma validez y eficacia que los documentos originales, siempre que quede garantizada su autenticidad, integridad y conservación y, en su caso, la recepción por el interesado, así como el cumplimiento de las garantías y requisitos exigidos por la normativa aplicable;

2) Los documentos impresos generados por medios electrónicos, deben garantizar su autenticidad e integridad mediante un código de seguridad de verificación. Los documentos emitidos en papel por medios electrónicos, informáticos o telemáticos pueden garantizar su autenticidad e integridad mediante firma electrónica, generados y vinculados a su autor, que, en su caso, permitan constatar su contenido accediendo por medios telemáticos a los archivos del órgano u organismo emisor;

3) Cuando al tiempo de emitir el documento en papel el sistema de información genere un documento con el mismo contenido en soporte electrónico, ambos tienen la condición de originales;

4) La Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Superintendencia Tributaria Aduanera, la Administración Tributaria y la Administración Aduanera, pueden obtener imágenes electrónicas de sus propios documentos, con su misma validez y eficacia, a través de procesos de digitalización que garanticen su autenticidad, la integridad y conservación del documento imagen, dejando constancia de ello. En tal caso, puede ser destruido el documento origen, salvo que una norma legal o reglamentaria imponga un específico deber de conservación;

5) La Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Superintendencia Tributaria Aduanera, la Administración Tributaria o la Administración Aduanera, pueden expedir copias en papel de cualquier clase de documento electrónico, ya sea original o de una imagen electrónica de un original;

6) En los procedimientos tributarios o aduaneros, los expedientes administrativos pueden tener carácter electrónico o físico, siempre que los documentos y archivos que los integren reúnan las características necesarias para su validez y eficacia. En dichos expedientes pueden incorporarse archivos con grabaciones de conversaciones o vídeos, consentidas por los intervinientes o con grabaciones de imágenes lícitamente obtenidas. Toda esta información, junto con sus soportes, no puede ser utilizada más que para los fines de los procedimientos que individualmente se tramiten;

7) Los expedientes administrativos en que se integren las actuaciones y procedimientos tributarios o aduaneros pueden documentarse en soporte papel o electrónico utilizando, en este último caso, tecnologías informáticas o telemáticas con las condiciones establecidas por Ley. La remisión de expedientes prevista en la normativa tributaria o aduanera puede ser sustituida por la puesta a disposición del expediente electrónico; y,

8) La Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Superintendencia Tributaria Aduanera, la Administración Tributaria o la Administración Aduanera, pueden adoptar cualquier otro método tecnológico que permita verificar la autenticidad e integridad de un documento electrónico.','83','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":83,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"31a60f0055b61d95db374353f4514f9bbe3b2acf0e6b33916eea64f6daa2d454","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a83","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','83','31a60f0055b61d95db374353f4514f9bbe3b2acf0e6b33916eea64f6daa2d454','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:84','mayalex_normativos','08_TRIBUTARIO','BUZÓN ELECTRÓNICO.

1) Créase el buzón electrónico como herramienta tecnológica con carácter permanente, el cual debe sustituir al domicilio tributario como lugar para recibir notificaciones y realizar cualquier actividad relacionada en materia tributaria o aduanera por todos los obligados tributarios que se registren al mismo. Para estos casos, la autoridad competente debe implementar un sistema razonable de alertas electrónicas de la existencia de una notificación;

2) El buzón electrónico se debe utilizar para la recepción o envío de solicitudes, escritos, autos, notificaciones, requerimientos y cualquier otro proveído, comunicaciones y resoluciones que se transmitan por medios telemáticos, con sujeción a los mismos requisitos establecidos para el resto de los trámites administrativos. El buzón electrónico debe cumplir con los criterios de disponibilidad, autenticidad, integridad, confidencialidad y conservación de la información que igualmente se señalen en la citada norma;

3) El buzón electrónico debe estar habilitado todos los días del año durante las veinticuatro (24) horas. A efectos de cómputo de plazos, una actuación celebrada en un día inhábil, para el órgano, entidad u obligado tributario, se debe entender efectuada en el primer día hábil siguiente;

4) La presentación de documentos electrónicos en el citado buzón, tiene idénticos efectos que la efectuada por los demás medios admitidos y tiene carácter obligatorio de acuerdo con lo dispuesto en el presente Código;

5) La Administración Tributaria debe administrar y controlar la totalidad del proceso informático que requiere el buzón electrónico. El buzón electrónico debe implementarse bajo el sistema de dominio propio; y,

6) En caso que por motivos técnicos el buzón electrónico quede fuera de servicio o no se le anexe la información correspondiente, se debe ampliar el plazo de un día hábil más contados a partir del día que se restableció el sistema, evento que debe constar en el expediente de cada interesado.','84','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":84,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"2d33d5800b39ad205cd6c965289f52fbea9a4d760e9ecad5ee60592f09e99f0b","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a84","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','84','2d33d5800b39ad205cd6c965289f52fbea9a4d760e9ecad5ee60592f09e99f0b','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:85','mayalex_normativos','08_TRIBUTARIO','USOS DE MEDIOS ELECTRÓNICOS EN LA SECRETARÍA DE ESTADO EN EL DESPACHO DE FINANZAS, LA SUPERINTENDENCIA TRIBUTARIA ADUANERA Y LA ADMINISTRACIÓN ADUANERA. Las disposiciones contenidas en la presente Sección, son aplicables a la Secretaría de Estado en el Despacho de Finanzas (SEFIN), a la Superintendencia Tributaria Aduanera y a la Administración Aduanera, según corresponda en el ámbito de sus competencias.','85','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":85,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"48658a3f20aeb641047fd0c4628760765f09fe4b05691c4b00a18ff0504554ef","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a85","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','85','48658a3f20aeb641047fd0c4628760765f09fe4b05691c4b00a18ff0504554ef','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:86','mayalex_normativos','08_TRIBUTARIO','PETICIONES.

1) Los obligados tributarios pueden ejercer el derecho de petición ante la Secretaría de Estado en el Despacho de Finanzas (SEFIN), Superintendencia Tributaria Aduanera, Administración Tributaria o Administración Aduanera, según corresponda, sobre la aplicación o no del derecho a una situación concreta;

2) A este efecto, el peticionario debe exponer y acreditar con claridad y precisión todas las circunstancias, antecedentes y demás datos constitutivos de la situación que motiva la petición;

3) La presentación de la petición no suspende el deber de cumplimiento de las obligaciones tributarias o aduaneras correspondientes;

4) Las peticiones que no se puedan resolver de plano o de mero trámite, entendiéndose como tales aquellas cuya tramitación legal quede terminada o decidida con la primera providencia que se dicte, la Administración Tributaria, la Administración Aduanera o la Secretaría de Estado en el Despacho de Finanzas (SEFIN), según corresponda, disponen de un plazo máximo de sesenta (60) días hábiles contados a partir de la presentación de la misma, salvo que la complejidad de la petición amerite una ampliación por un plazo máximo de treinta (30) días. Cuando el atraso se deba a causas imputables al obligado tributario, los plazos anteriores se deben suspender hasta tanto se complemente la petición en los plazos establecidos en este Código, sin perjuicio de la facultad de caducar la instancia correspondiente. El efecto de la respuesta cubre al caso concreto peticionado;

5) Las peticiones que no se resuelvan dentro de los términos establecidos por este Código o las leyes tributarias o aduaneras especiales, se entienden falladas en contra del peticionario;

6) Para acreditar el extremo del numeral anterior, basta con que se presente para su aplicación o ejecución, el escrito o solicitud inicial de la gestión de que se trate, con la evidencia de la fecha de presentación oficial del referido escrito o solicitud; y,

7) Los daños y perjuicios debidamente acreditados que el silencio administrativo negativo o la omisión causaren al obligado tributario, correrán a cuenta del Estado y solidariamente del servidor o servidores públicos negligentes directamente involucrados. Los daños y perjuicios se deben exigir por medio de la vía judicial civil correspondiente, previo al reclamo administrativo contenido en la Ley.','86','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":86,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"99a8518f2b11ac5e5bace45be04ce36fd7d316647989f1ab403088caf49ecc59","ubicacion":["SECCIÓN SEGUNDA","PETICIONES"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a86","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','86','99a8518f2b11ac5e5bace45be04ce36fd7d316647989f1ab403088caf49ecc59','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:87','mayalex_normativos','08_TRIBUTARIO','REQUERIMIENTOS Y PLAZOS.

1) Cuando la norma tributaria o aduanera no establezca los plazos para presentar comunicaciones y demás documentos, la Secretaría de Estado en el Despacho de Finanzas (SEFIN), Superintendencia Tributaria Aduanera, la Administración Tributaria o Administración Aduanera, según corresponda, debe exigir la presentación de los mismos, en un plazo máximo de diez (10) días hábiles;

2) La Secretaría de Estado en el Despacho de Finanzas (SEFIN), Superintendencia Tributaria Aduanera, Administración Tributaria o Administración Aduanera, según corresponda, en los procesos de verificación, comprobación y fiscalización, debe otorgar a los obligados tributarios un plazo de cinco (5) días hábiles para atender los requerimientos de información que no hayan sido incluidos en el requerimiento inicial; y,

3) Cuando los obligados tributarios tengan la obligación de presentar comunicaciones y demás documentos y no lo hagan dentro de los plazos señalados en las normas tributarias o aduaneras, sin perjuicio de las sanciones correspondientes por la presentación extemporánea, la Administración Tributaria, la Administración Aduanera o la Secretaría de Estado en el Despacho de Finanzas (SEFIN), según corresponda, debe exigir la presentación de los mismos, en un plazo máximo de cinco (5) días hábiles.','87','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":87,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"f77d1d64506c36e794953e8662fe1b83f00f5dd26c7130c2a4389bfbddc49ee7","ubicacion":["SECCIÓN TERCERA","REQUERIMIENTOS Y NOTIFICACIONES"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a87","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','87','f77d1d64506c36e794953e8662fe1b83f00f5dd26c7130c2a4389bfbddc49ee7','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:88','mayalex_normativos','08_TRIBUTARIO','NOTIFICACIONES.

1) Se debe notificar a los interesados las resoluciones y actuaciones que afecten o favorezcan los derechos e intereses del obligado tributario;

2) Toda notificación debe contener:

a) El texto íntegro de la resolución o la descripción de la actuación en materia tributaria o aduanera;

b) La indicación si la resolución es o no definitiva, en la vía administrativa;

c) La expresión de los recursos que procedan para las resoluciones y la base legal para las actuaciones en materia tributaria o aduanera; y, d) El órgano ante el que deben de presentarse los recursos que procedan a las resoluciones y el plazo para interponerlos.

En las notificaciones no es admisible ni debe consignarse respuesta alguna del interesado, a no ser que así se hubiera mandado.

3) Las notificaciones defectuosas surtirán efecto a partir de la fecha en que se haga la manifestación expresa de tal sentido por el notificado o se interponga el recurso procedente siempre y cuando la misma cumpla con el requisito establecido en el literal a) del numeral anterior. En caso de omisión del referido requisito, la notificación es anulable de pleno derecho, pudiendo rectificarse de oficio o a petición de parte.

Los incidentes que se susciten en los procedimientos que se refieren a la nulidad de actuaciones, salvo en los casos en que dicho incidente se refiera a la omisión del literal
a) del numeral anterior no suspenderá el curso del procedimiento;

4) Las notificaciones se deben practicar por cualquier medio que permita tener constancia de la recepción por el Obligado Tributario, Representante Legal o Procesal o apoderado legal, o cualquier empleado, así como de la fecha, la identidad del notificado y el contenido de la resolución o actuación tributaria puesta en conocimiento. De la notificación se debe dejar constancia en el expediente; y,

5) Los plazos deben empezar a correr a partir del día hábil siguiente al que se tenga por realizada la notificación, independientemente del medio utilizado.','88','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":88,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"fdacf9b840439881d5ec67bd33dc6a7558b39d910599bf1063b4ccaeb393764a","ubicacion":[],"constancias":[{"nota":13,"tipo":"REFORMA","texto":"Artículo 88. Numerales 3) 4) y 5) reformados mediante Decreto No.180-2020 de fecha 22 de diciembre de 2020 y publicado en el Diario Oficial La Gaceta No.35,471 de fecha 28 de diciembre de 2020.","decretos":["180-2020"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a88","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','88','fdacf9b840439881d5ec67bd33dc6a7558b39d910599bf1063b4ccaeb393764a','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:89','mayalex_normativos','08_TRIBUTARIO','FORMAS. Las notificaciones se deben efectuar por cualquiera de los medios siguientes:

1) Personalmente o a la persona debidamente facultada;

2) Por sistemas de comunicación electrónicos o telemáticos, incluyendo el buzón electrónico a través del Portal de la Administración Tributaria, debiendo en estos casos dejarse constancia fidedigna de la recepción de la comunicación remitida;

3) Mediante correo público o privado, con acuse de recibo, remitido al domicilio tributario o al lugar expresamente indicado por el obligado tributario para recibir notificaciones; y,

4) Por la tabla de avisos física y electrónica o por la publicación en uno de los diarios de mayor circulación en el país.','89','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":89,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"724426cf8b16ae28759ed0103b061e6c5fd4606e5e146c2f75db87e4fa5ef707","ubicacion":[],"constancias":[{"nota":14,"tipo":"REFORMA","texto":"Artículo 89. Reformado mediante Decreto No.180-2020 de fecha 22 de diciembre de 2020 y publicado en el Diario Oficial La Gaceta No.35,471 de fecha 28 de diciembre de 2020.","decretos":["180-2020"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a89","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','89','724426cf8b16ae28759ed0103b061e6c5fd4606e5e146c2f75db87e4fa5ef707','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:90','mayalex_normativos','08_TRIBUTARIO','NOTIFICACIÓN PERSONAL.

1) La notificación personal se debe hacer mediante la entrega de la copia íntegra del acto administrativo al Obligado Tributario, al Representante Legal o su Apoderado Legal en el domicilio tributario o en las oficinas de la Administración Tributaria, Administración Aduanera, la Secretaría de Estado en el Despacho de Finanzas (SEFIN), y la Superintendencia Tributaria y Aduanera, según corresponda; asimismo podrá efectuarse la entrega del acto administrativo en el domicilio fiscal o familiar del Obligado Tributario, el Representante Legal o Apoderado Legal;

2) Cuando el Obligado Tributario, Representante Legal, Apoderado Legal, estando presentes en la entrega del acto administrativo, se negaren a firmar la constancia respectiva, se debe de practicar la notificación fijándose ésta en un lugar visible en el domicilio tributario, dejando los documentos en sobre cerrado, debiendo levantar acta de tal diligencia. En los casos en que el Obligado Tributario, su Representante Legal o

Apoderado Legal, se presentaren a las oficinas de la Administración Tributaria, Administración Aduanera, la Secretaría de Estado en el Despacho de Finanzas (SEFIN), y la Superintendencia Tributaria y Aduanera, según corresponda y se negaren a notificarse del acto administrativo, se levantará acta de tal diligencia dejándose constancia de ello en el expediente, surtiendo efectos la notificación;

3) En los casos en que se ejerzan las facultades de verificación de cumplimiento de obligaciones tributaras mediante operativos o controles extensivos, la notificación personal podrá hacerse al Representante Legal, Apoderado Legal, responsable o persona encargada del establecimiento en el cual se hubiere de realizar la actuación.','90','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":90,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"6d2d074a78c9f6425b479ea46252c951a8b1fb48435a3665c0a264d701cbdd2b","ubicacion":[],"constancias":[{"nota":15,"tipo":"REFORMA","texto":"Artículo 90. Reformado mediante Decreto No.180-2020 de fecha 22 de diciembre de 2020 y publicado en el Diario Oficial La Gaceta No.35,471 de fecha 28 de diciembre de 2020.","decretos":["180-2020"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a90","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','90','6d2d074a78c9f6425b479ea46252c951a8b1fb48435a3665c0a264d701cbdd2b','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:91','mayalex_normativos','08_TRIBUTARIO','NOTIFICACIÓN POR SISTEMAS ELECTRÓNICOS O TELE- MÁTICOS.

1) La Secretaría de Estado en el Despacho de Finanzas (SEFIN), Superintendencia Tributaria Aduanera, la Administración Tributaria y la Administración Aduanera, según corresponda, pueden efectuar las notificaciones por sistemas de comunicación electrónicos o telemáticos, incluyendo el buzón electrónico a través del Portal de la Administración Tributaria, identificando plenamente al remitente y destinatario de la notificación; Para estos efectos, las referidas instituciones deben realizar la notificación bajo una de las modalidades de firma electrónica incluyendo la firma equivalente de conformidad a lo establecido en la Ley de Firma Electrónica y sus reformas en el Decreto No.33-2020, así como en los reglamentos correspondientes;

2) Las notificaciones practicadas por sistemas de comunicación electrónicos o telemáticos tienen los mismos efectos legales que las realizadas personalmente y deben ser realizadas por el titular de la Secretaría General o por las personas a quien expresamente, mediante Acuerdo, se le hayan delegado esas funciones, debiendo consignarse así en el acto de la notificación por vía electrónica o telemática;

3) Para que las notificaciones se practiquen utilizando sistemas de comunicación electrónicos o telemáticos basta solamente con remitir la notificación al correo electrónico señalado por el Obligado Tributario, su Representante Legal o Apoderado Legal a través de los métodos o medios que para tal efecto disponga la Administración Tributaria, Administración Aduanera, la Secretaria de Estado en el Despacho de Finanzas (SEFIN), y la Superintendencia Tributaria y Aduanera, según corresponda. A la notificación deberá adjuntarse el acto administrativo que está siendo objeto de notificación; la notificación surtirá efectos el mismo día en que fue remitido el acto administrativo por medio electrónico o telemático;

4) En caso de haber cambio de correo electrónico del Obligado Tributario, este deberá ser notificado inmediatamente a la Administración Tributaria, la Administración Aduanera, la Secretará de Estado en el Despacho de Finanzas (SEFIN), y la Superintendencia Tributaria y Aduanera, a través de los métodos o medios que dichas Administraciones dispongan. En caso que el Obligado Tributario, su Representante Legal o Apoderado Legal no notifiquen el cambio, el correo vigente para efectos de notificación será el último que se encuentre registrado o señalado al momento de efectuar la notificación del acto administrativo; y,

5) En caso de notificaciones por medios electrónicos, debe dejarse en el expediente constancia fehaciente de haberse enviado la notificación, de su contenido y la fecha de la misma.','91','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":91,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"e79f10b49e341ae6c3546e0b96378dcdd0e911613875c526c33525bafa0f26d7","ubicacion":[],"constancias":[{"nota":16,"tipo":"REFORMA","texto":"Artículo 91. Reformado mediante Decreto No.180-2020 de fecha 22 de diciembre de 2020 y publicado en el Diario Oficial La Gaceta No. 35,471 de fecha 28 de diciembre de 2020.","decretos":["180-2020"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a91","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','91','e79f10b49e341ae6c3546e0b96378dcdd0e911613875c526c33525bafa0f26d7','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:92','mayalex_normativos','08_TRIBUTARIO','NOTIFICACIÓN MEDIANTE CORREO PÚBLICO O PRIVADO CERTIFICADO. La notificación por correo público o privado certificado se hará mediante la entrega de un sobre cerrado y sellado que debe contener la copia íntegra de la resolución o del documento que debe ser puesto en conocimiento del interesado, haciéndose constar por escrito dicha diligencia, con constancia de la recepción e indicación del día, hora y lugar en que se haya practicado la referida entrega.','92','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":92,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"57bc50e713c957993586722aaf420e3dda19c15759b1265916b8db6743156f8b","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a92","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','92','57bc50e713c957993586722aaf420e3dda19c15759b1265916b8db6743156f8b','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:93','mayalex_normativos','08_TRIBUTARIO','NOTIFICACIÓN POR TABLA DE AVISOS FÍSICA Y ELECTRÓNICA O PUBLICACIÓN EN UN DIARIO DE MAYOR CIRCULACIÓN.

1) Para efectos de lo dispuesto en el presente Código, la notificación por tabla de avisos física y electrónica se debe hacer únicamente en aquellos casos en que no haya sido posible efectuar al menos una vez la notificación personal o por medios electrónicos o telemáticos del acto o actuación tributaria o aduanera.

2) Las notificaciones por el medio anterior se deben hacer fijando durante cinco (5) días hábiles el documento que se pretenda notificar en un sitio abierto al público de las oficinas de la Secretaria de Estado en el Despacho de Finanzas (SEFIN), Superintendencia Tributaria Aduanera, la Administración Tributaria y la Administración Aduanera, según corresponda; la notificación surtirá efectos a partir del día en que se fijó el documento en la tabla de avisos física y electrónica; y,

3) La notificación del acto administrativo mediante publicación en un diario de mayor circulación se deberá hacer por una vez, surtiendo efecto la notificación el día en que se efectúo la publicación.','93','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":93,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"005d9c88ac72236be2a2f33119fcd4ec125a8e4be3bfea4b69a73d12490e6af5","ubicacion":[],"constancias":[{"nota":17,"tipo":"REFORMA","texto":"Artículo 93. Reformado mediante Decreto No.180-2020 de fecha 22 de diciembre de 2020 y publicado en el Diario Oficial La Gaceta No.35,471 de fecha 28 de diciembre de 2020.","decretos":["180-2020"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a93","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','93','005d9c88ac72236be2a2f33119fcd4ec125a8e4be3bfea4b69a73d12490e6af5','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:94','mayalex_normativos','08_TRIBUTARIO','PRINCIPIOS Y NORMAS APLICABLES A LA PRUEBA. Todos los principios, medios y procedimientos relacionados con los medios de prueba se deben sujetarse a las normas de la Ley de Procedimiento Administrativo y, supletoriamente, el Libro Segundo Código Procesal Civil.','94','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":94,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"437ef3d5f84ccbcab2ff60959677d3b95385e0a96dd5c1c97ad2a81a1af42031","ubicacion":["SECCIÓN CUARTA","PRUEBA"],"constancias":[{"nota":18,"tipo":"FE_DE_ERRATAS","texto":"Artículo 94. Se corrigen las palabras “deben sujetan” por las palabras “deben sujetarse”. Mediante Fe de Errata publicada en el Diario Oficial La Gaceta No.34,347 de fecha 25 de mayo de 2017.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a94","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','94','437ef3d5f84ccbcab2ff60959677d3b95385e0a96dd5c1c97ad2a81a1af42031','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:95','mayalex_normativos','08_TRIBUTARIO','ADMISIÓN Y VALORACIÓN DE LA PRUEBA.

1) Son admisibles todos los medios de prueba reconocidos por el derecho hondureño, siempre y cuando los mismos sean presentados en los términos y plazos establecidos en el presente Código, la Ley de Procedimiento Administrativo y en el Código Procesal Civil, este último de forma supletoria;

2) No son admisibles en la tramitación del recurso correspondiente medios probatorios que habiendo sido requeridos por la Administración Tributaria, Administración Aduanera o la Secretaría de Estado en el Despacho de Finanzas (SEFIN), durante el proceso de verificación, determinación o fiscalización, no se hayan presentado en el plazo legal para la discusión de ajustes, salvo por causas ajenas a la voluntad del requerido debidamente justificadas y documentadas;

3) La Secretaría de Estado en el Despacho de Finanzas (SEFIN), la superintendencia Tributaria Aduanera, la Administración Tributaria y la Administración Aduanera, deben admitir todos los medios de pruebas propuestos por los obligados tributarios, con excepción de lo dispuesto en el numeral anterior, debiendo motivar y valorar en su resolución cada uno de los medios de pruebas presentados y admitidos en el proceso;

4) Los documentos, libros y registros contables constituyen elementos de prueba, siempre y cuando se lleven en legal y debida forma, reflejando fielmente la situación financiera. No obstante, las referidas instituciones pueden objetar el contenido de la contabilidad mediante otros elementos de prueba externos a ésta, sin perjuicio del derecho del obligado tributario para impugnar la objeción que le realice; y,

5) La prueba se debe apreciar y valorar excluyendo en todo caso la arbitrariedad, conforme a la regla de la sana crítica, del conocimiento y criterio humano, así como de las normas que rigen el razonamiento lógico.','95','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":95,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"e83711937be64a5f4e7e8d228895b4253a8448a606e26d0c633481ab3d43dcc8","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a95","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','95','e83711937be64a5f4e7e8d228895b4253a8448a606e26d0c633481ab3d43dcc8','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:96','mayalex_normativos','08_TRIBUTARIO','PERÍODO PROBATORIO.

1) Salvo que este Código establezca un período o plazo específico para determinados procesos, el período probatorio ordinario y general a que está sujeto un obligado tributario, para la admisión y evacuación de las pruebas es de un (1) mes, contados a partir del día siguiente en que se notifique la providencia que abra el mismo; y,

2) Si el obligado tributario estima no tener que presentar medios probatorios o considera haber evacuado todos los medios necesarios y a su alcance, previo al vencimiento del plazo contenido en el numeral anterior, puede solicitar que se cierre el período probatorio para la continuación de las diligencias correspondientes.','96','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":96,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"7fb753cbb859c1bc07ddc2c500651a11672d67dfb00d2f2a89a91435105b3001","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a96","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','96','7fb753cbb859c1bc07ddc2c500651a11672d67dfb00d2f2a89a91435105b3001','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:97','mayalex_normativos','08_TRIBUTARIO','FUNDAMENTACIÓN DE LAS ACTUACIONES. Los hechos que se conozcan con motivo del ejercicio de las facultades de determinación, fiscalización e Investigación previstas en este Código, bien que consten en los expedientes o documentos que tenga en su poder la Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Superintendencia Tributaria Aduanera, la Administración Tributaria y la Administración Aduanera, sirven como prueba para fundamentar sus resoluciones, sin perjuicio del derecho del obligado tributario para objetar las mismas, mediante los mecanismos establecidos en este Código.','97','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":97,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"2a4cb7d4f8ddbbd41a01cb17dcd3700b7db5181377dae27cb98721f798b40499","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a97","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','97','2a4cb7d4f8ddbbd41a01cb17dcd3700b7db5181377dae27cb98721f798b40499','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:98','mayalex_normativos','08_TRIBUTARIO','ALEGACIONES. Transcurrido el período probatorio, de oficio se abrirá un período de diez (10) días hábiles para que el obligado tributario alegue sobre todo lo actuado y sobre el valor y alcance de las pruebas producidas.','98','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":98,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"1ec15a050af15ea02c8f87d302cc4d2457097860ec18c46caab07578d6d4274f","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a98","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','98','1ec15a050af15ea02c8f87d302cc4d2457097860ec18c46caab07578d6d4274f','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:99','mayalex_normativos','08_TRIBUTARIO','PLAZO PARA DICTAR LA RESOLUCIÓN. Dentro de los veinte (20) días hábiles, contados a partir del día siguiente a la fecha de la providencia que dé por finalizado el período de las alegaciones, se debe emitir la resolución que en Derecho corresponda, la cual debe de resolver todas las cuestiones planteadas en el curso del proceso. La resolución se debe notificar a la mayor brevedad posible, sin que el plazo de la misma exceda los cinco (5) días contados desde la fecha en que se dictó.','99','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":99,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"f3750b78ff2bc59e7322b48fe982f39a46d9fa8a221ae96e59fed7520bcce77f","ubicacion":["SECCIÓN QUINTA","RESOLUCIÓN"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a99","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','99','f3750b78ff2bc59e7322b48fe982f39a46d9fa8a221ae96e59fed7520bcce77f','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:100','mayalex_normativos','08_TRIBUTARIO','REQUISITOS Y CONTENIDO FORMALES DE LA RESOLUCIÓN. Toda resolución que se emita en cualquier procedimiento relacionado en este Código, debe contener, como mínimo, los requisitos siguientes:

1) Debe ser motivada y contener, en párrafos separados y numerados, los antecedentes de hecho y los fundamentos de Derecho en los que se base la parte dispositiva;

2) En el encabezamiento debe expresarse el nombre, denominación o razón social del obligado tributario, incluyendo el número de identificación tributaria, la legitimación y representación en virtud de la que actúe y el nombre del profesional del derecho que lo represente, si así fuera el caso, así como el objeto del procedimiento;

3) Los antecedentes de hecho se deben consignar con claridad y concisión, en párrafos separados y numerados, las pretensiones, los hechos en que las funden y que hayan sido alegados oportunamente, las pruebas propuestas y practicadas, su apreciación y valoración y los hechos probados, en su caso. Cuando se dé el caso, se debe hacer una relación sucinta del contenido del acta de la discusión de ajustes y en particular de las alegaciones y medios de prueba presentados, fundamentando de forma individualizada las imputaciones o cargos que se le formulen;

4) Los fundamentos de derecho deben expresarse en párrafos separados y numerados, los puntos de derecho, las cuestiones controvertidas, dando las razones y fundamentos legales de la resolución que haya de dictarse, con expresión concreta de las normas jurídicas aplicables al caso;

5) La resolución o parte resolutiva debe contener, en párrafo separado y numerado, los pronunciamientos correspondientes a las pretensiones del obligado tributario, aunque la estimación o desestimación de todas o algunas de dichas pretensiones pudiera deducirse de los fundamentos jurídicos. También debe determinarlas cantidades y los conceptos que procedan y correspondan;

6) En caso de tratarse de una determinación de tributos, debe indicar el tributo, período fiscal liquidado, importe adeudado o a devolver y sus elementos determinantes y, en su caso, la sanción a aplicar. En los demás casos, debe expresar el objeto o propósito de la resolución;

7) El carácter parcial de la liquidación, de ser el caso, con indicación de los elementos de la obligación tributaria o aduanera objeto de ésta;

8) Fecha, nombre, cargo y firma autógrafa o electrónica, del servidor público competente, así como los mismos datos de la autoridad que refrende dicha firma; y,

9) Los recursos que procedan contra la resolución, los plazos para interponerlos y el órgano ante el cual deben interponerse.','100','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":100,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"a99c84da8574bad8b1cd5b85e545d09d6c23177f11b66d9a7149d44e6fd58ea2","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a100","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','100','a99c84da8574bad8b1cd5b85e545d09d6c23177f11b66d9a7149d44e6fd58ea2','OLA9_CTRIB_2024_01',now())
