INSERT INTO public.biblioteca_vectores (id,coleccion,materia,contenido,num_articulo,fuente,metadata,embedding,jurisdiccion,fuente_tipo,es_norma_vigente,revision_pendiente,instrumento_id,num_articulo_norm,hash_contenido,ingest_batch,ingested_at) VALUES
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:101','mayalex_normativos','08_TRIBUTARIO','REQUISITOS INTERNOS DE LA RESOLUCIÓN. Toda resolución que se emita conforme a este Código debe reunir los requisitos internos siguientes:

1) La resolución debe ser clara, precisa y exhaustiva;

2) Debe resolver, sin apartarse de la causa y objeto del proceso, conforme a las normas aplicables al caso, aunque no hayan sido acertadamente citadas o alegadas por el obligado tributario;

3) Cuando los puntos en controversia, discusión o debate hayan sido varios, se debe hacer la debida separación del pronunciamiento correspondiente a cada uno de ellos;

4) Se debe motivar expresando los razonamientos fácticos y jurídicos que conducen a la apreciación y valoración de las pruebas, así como a la aplicación del Derecho;

5) La motivación debe incidir en los distintos elementos fácticos y jurídicos del proceso, considerados individualmente y en conjunto, ajustándose siempre a las reglas de la lógica y de la razón;

6) Debe ser congruente con los reclamos y con las demás pretensiones del obligado tributario, deducidas oportunamente en el proceso; y,

7) Se deben incluir los pronunciamientos sobre las declaraciones que se exijan, resolviendo a favor o en contra y decidiendo todos los puntos que hayan sido objeto de controversia.','101','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":101,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"f76dc7251b296dd5cf08fc1c1ae73673740bbeeff3b2c677a5d84eb75aadf08b","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a101","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','101','f76dc7251b296dd5cf08fc1c1ae73673740bbeeff3b2c677a5d84eb75aadf08b','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:102','mayalex_normativos','08_TRIBUTARIO','ANULABILIDAD DE LA RESOLUCIÓN. El incumplimiento de los plazos o el error u omisión de cualquiera de los requisitos enunciados, contenidos en los artículos anteriores, constituyen una infracción de forma y da lugar a la anulabilidad de la resolución emitida y, consecuentemente, a la inaplicabilidad de sus efectos, de conformidad con el Artículo 213 del Código Procesal Civil.','102','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":102,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"248d44628ae679e4b0e46713ed005b281e227450667011f0c4aa951e3d70fd7f","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a102","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','102','248d44628ae679e4b0e46713ed005b281e227450667011f0c4aa951e3d70fd7f','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:103','mayalex_normativos','08_TRIBUTARIO','RECURSOS CONTRA LA RESOLUCIÓN. Los recursos contra las resoluciones relacionados en este Código, se deben regular en las disposiciones específicas para estos actos.','103','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":103,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"073e7da343918630e92bf938c604c1e3af2bd31ab29cfb833719e946d8c9c2b1","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a103","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','103','073e7da343918630e92bf938c604c1e3af2bd31ab29cfb833719e946d8c9c2b1','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:104','mayalex_normativos','08_TRIBUTARIO','CONCEPTOS.

1) HECHO GENERADOR O IMPONIBLE: Es el acto real o supuesto que, de acuerdo con la Ley, tipifica cualquier clase de tributo y cuya realización origina el nacimiento de la obligación tributaria. La Ley debe delimitar el hecho generador mediante la mención de supuestos de no sujeción al tributo, así como establecer supuestos de exención;

2) EL HECHO GENERADOR DE LA OBLIGACIÓN TRIBUTARIA SE CONSIDERA REALIZADO:

a) En las situaciones de hecho, esto es, cuando la Ley tributaria o aduanera respectiva toma en cuenta preferentemente aspectos fácticos o económicos, desde el momento en que se han cumplido las circunstancias materiales o temporales necesarias para que se produzcan los efectos que normalmente le corresponda;

b) En las situaciones jurídicas, desde el momento en que estén definitivamente constituidas de conformidad con el derecho aplicable; y, c) Si el hecho generador fuere un acto jurídico condicionado, se le debe considerar perfeccionado:

i. En el momento de su celebración, si la condición fuere resolutoria;

ii. Al producirse la condición, si ésta fuere suspensiva.

En caso de duda se debe entender que la condición es resolutoria.

3) SUPUESTO DE NO SUJECIÓN: Se produce cuando el hecho realizado por el obligado tributario no se encuentra comprendido en el presupuesto legal que da origen a la obligación tributaria y aduanera; y,

4) SUPUESTO DE EXENCIÓN: A pesar de realizarse el hecho generador, la Ley exime del cumplimiento de la obligación tributaria o aduanera principal.','104','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":104,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"03aaab9f1d1c6f6206ecf1ce7e22e2057324e34f5421b10fbee1442349856bab","ubicacion":["CAPÍTULO II","DEL HECHO GENERADOR O IMPONIBLE DE LA OBLIGACIÓN TRIBUTARIA"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a104","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','104','03aaab9f1d1c6f6206ecf1ce7e22e2057324e34f5421b10fbee1442349856bab','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:105','mayalex_normativos','08_TRIBUTARIO','BASE IMPONIBLE, DETERMINACION Y AUTOLIQUIDACION.

1) La base imponible es la cuantificación del hecho generador expresada en dinero o en unidades específicas y debe servir para el cálculo de la liquidación del tributo;

2) La base imponible debe siempre estar consignada en la Ley, por lo que para su determinación, la Administración Tributaria y la Administración Aduanera, deben fundarse en la realidad económica, en los usos normales y ordinarios de los negocios y en las normas y reglas contables generalmente aceptadas, así como en los principios y buenas prácticas en materia de contabilidad e información financiera. Debe, además, ser proporcional al hecho generador y tener en cuenta la capacidad económica del obligado tributario;

3) La determinación es la realización del acto por el cual se fija el monto que debe pagar el obligado tributario; y,

4) La autoliquidación es el acto que realiza el obligado tributario, o tercero responsable, a través de declaraciones juradas, en las que se fija el importe de los tributos a pagar.','105','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":105,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"98309caae824971cd8228d249ca2f949abb4b405255486cd78ec67a2483d31d8","ubicacion":["CAPITULO III","DE LA BASE IMPONIBLE, FORMAS DE DETERMINACION Y PRESUNCIONES","SECCION PRIMERA","LA BASE IMPONIBLE Y SUS FORMAS DE DETERMINACION"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a105","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','105','98309caae824971cd8228d249ca2f949abb4b405255486cd78ec67a2483d31d8','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:106','mayalex_normativos','08_TRIBUTARIO','FORMAS DE LA DETERMINACIÓN.

1) DETERMINACIÓN POR LA ADMINISTRACIÓN TRIBUTARIA O LA ADMINISTRACIÓN ADUANERA: Llamada también “De Oficio”, esta puede ser:

LIQUIDACIÓN ADMINISTRATIVA: Se ejecuta con base a la información proporcionada por el obligado tributario en las declaraciones determinativas y manifestaciones informativas presentadas, la cual debe proceder a liquidar el monto a ser pagado o sus pagos anticipados, si estos últimos se encuentran establecidos conforme a Ley, sin perjuicio de la fiscalización posterior.

LIQUIDACIÓN MEDIANTE FISCALIZACIÓN: La Administración Tributaria o la Administración Aduanera, mediante fiscalización, en cualquier momento y antes de producirse la prescripción, puede determinar de oficio la obligación tributaria o aduanera correspondiente, considerando los hechos siguientes:

a) SOBRE BASE CIERTA: Tomando en cuenta los documentos e información que permitan conocer en forma directa e indubitable los hechos generadores del tributo y la cuantía del mismo, sirviendo entre otros las declaraciones, libros o registros contables, documentación de soporte y comprobantes que obren en poder del obligado tributario;

b) SOBRE LA BASE DE HECHOS CONEXOS: Con base en los hechos y circunstancias que, por su vinculación o conexión normal con el hecho generador de la obligación, permitan deducir la existencia y cuantía de la obligación tributaria o aduanera; y, c) SOBRE BASE MIXTA: La base mixta es la determinación de la obligación tributaria o aduanera utilizando los métodos anteriores.

2) Sin perjuicio de lo establecido en este Artículo, en materia aduanera se está a lo prescrito en el marco legal especial;

3) Una vez practicada la determinación de oficio sobre la base de hechos conexos, subsiste la responsabilidad sobre las diferencias que resulten de una determinación sobre base cierta respecto de un período fiscal no fiscalizado; y,

4) La Administración Tributaria o la Administración Aduanera, en el marco de las competencias y atribuciones, debe aprobar los Manuales Técnicos conforme a las normas de este Código y leyes tributarias o aduaneras especiales aplicables para cada caso, para definir la metodología necesaria en la Determinación De Oficio de la Obligación Tributaria o Aduanera.

Adicionalmente, dichos manuales deben ser publicados en su portal electrónico.','106','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":106,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"49f5b59ae9482daee3e322167dbaca0f6253ed5a4f9fda38dda682306fbafcfc","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a106","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','106','49f5b59ae9482daee3e322167dbaca0f6253ed5a4f9fda38dda682306fbafcfc','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:107','mayalex_normativos','08_TRIBUTARIO','SUPUESTOS DE DETERMINACIÓN SOBRE LA BASE DE HECHOS CONEXOS. La Administración Tributaria o la Administración Aduanera, deben determinar los tributos sobre la base de hechos conexos cuando los obligados tributarios:

1) Se opongan u obstaculicen la iniciación o desarrollo de sus facultades de fiscalización;

2) No presenten los libros de contabilidad y sus registros, la documentación comprobatoria o no proporcionen los informes relativos al cumplimiento de las normas tributarias o aduaneras; y,

3) No presenten las declaraciones dentro del plazo estipulado en la Ley; o bien, se dé alguna de las siguientes irregularidades:

a) Omisión del registro de operaciones, como ser: ingresos o compras, así como en la alteración del costo y gastos;

b) Registro de compras, gastos o servicios no realizados o no recibidos; y, c) Omisión o alteración en el registro de existencias que deban figurar en los inventarios o registren dichas existencias a precios distintos de los de costo, sin cumplir con los métodos aceptados de valuación de inventarios.','107','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":107,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"5f77dd48f1a735d5249233e88e737b5cd9257ec766bc139b3bf1045808878226","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a107","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','107','5f77dd48f1a735d5249233e88e737b5cd9257ec766bc139b3bf1045808878226','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:108','mayalex_normativos','08_TRIBUTARIO','ELEMENTOS INDICIARIOS PARA LA DETERMINACIÓN SOBRE LA BASE DE HECHOS CONEXOS. Para la determinación de la obligación tributaria sobre la base de hechos conexos se debe considerar:

1) La aplicación de datos, antecedentes y elementos que permitan determinar la existencia de los hechos generadores en su real magnitud;

2) La utilización de aquellos elementos que acrediten la existencia de bienes, rentas, así como de los ingresos, ventas, costos y rendimientos que sean normales en el respectivo sector económico, considerando las características de otras unidades económicas que puedan compararse en términos tributarios o aduaneros; y,

3) La valoración de índices o indicadores que se den entre obligados tributarios con actividades similares o equivalentes.','108','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":108,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"aab242adcabc91d64394e32ce2ffa66c960488c48af0248fe7c44af3310556c0","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a108","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','108','aab242adcabc91d64394e32ce2ffa66c960488c48af0248fe7c44af3310556c0','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:109','mayalex_normativos','08_TRIBUTARIO','DATOS ECONÓMICOS RELEVANTES PARA LA DETERMINACIÓN SOBRE BASE DE HECHOS CONEXOS.

1) Para los efectos del Artículo anterior, la Administración Tributaria o la Administración Aduanera, deben determinar el tributo y las sanciones correspondientes, en función de los elementos conocidos que permitan presumir su existencia y magnitud; y,

2) Para el cumplimiento de lo anterior debe hacerse una reconstrucción contable y de información financiera, que tenga en cuenta lo siguiente:

a) El patrimonio;

b) El activo y pasivo existente;

c) El movimiento de las cuentas en el sistema financiero;

d) Las transacciones hechas en otros períodos fiscales y las utilidades obtenidas;

e) El monto de las compraventas efectuadas;

f) La rentabilidad normal de la actividad que se trate, de otras similares o equivalentes;

g) Las erogaciones hechas;

h) Los salarios pagados o devengados;

i) El valor de los alquileres pagados o pendientes de pago;

j) El nivel de vida del obligado tributario; y, k) Cualesquiera otros elementos de juicio que suministren los agentes de retención y percepción u otros entes públicos o privados o, puedan ser conocidos por la Administración Tributaria o Administración Aduanera, siempre y cuando la información y documentos haya sido obtenida y conocida por los mecanismos y procedimientos legalmente establecidos de investigación o denuncias.','109','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":109,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"4b6ecc5257c6acd71bcf18ba44510c547490a5345c6ffdc83d7d8e2eb4191a30","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a109","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','109','4b6ecc5257c6acd71bcf18ba44510c547490a5345c6ffdc83d7d8e2eb4191a30','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:110','mayalex_normativos','08_TRIBUTARIO','PRESUNCIONES EN LA DETERMINACIÓN DE LA OBLIGACIÓN TRIBUTARIA O ADUANERA. Salvo prueba en contrario, en la determinación de oficio de las obligaciones tributarias o aduaneras sobre la base de hechos conexos o mixtos, a que se refiere este Código, se debe tomar en cuenta:

1) Los ingresos brutos y activos obtenidos o adquiridos durante el período fiscal deben ser estimados conforme a los ingresos brutos y activos obtenidos o adquiridos durante el período fiscal anterior, más las variaciones del Índice Mensual de Actividad Económica y el Índice de Precios al Consumidor por sector de la economía, publicados por el Banco Central de Honduras (BCH). A falta de esta última información, se debe presumir que los ingresos brutos y activos obtenidos o adquiridos durante el período fiscal son iguales a los que haya obtenido o adquirido otro contribuyente dedicado a la misma actividad comparable en cuanto a su capacidad económica. Lo dispuesto en este numeral se entiende como parte de la base para determinar la obligación tributaria o aduanera, por lo que no incluyen las deducciones que las leyes tributarias o aduaneras especiales autoricen.

Para los efectos de la aplicación de lo dispuesto en este numeral, deben considerarse los factores siguientes:

a) El giro mercantil o actividad comercial apropiada del contribuyente;

b) La demanda de los bienes o servicios atendiendo a la o las temporadas en que éstos se solicitan en mayores o menores cantidades; y, c) Seleccionar de manera apropiada los meses en que se debe efectuar el control, de forma tal que refleje la actividad real de los negocios.

2) Los precios de los bienes inmuebles a través de la aplicación de los criterios de valoración que señale el marco legal aplicable;

3) Los incrementos patrimoniales no justificados deben formar parte de la renta durante el período fiscal sujeto a verificación, sin que ello implique una eximente de otras responsabilidades legales que pudieran derivarse de la no justificación de dichos incrementos; y,

4) Las diferencias que existen entre el inventario físico de las mercancías efectuado ya sea por la Administración Tributaria o por la Administración Aduanera y, el inventario que resulte de los registros contables o la confirmación de terceros, deben ser consideradas como ventas omitidas cuando la diferencia sea en menos o como compra omitida cuando la diferencia sea en más.','110','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":110,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"25b9d73eae8c3cab4715e39214a58f99ac6ae19f7c9fea9dc2f9e123d873f547","ubicacion":["SECCIÓN SEGUNDA","PRESUNCIONES SOBRE LA BASE IMPONIBLE"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a110","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','110','25b9d73eae8c3cab4715e39214a58f99ac6ae19f7c9fea9dc2f9e123d873f547','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:111','mayalex_normativos','08_TRIBUTARIO','PRESUNCIONES DE INGRESOS. Para la verificación de los ingresos o del valor de los actos, actividades o activos que formen parte de una obligación tributaria o aduanera, la Administración Tributaria o la Administración Aduanera, según el caso, debe presumir, salvo prueba en contrario, que:

1) La información contenida en la contabilidad, documentación comprobatoria y correspondencia que se encuentren en poder de los obligados tributarios forman parte de operaciones celebradas por ellos, aun cuando aparezcan sin su nombre o a nombre de otra persona, siempre que una de las operaciones o actividades, por lo menos, haya sido realizada por aquéllos;

2) La información contenida en los sistemas de contabilidad a nombre del obligado tributario, que se encuentren en poder de personas a su servicio o de accionistas, partícipes, socios, miembros o propietarios, corresponden a operaciones de éste;

3) Los depósitos que figuren en las cuentas del sistema financiero a nombre del obligado tributario que no correspondan a registros de su contabilidad, son ingresos gravables;

4) Son ingresos del obligado tributario, los depósitos hechos en las cuentas personales del Sistema Financiero de los representantes legales si con ellos efectúan operaciones propias de aquél o depositan en dichas cuentas sumas propias del obligado tributario, aunque éste no los registre en su contabilidad;

5) Las diferencias entre los activos registrados en la contabilidad, inferiores a los reales, corresponden a ingresos del último ejercicio y forman parte de las obligaciones tributarias o aduaneras, según corresponda. Lo dispuesto en este numeral se entiende sin perjuicio de lo establecido en el Artículo 110 numeral 4; y,

6) Los cheques librados, transferencias bancarias u otras formas de transacciones de pago, contra las cuentas del obligado tributario y a favor de proveedores o de quienes le han prestado servicios al mismo, que no corresponden a operaciones registradas en la contabilidad del obligado tributario, son pagos hechos por cuenta de éste para adquirir mercancías o servicios de los que obtuvo ingresos.','111','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":111,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"c4f7d7dfc456f5acd361b6c26fc8cc15f0a7bbdda15bf371557409b567fe1178","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a111","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','111','c4f7d7dfc456f5acd361b6c26fc8cc15f0a7bbdda15bf371557409b567fe1178','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:112','mayalex_normativos','08_TRIBUTARIO','PRESUNCIONES DE INGRESOS Y VALOR EN TERCEROS. Para comprobar los ingresos, así como el valor de los actos de los obligados tributarios, la Administración Tributaria o Administración Aduanera debe presumir, salvo prueba en contrario, que la información o documentos de terceros relacionados con el obligado tributario corresponden a operaciones realizadas por éste cuando:

1) Se refiere al obligado tributario designado por sus nombres, razón o denominación social;

2) Señalen como lugar para la entrega o recibo de bienes o la prestación de servicios relacionados con las actividades del obligado tributario, cualquiera de sus establecimientos aún cuando el nombre, razón o denominación social que figure sea el de un tercero real o ficticio;

3) Señalen el nombre o domicilio de un tercero, real o ficticio, si se comprueba que el obligado tributario entrega o recibe bienes o servicios a ese nombre o en ese domicilio; y,

4) Se refieren a cobros o pagos efectuados por el obligado tributario o por su cuenta, por interpósita persona o por un ente ficticio.','112','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":112,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"96df3fd9dce74115969fa0da57b7eadeb9944caaf0103428aff1e4fce1a04b54","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a112","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','112','96df3fd9dce74115969fa0da57b7eadeb9944caaf0103428aff1e4fce1a04b54','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:113','mayalex_normativos','08_TRIBUTARIO','PRECIOS DE TRANSFERENCIA.

1) La Administración Tributaria o la Administración Aduanera, según el caso, para la determinación de las obligaciones tributarias, de acuerdo con la Ley para la Regulación de Precios de Transferencia, debe verificar la existencia de precios de transferencia en las operaciones realizadas entre personas naturales o jurídicas domiciliadas o residentes en Honduras con sus partes relacionadas, vinculadas o asociadas y aquellas amparadas en regímenes especiales que gocen de beneficios fiscales; y,

2) Las personas naturales o jurídicas que tengan partes relacionadas, vinculadas o asociadas dentro del territorio nacional, no están sujetas a la presentación del Estudio de Precios de Transferencia, salvo aquellas que sean relacionadas o vinculadas con personas naturales o jurídicas amparadas en regímenes especiales que gocen de beneficios fiscales. Para estos efectos, la Secretaría de Estado en el Despacho de Desarrollo Económico debe desarrollar una plataforma electrónica de consulta para determinar los precios de referencia en el mercado nacional, para propósitos tributarios y aduaneros.','113','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":113,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"f71e3815936d8308dff2e0bde8f02fdce73ae1309d2c073fdac54d9c2f2e7fef","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a113","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','113','f71e3815936d8308dff2e0bde8f02fdce73ae1309d2c073fdac54d9c2f2e7fef','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:114','mayalex_normativos','08_TRIBUTARIO','DATOS DE AUTORIDADES FISCALES EXTRANJERAS. Para determinar obligaciones tributarias o aduaneras omitidas, la Administración Tributaria o la Administración Aduanera, deben tener por ciertos los hechos, información y documentación, cuyo conocimiento haya obtenido de parte de autoridades fiscales extranjeras salvo prueba en contrario, siempre y cuando dichos hechos, información y documentación, entre otros elementos, se obtenga al amparo de Tratados o Convenios Tributarios o Aduaneros debidamente suscritos y aprobados, conforme al procedimiento contenido en la Constitución de la República.','114','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":114,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"7d0145e8d5824b401f7086e5a67fea41c58c0a0dada3d4148c8129a8b3053f69","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a114","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','114','7d0145e8d5824b401f7086e5a67fea41c58c0a0dada3d4148c8129a8b3053f69','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:115','mayalex_normativos','08_TRIBUTARIO','DERECHO DE RESTITUCIÓN Y DEVOLUCIÓN.

1) El obligado tributario tiene derecho de acción para reclamar la restitución de lo pagado en exceso o indebidamente, por concepto de tributos y sanciones;

2) Asimismo, el obligado tributario tiene derecho a la autorización de la nota de crédito o la devolución de los saldos a su favor que excedan la compensación prevista en este

Código;

3) Los pagos que den derecho a devoluciones y notas de crédito devengarán interés una vez que hayan finalizado el procedimiento siguiente:

a) En ambos supuestos, la Administración Tributaria o la Administración Aduanera, según corresponda, debe verificar los pagos indebidos o en exceso de un período fiscal, en el plazo legal establecido en este Código, debiendo notificar dicho acto al obligado tributario y a la Secretaría de Estado en el Despacho de Finanzas (SEFIN);

b) En el caso de las devoluciones, una vez que la Secretaría de Estado en el Despacho de Finanzas (SEFIN) haya sido notificada de la resolución respectiva, debe realizar el pago de la devolución en un plazo máximo de cuarenta (40) días calendario; y, c) Cuando los pagos indebidos se generen por autoliquidación, éstos no causan interés alguno.

4) En lo que respecta al pago de intereses, se debe aplicar la tasa de política monetaria publicada por el Banco Central de Honduras (BCH), tomando como referente el primer día en que la obligación los devengue;

5) Se autoriza a la Secretaría de Estado en el Despacho de Finanzas (SEFIN) para que anualmente incorpore en el Presupuesto General de Ingresos y Egresos de la República, en su propio presupuesto, la partida presupuestaria con los recursos necesarios para responder por el pago de los intereses que se causen a favor de los obligados tributarios respecto de los asuntos sometidos a su competencia; y,

6) De igual forma se autoriza a la Secretaría de Estado en el Despacho de Finanzas (SEFIN) para que anualmente incorpore en el Presupuesto General de Ingresos y Egresos de la República, en el presupuesto de la Administración Tributaria y de la Administración Aduanera, la partida presupuestaria con los recursos necesarios para responder por el pago de los intereses que se causen a favor de los obligados tributarios respecto de los asuntos sometidos a su competencia.','115','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":115,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"28f86e844762fd9bbfaafebf06032223e07096442bc9f97c3047ce9fd4e33fbe","ubicacion":["CAPÍTULO IV","PROCEDIMIENTOS DE DETERMINACIÓN DE LAS OBLIGACIONES","SECCIÓN PRIMERA","PROCEDIMIENTOS DE DETERMINACIÓN A INSTANCIA DEL OBLIGADO","TRIBUTARIO SUBSECCIÓN PRIMERA","RESTITUCIÓN Y DEVOLUCIÓN"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a115","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','115','28f86e844762fd9bbfaafebf06032223e07096442bc9f97c3047ce9fd4e33fbe','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:116','mayalex_normativos','08_TRIBUTARIO','PROCEDIMIENTO DE DEVOLUCIÓN DE PAGOS INDEBIDOS.

1) El procedimiento para el reconocimiento del derecho a la devolución de pagos indebidos se inicia:

a) Cuando se haya producido una duplicidad en el pago de deudas tributarias, recargos o sanciones;

b) Cuando la cantidad pagada haya sido superior al importe a pagar resultante de un acto administrativo o de una autoliquidación;

c) Cuando se realice un pago al que no esté obligado o se haya imputado una obligación erróneamente, y, d) Cuando así lo establezca la normativa tributaria o aduanera.

2) El interesado debe presentar solicitud ante la Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Administración Tributaria o la Administración Aduanera, según corresponda, en la que debe exponer detalladamente todos los hechos y fundamentos que acrediten la existencia de una de las circunstancias indicadas, acompañando las pruebas pertinentes; y,

3) Cuando un obligado tributario fuese afectado por un pago indebido derivado de una retención mal calculada por el agente de retención, éste puede compensar los pagos recibidos en exceso con otros pagos a realizar por el mismo obligado tributario o responsable, siempre que se trate del mismo tributo y del mismo ejercicio fiscal. En todo caso el agente retenedor debe emitir a favor del obligado tributario el documento fiscal que acredite la retención.

Si la compensación no pudiere efectuarse dentro de un mismo período fiscal, el retenido o responsable tiene derecho de solicitar la compensación o devolución ante el mismo agente retenedor, según sea el caso, quien debe informar a la Administración Tributaria o a la Administración Aduanera, en el ámbito de su competencia.','116','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":116,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"b6d192cc5ca35088aa76e2f89e20b7d57464c81231d34f0ea5a04bd0ed871128","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a116","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','116','b6d192cc5ca35088aa76e2f89e20b7d57464c81231d34f0ea5a04bd0ed871128','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:117','mayalex_normativos','08_TRIBUTARIO','RECTIFICACIÓN DE DECLARACIONES.

1) La rectificación de las declaraciones que disminuyan el tributo a pagar o aumenten el saldo a favor del obligado tributario se deben efectuar conforme a lo siguiente:

a) Tributos con modalidad anual: Dos (2) rectificaciones dentro del período de prescripciones contadas a partir de la fecha de Declaración del Tributo;

b) Tributos con modalidad mensual: Dos (2) rectificaciones dentro de doce (12) meses contados a partir de la fecha de Declaración del Tributo; y, c) Tributos con modalidad eventual o no periódica: Dos (2) rectificaciones dentro de un (1) año contado a partir de la fecha de Declaración del Tributo.

No obstante, lo establecido en este numeral, la Administración Tributaria o la Administración Aduanera, pueden solicitar al obligado tributario que rectifique la declaración, cuando aquélla lo determine necesario de conformidad a la Ley. Si el obligado tributario no rectificare su declaración por solicitud referida, éstas pueden ejercer sus facultades de verificación o fiscalización, de conformidad con la Ley.

Para rectificar las declaraciones que disminuyen el tributo a pagar o aumenten el saldo a favor del obligado tributario, se debe presentar en debida forma una nueva declaración en los lugares o medios habilitados para este fin;

3) Cuando los obligados tributarios, rectifiquen sus declaraciones y si fuere el caso, deben pagar la diferencia que resulte entre el pago realizado en la declaración original y la rectificación; junto con sus accesorios, tales como intereses, así como las sanciones pecuniarias establecidas para el pago fuera de plazo legal;

4) Una misma declaración que sea rectificada por más ocasiones que las establecidos en numeral 1) de este Artículo, constituye criterio para una posible fiscalización conforme a los programas que implemente la Administración Tributaria o la Administración Aduanera; y,

5) La rectificación de las declaraciones a que se hace referencia en los numerales anteriores no impide el ejercicio posterior de las facultades de verificación, comprobación, fiscalización determinación y de efectuar las respectivas liquidaciones de corrección aritmética o, en general, de revisión que tienen la Administración Tributaria y la Administración Aduanera, en sus respectivos ámbitos de competencia.','117','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":117,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"6a91976d64f5ae9b28a2f95aa883438f4fafa42383e1b2aad275ce7e867e7d2f","ubicacion":["SUBSECCIÓN SEGUNDA","RECTIFICACIÓN DE DECLARACIONES"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a117","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','117','6a91976d64f5ae9b28a2f95aa883438f4fafa42383e1b2aad275ce7e867e7d2f','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:118','mayalex_normativos','08_TRIBUTARIO','PROCEDIMIENTO DE DETERMINACIÓN DEL TRIBUTO POR LIQUIDACIÓN ADMINISTRATIVA CON BASE EN LAS DECLARACIONES. La intervención de la Administración Tributaria o de la Administración Aduanera, según el caso, para producir el documento de liquidación y pago solamente debe efectuarse para los casos regulados en el presente Artículo, conforme al procedimiento siguiente:

1) Deben proceder a la elaboración y propuesta al obligado tributario de una nueva liquidación, cuando de manera clara e indubitada acredite:

a) Que los datos contenidos en la declaración o declaraciones presentadas no concuerdan con los que obran en su poder, obtenidos de manera lícita;

b) Que los datos contienen discrepancia con los que provienen de sus otras declaraciones; o, c) Que los datos contienen errores aritméticos, lógicos o de aplicación.

2) La propuesta de liquidación debe contener los hechos y fundamentos de derecho correspondientes;

3) Se debe requerir al obligado tributario para que aclare o acredite lo que estime conveniente a fin de satisfacer las dudas surgidas. El plazo para realizar las aclaraciones es de quince (15) días hábiles contados a partir del día siguiente del requerimiento que se practique;

4) Si transcurrido el plazo para aclaraciones el obligado tributario no se presenta o guarda silencio sobre la liquidación propuesta, la Administración Tributaria o la Administración Aduanera, según el caso, debe ajustar de oficio la declaración, adquiriendo la misma el carácter de definitiva y firme para efectos de cobranza;

5) Transcurrido el plazo para aclaraciones y si el obligado tributario no aceptó la liquidación propuesta, el expediente se debe remitir a la dependencia que corresponda para efectuar el procedimiento de Determinación por Verificación de Escritorio; y,

6) Si el obligado tributario acepta la propuesta de nueva liquidación, el pago que realice queda exento de las multas. La liquidación sirve como documento válido para generar los débitos en la cuenta corriente del obligado tributario.','118','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":118,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"c48869fad1beab1020d07ed2c3e571381b4810078ae6c9ff78cfcd16af316e0e","ubicacion":["SUBSECCIÓN TERCERA","LIQUIDACIÓN ADMINISTRATIVA Y VERIFICACIÓN DE ESCRITORIO"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a118","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','118','c48869fad1beab1020d07ed2c3e571381b4810078ae6c9ff78cfcd16af316e0e','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:119','mayalex_normativos','08_TRIBUTARIO','PROCEDIMIENTO DE VERIFICACIÓN.

1) La Administración Tributaria o la Administración Aduanera, según el caso, puede verificar la exactitud de las autoliquidaciones a través de actuaciones de comprobación abreviada, entendiéndose como tales aquellas que se realizan utilizando los datos y elementos de prueba, obtenidos en legal y debida forma, que obren ya en poder de la respectiva institución o que solicite al propio obligado tributario, sin la realización de una auditoría integral;

2) Asimismo, puede realizar la verificación de las liquidaciones hechas conforme al procedimiento de liquidación administrativa en las cuales el obligado tributario las haya objetado o rechazado, de tal manera que se compruebe o no la veracidad de los hechos y datos aportados por el mismo;

3) Una vez realizadas estas actuaciones, se puede realizar la propuesta de regularización por conducto de una liquidación o solicitar al obligado tributario la aclaración de las discrepancias observadas, a fin de satisfacer las dudas surgidas. En ambos casos, el plazo para realizar las aclaraciones es de diez (10) días hábiles contados a partir del día siguiente del requerimiento que se practique;

4) La liquidación que se dicte tiene carácter de no integral;

5) Si el obligado tributario acepta la propuesta de nueva liquidación, el pago que realice está exento de las multas y no está sujeto a ningún tipo de sanciones. La liquidación sirve como documento válido para generar los débitos en la cuenta corriente del obligado tributario en materia tributaria- aduanera;

6) Si el obligado tributario no acepta o guarda silencio respecto de la propuesta de liquidación formulada, se puede ordenar la fiscalización parcial o integral correspondiente, cuyo resultado se debe notificar conforme al procedimiento establecido en este Código; y,

7) Las actuaciones de verificación deben concluirse en un plazo máximo de cuatro (4) meses, prorrogables por dos (2) meses adicionales, contados a partir del día siguiente de iniciado el procedimiento.','119','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":119,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"062977e7059510f461eca39e3e55ab2cdbf8fdfc12f7b04c66570aaee7d76cda","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a119","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','119','062977e7059510f461eca39e3e55ab2cdbf8fdfc12f7b04c66570aaee7d76cda','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:120','mayalex_normativos','08_TRIBUTARIO','CAUSALES Y PROCEDIMIENTO.

1) La Administración Tributaria o la Administración Aduanera, según corresponda, puede ejercer sus facultades de verificación del cumplimiento de las obligaciones formales de los obligados tributarios, mediante los mecanismos siguientes:

a) Actuaciones presenciales en los establecimientos abiertos al público, almacenes y bodegas, debiendo identificarse ante el obligado tributario previamente el ejercicio de sus funciones de verificación: y, b) Verificación de datos que consten en sus sistemas informáticos, sin necesidad de notificar al obligado tributario.

2) Detectado un incumplimiento se debe instar al obligado a rectificarlo, dentro de un plazo no menor de diez (10) días hábiles. Vencido el plazo anterior, se debe imponer la multa que corresponda según el rango determinado para las infracciones formales. Sin perjuicio de lo anterior, se debe iniciar y ejecutar el procedimiento sancionatorio descrito en este Código. En ambos casos se debe emitir la resolución correspondiente, la cual puede ser recurrida mediante los recursos prescritos en el presente Código; y,

3) Si existen irregularidades en los registros, datos o informaciones de un obligado tributario, se puede trasladar el expediente del caso para el inicio del correspondiente procedimiento de fiscalización, conforme a las normas y procedimientos contenidos en este Código.','120','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":120,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"4f47d2b0d1e424635852cec1d1c6785458459222e45ca1c02f312d02b0d819dc","ubicacion":["SECCIÓN SEGUNDA","VERIFICACIÓN EN CAMPO DE CUMPLIMIENTO DE OBLIGACIONES FORMALES"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a120","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','120','4f47d2b0d1e424635852cec1d1c6785458459222e45ca1c02f312d02b0d819dc','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:121','mayalex_normativos','08_TRIBUTARIO','CONCEPTO Y CLASES DE DETERMINACIÓN DE OFICIO.

1) La Determinación realizada por la Administración Tributaria o la Administración Aduanera llamada De Oficio, es el acto resolutorio mediante el cual verifica la existencia de un hecho generador, realiza las operaciones de cuantificación y determina el importe de la deuda tributaria o aduanera, comprobando o corrigiendo, si así procediera, la autoliquidación hecha por el obligado tributario y, determinando en este caso una suma a ingresar, una suma a devolver, una compensación, o un sello definitivo, de acuerdo con la normativa tributaria o aduanera. Asimismo, el acto determinativo puede establecer la existencia de la causal de atribución de la responsabilidad solidaria o subsidiaria, debiéndose, en tal caso, individualizar al sujeto responsable y el monto de la deuda;

2) Las determinaciones de oficio son integrales o parciales. Las determinaciones de oficio integrales también se denominan fiscalizaciones;

3) Tienen el carácter de integrales las practicadas con base en el procedimiento de fiscalización regulado en el Capítulo siguiente, mediante la investigación y comprobación de los elementos de la obligación tributaria o aduanera;
4) Tienen carácter de parcial, aquellas que no sean integrales y en particular, las siguientes:

a) Aquellas de alcance parcial, condición de la que debe dejarse expresa constancia en la resolución, con base en los aspectos que han sido objeto de la fiscalización:

b) Aquellas comprobaciones de escritorio reguladas en el presente Código que se realicen sobre la base de información que obra en poder de la Administración Tributaria o la Administración Aduanera o, que se ha solicitado al obligado tributario sin realizar un procedimiento de fiscalización, incluyendo las que se efectúen con base en puras diferencias de interpretación jurídica o se orienten a corregir errores de hecho o aritméticos cometidos en la declaración; y, c) Aquellas comprobaciones y verificaciones preventivas del cumplimiento de las obligaciones formales de los obligados tributarios.

5) Los elementos de la obligación tributaria o aduanera investigados y comprobados en el curso de un procedimiento que hubiera terminado con una determinación no integral, de alcance parcial, del literal a) del numeral anterior, no pueden ser objeto nuevamente de un procedimiento de fiscalización posterior,

6) Los elementos de la obligación tributaria o aduanera a los que no se hayan extendido las actuaciones de comprobación e investigación, pueden ser objeto de un procedimiento de determinación posterior, salvo que la fiscalización haya sido formalmente declarada integral; y,

7) Para las determinaciones parciales, los servidores públicos deben disponer de las mismas facultades que el procedimiento de fiscalización, salvo en el caso de determinación de oficio.','121','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":121,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"6bebfb806e89045ec11a06c54d4c6a53c9e7399701e442ab6ee0ac73cd535b26","ubicacion":["SECCIÓN TERCERA","PROCEDIMIENTO DE DETERMINACIÓN DE OFICIO"],"constancias":[{"nota":19,"tipo":"FE_DE_ERRATAS","texto":"Artículo 121. Numeral 7) Se corrige la palabra “oficina” por la palabra “oficio”. Mediante Fe de Errata publicada en el Diario Oficial La Gaceta No.34,347 de fecha 25 de mayo de 2017.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a121","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','121','6bebfb806e89045ec11a06c54d4c6a53c9e7399701e442ab6ee0ac73cd535b26','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:122','mayalex_normativos','08_TRIBUTARIO','ETAPAS DELPROCEDIMIENTO DE DETERMINACIÓN DE OFICIO.

1) El procedimiento de determinación de los tributos sujetos a la declaración, liquidación o autoliquidación por los obligados tributarios, se inicia con actuaciones de comprobación o de fiscalización;

2) El procedimiento se debe iniciar de oficio por el órgano competente quien debe notificar a los obligados tributarios indicando la naturaleza y alcance del procedimiento e informando sobre sus derechos y obligaciones en el curso de las actuaciones. Puede iniciarse también mediante requerimiento al obligado tributario o personamiento de la Administración en las instalaciones o domicilio;

3) Cuando los datos en poder de la Administración Tributaria o la Administración Aduanera sean suficientes para formular la propuesta de liquidación, el procedimiento puede iniciarse mediante la notificación de dicha propuesta;

4) Las actuaciones que realice un obligado tributario respecto de las declaraciones o autoliquidaciones objeto de un procedimiento de determinación, no son motivo para iniciar un procedimiento de devolución, crédito, compensación o considerarse como un pago espontáneo, en caso de haber realizado pago alguno, mientras se lleve a cabo el procedimiento de determinación;

5) No obstante lo anterior, cualquier pago que realice el obligado tributario, durante el procedimiento de determinación, se debe tomar en cuenta sin considerar los efectos y ventajas de un pago espontáneo;

6) Los pagos efectuados por el obligado tributario con posterioridad al inicio de las actuaciones o procedimientos y mientras el procedimiento no haya concluido con la emisión de una resolución determinativa, tienen el carácter de crédito a cuenta del importe de la liquidación que se practique en la resolución;

7) Si el pago es enterado por el obligado tributario previo a la emisión de la resolución y éste satisface todas las determinaciones y sanciones causadas, la resolución debe emitirse conteniendo un sello definitivo, describiendo expresa y puntualmente el cumplimiento de las obligaciones tributarias que se encontraban pendientes más las sanciones calculadas hasta la fecha en que se hizo efectivo el pago;

8) La Administración Tributaria o la Administración Aduanera, en el ámbito de sus competencias, debe realizar los ajustes en la cuenta corriente del obligado tributario en materia tributaria- aduanera conforme a la resolución emitida, a fin que el crédito generado producto del pago enterado, se concilie conforme a los débitos contenidos en la resolución referida;

9) El procedimiento de discusión de ajustes debe adecuarse conforme a lo dispuesto en este Código;

10) Del acta o documento equivalente, debe entregarse copia al obligado tributario, acompañando los documentos de trabajo y de soporte generados en el proceso de determinación de oficio;

11) Como resultado de estas actuaciones, se debe emitir una resolución, la cual debe contener una propuesta de regularización, en la que consten los hechos y omisiones que se hubieren conocido y entrañen incumplimiento de las normas tributarias o aduaneras por parte del obligado tributario, una relación sucinta del contenido del acta de la discusión de ajustes y en particular de las alegaciones y medios de prueba presentados, fundamentando de forma individualizada las imputaciones o cargos que se le formulen o los montos autoliquidados indebidamente en su perjuicio para efectos de su compensación, devolución o disminución del ajuste o para compensar con el monto ajustado que proponga la Administración Tributaria o la Administración Aduanera; y,

12) El obligado tributario dispone de un plazo de quince (15) días hábiles y diez (10) días hábiles en materia aduanera, contados a partir del día siguiente al que surta efectos la notificación de la resolución que se emita, para manifestar su conformidad, solicitar un arreglo de pago cuando éste proceda o interponer el recurso de reposición.','122','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":122,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"ebdfd25bc9972f4b3ec5bfb54371488fa3a26d4390fa7e4d6dff08425938deac","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a122","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','122','ebdfd25bc9972f4b3ec5bfb54371488fa3a26d4390fa7e4d6dff08425938deac','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:123','mayalex_normativos','08_TRIBUTARIO','RESOLUCIÓN DEL PROCEDIMIENTO DE DETERMINACIÓN DE OFICIO.

1) La resolución a la que se refiere el Artículo anterior debe emitirse dentro de los veinte (20) días hábiles, contados a partir del día hábil siguiente de la fecha de las alegaciones presentadas por el obligado tributario sobre los resultados de la determinación;

2) La resolución debe contener, como mínimo, los requisitos contenidos en este Código; y,

3) El incumplimiento de los plazos o el error u omisión de cualquiera de los requisitos enunciados contenidos en los artículos anteriores, constituyen una infracción de forma y da lugar a la anulabilidad de la resolución emitida y, consecuentemente, a la inaplicabilidad de sus efectos, de conformidad con el Artículo 102 del presente Código.','123','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":123,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"56e97d752962c98d7be37aab1d238b3b23f47d4b7333105a1eb018ca17907d40","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a123","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','123','56e97d752962c98d7be37aab1d238b3b23f47d4b7333105a1eb018ca17907d40','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:124','mayalex_normativos','08_TRIBUTARIO','ATRIBUCIONES PARA LA FISCALIZACIÓN.

1) La Administración Tributaria o la Administración Aduanera, según corresponda, a fin de comprobar o investigar que los obligados tributarios han cumplido con las correspondientes normas y, en su caso, determinar los tributos omitidos, así como de cumplir con lo establecido en los Convenios de Derecho Internacional Tributario o Aduanero, está facultada para:

a) Requerir a los obligados tributarios, para que comparezcan ante sus oficinas a dar contestación a las preguntas que se les formulen o a reconocer firmas, documentos o bienes de acuerdo a lo establecido en este Código;

b) Requerir a los obligados tributarios, para que exhiban, en su domicilio o establecimientos, los documentos que sustenten la contabilidad o que estén relacionados con hechos vinculados a la generación de obligaciones tributarias o aduaneras, así como documentos y correspondencia comercial relacionada con hechos susceptibles de generar dichas obligaciones, en la forma que determine la Ley;

c) Requerir la presentación y copia de informes y análisis relacionados con hechos susceptibles de generar obligaciones tributarias en la forma que determine la autoridad correspondiente, en el marco de sus atribuciones legales;

d) Realizar auditoría de sistemas, conforme a los principios, derechos y reglas contenidas en este Código;

e) Practicar verificaciones, comprobaciones, fiscalizaciones e investigaciones en el domicilio tributario de los obligados tributarios y revisar su contabilidad y bienes;

f) Solicitar a entidades especializadas que practiquen actuaciones de valoración de bienes, rentas, productos, derechos y patrimonios en general de personas y entidades públicas y privadas. Estas actuaciones, tienen por objeto la tasación o comprobación del valor declarado. Cualquier actuación de valoración, tasación o comprobación que se realice por mandato de la autoridad correspondiente, debe ponerse en conocimiento y a la vista, con copia, al obligado tributario, para que éste pueda aprobarla o impugnarla mediante los mecanismos previstos en este Código;

g) Comprobar o verificar físicamente toda clase de bienes, incluso durante su transporte, sin perjuicio del derecho a la inviolabilidad del domicilio, salvo con orden judicial; y, h) Resguardar los documentos inspeccionados y tomar medidas de seguridad para su conservación.

2) La Administración Tributaria o la Administración Aduanera, en el ámbito de sus competencias, puede ejercer estas facultades conjunta, indistinta o sucesivamente, pudiendo requerir el auxilio de la fuerza pública para ejercerlas, siempre y cuando exista evidente y notoria resistencia del obligado tributario que impida el cumplimiento de sus facultades o bien cuando éstas se realicen en lugares en donde exista riesgo inminente para la seguridad física de los servidores públicos de dichas administraciones. En los casos en que en el ejercicio de estas facultades implique la restricción de derechos y garantías constitucionales se debe contar con la autorización previa de un Juez competente.','124','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":124,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"a972acb87b25341cef4e6d8cffde781abdd53f238526ecf69fa82d0aeadf761b","ubicacion":["CAPÍTULO V","FISCALIZACIÓN"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a124","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','124','a972acb87b25341cef4e6d8cffde781abdd53f238526ecf69fa82d0aeadf761b','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:125','mayalex_normativos','08_TRIBUTARIO','DESARROLLO DEL PROCEDIMIENTO DE FISCALIZACIÓN.

1) El procedimiento de fiscalización se debe iniciar mediante la notificación de inicio de actuaciones al obligado tributario, el cual es suscrito por el titular de la Administración Tributaria o de la Administración Aduanera o, por la persona a quién éste delegue en la que se debe informar:

a) Alcance total o parcial de las actuaciones;

b) Detalle de los tributos sujetos a fiscalización;

c) Fundamentos de derecho de la orden de fiscalización;

d) Los períodos fiscales que debe comprender el acto de fiscalización; y, e) La identificación del o de los servidores públicos actuantes.

2) El ocupante de la finca, local, establecimiento o edificio, debe permitir sin dilación la entrada de los fiscalizadores. No obstante, si aquel se opusiere, es preciso obtener un mandamiento judicial por un juez del fuero penal y con el auxilio de la fuerza pública;

3) Cuando se trate de casa habitación o morada del obligado tributario, es preciso obtener previamente un mandamiento judicial, salvo que aquél manifieste su consentimiento por escrito;

4) Todas las actuaciones que se desarrollen en el curso del procedimiento de fiscalización e investigación se deben documentar en actas, inclusive las actuaciones en que intervenga directamente el obligado fiscalizado, en las que se hacen constar como mínimo:

a) Los hechos y omisiones que se hubieren conocido por los fiscalizadores;

b) Los puntos de convergencia del sujeto fiscalizado durante el proceso de la auditoría;

c) La cronología completa y hallazgos del proceso;

d) Las objeciones o rechazos que manifieste el obligado tributario; y, e) Las investigaciones u otros hechos relacionados con las demás actuaciones y diligencias que se lleven a cabo en un proceso de fiscalización.

5) Si durante el desarrollo de la fiscalización los servidores públicos actuantes encuentran activos que no estén registrados en contabilidad, a fin de asegurar los documentos y correspondencia de dichos activos, deben solicitar autorización judicial, para que en presencia del juez ejecutor, se proceda a sellar o colocar marcas en los muebles, archivos u oficinas donde se encuentren los documentos objeto de fiscalización, así como dejarlos en cantidad de depósito al fiscalizado o a la persona con quien se entienda la actuación, previo inventario que al efecto formulen. En el caso que se encuentren documentos en los muebles, archivos u oficinas que se sellen y sean necesarios al fiscalizado o investigado para realizar sus actividades, se le permitirá extraerlos con la autorización del juez competente, quien puede sacar copia del mismo, dejándose constancia de este hecho.

6) Las actuaciones de fiscalización deben concluir con la emisión de la resolución correspondiente, en un plazo máximo de ocho (8) meses contados a partir del día siguiente a la fecha de notificación del documento de inicio de fiscalización. No obstante, se puede prorrogar por seis (6) meses cuando se dé cualquiera de las circunstancias siguientes:

a) Las actuaciones revistan especial complejidad; y, b) En el transcurso de las mismas se descubra que el obligado tributario ha ocultado a la Administración Tributaria o la Administración Aduanera alguna de las actividades empresariales o profesionales que realice.

7) La ampliación del plazo legalmente previsto es, en todo caso, motivado, con referencia a los hechos y fundamentos de derecho;

8) Asimismo, las actuaciones de fiscalización e investigación no pueden suspenderse por más de sesenta (60) días por causas no imputables al obligado tributario.

9) El plazo de suspensión finaliza, entre otras, por las causas siguientes:

a) Por las visitas al lugar en que se desarrollan las actuaciones de fiscalización;

b) Las audiencias en las oficinas de la Administración Tributaria o la Administración Aduanera; o, c) Los requerimientos de información al obligado tributario.

10) Las mismas actuaciones pueden suspenderse por el mismo plazo, a petición del obligado tributario, siempre y cuando sea por causas debidamente justificadas, caso fortuito o fuerza mayor,

11) En cualquiera de las situaciones previstas en este Artículo, la suspensión se hace constar en el acta de suspensión de auditoría;

12) Cuando las actuaciones de fiscalización no se concluyan en el plazo indicado en el numeral 6) anterior, o la suspensión se alargue por más del plazo indicado en el numeral
8) anterior, se entiende que no se ha interrumpido la prescripción por las actuaciones anteriores realizadas;

13) Cuando a juicio de los servidores públicos actuantes se hayan obtenido los datos y pruebas necesarios para fundamentar los actos que procede dictar, levantarán un acta final de cierre de las actuaciones de fiscalización. Si en este acto no estuviere presente el fiscalizado, se le dejará citación para que esté presente a una hora determinada del día siguiente hábil. Si no se presentare, el acta final se levantará ante quien se haya delegado para estar presente en ese acto, en la finca, local, establecimiento o edificio.

En ese momento cualquiera de los servidores públicos que hayan intervenido en la fiscalización y el fiscalizado o la persona con quien se entiende la diligencia deben firmar el acta de la que se dejará copia al fiscalizado;

14) Si el fiscalizado o la persona designada no comparecen, se niegan a firmar o, aceptar la copia del acta, dicha circunstancia se debe asentar en la misma sin que esto afecte su validez y valor probatorio. No obstante, el contenido del acta debe ser notificada al obligado tributario utilizando cualquiera de los otros medios de notificación previstos en este Código;

15) Concluida la labor de campo del proceso de fiscalización, los servidores públicos actuantes dentro del plazo de diez (10) días hábiles posteriores a dicha conclusión, deben emitir una propuesta provisional de regularización y liquidación en la cual consten los ajustes o modificaciones a la autoliquidación o declaración del sujeto fiscalizado o la determinación que consideren procedente en caso de no haber mediado declaración, así como las faltas tributarias materiales y formales, con indicación de los hechos, pruebas y fundamentos jurídicos, otorgándole un plazo de quince (15) días hábiles para que manifieste su conformidad total o parcial o para que alegue lo que convenga a su derecho. El obligado tributario tiene acceso a la totalidad del expediente a partir de la fecha de notificación de la resolución correspondiente;

16) La propuesta de regularización y liquidación emitida no puede modificarse, si el obligado tributario realiza el pago total de la misma;

17) La liquidación que se dicte es de carácter integral o parcial según lo establecido en este Código; y,

18) Las actuaciones a que se refiere este Artículo, deben concluir con la notificación de la resolución correspondiente, la cual puede ser recurrida según los procedimientos y recursos prescritos en este Código.','125','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":125,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"efda4e9a89ebf1c9935b0592880e00eec1c067f9ddea2543e19e8b610526546d","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a125","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','125','efda4e9a89ebf1c9935b0592880e00eec1c067f9ddea2543e19e8b610526546d','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:126','mayalex_normativos','08_TRIBUTARIO','LUGAR PARA ELEJERCICIO DE LA VERIFICACIÓN, COMPROBACIÓN, FISCALIZACIÓN E INVESTIGACIÓN.

1) Los actos de verificación, comprobación, fiscalización e investigación pueden desarrollarse indistintamente según determinen los órganos encargados de la misma:

a) En el domicilio del obligado tributario;

b) En donde se realicen total o parcialmente las actividades del obligado tributario;

c) Donde se haya dado el hecho imponible; y, d) En las oficinas de la Administración Tributaria o de la Administración Aduanera, según corresponda.

2) Los fiscalizadores de los tributos pueden entrar en las fincas, locales de negocio y demás establecimientos o lugares en que se desarrollen actividades o explotaciones para ejercer las funciones previstas en este Código. Estas facultades se deben ejecutar garantizando los derechos de los obligados tributarios.','126','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":126,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"cbc52698704ef3d3332b1f9f4475716154e1c9792a255df3984a345178753920","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a126","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','126','cbc52698704ef3d3332b1f9f4475716154e1c9792a255df3984a345178753920','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:127','mayalex_normativos','08_TRIBUTARIO','ACCIÓN EJECUTIVA DE COBRO.

1) El Estado tiene acción ejecutiva y preferente para el cobro de los créditos por concepto de tributos, multas e intereses, que resulten de autoliquidaciones, liquidaciones, resoluciones firmes y sentencias firmes.

En aquellos casos en que las leyes especiales contengan recargos, éstos se deben cobrar conforme al procedimiento contenido en este numeral;

2) En el caso de las obligaciones generadas por autoliquidaciones y liquidaciones, es título ejecutivo suficiente la certificación de deuda en que conste la obligación tributaria principal o accesoria, extendida por la Administración Tributaria o la Administración Aduanera. En el caso de las resoluciones y las sentencias firmes, éstas sirven de título ejecutivo, pudiendo acompañarse una certificación de deuda que actualice el cómputo de lo debido a favor del Estado;

3) La certificación a la que se refiere el numeral anterior debe reunir los requisitos siguientes:

a) Lugar y fecha de emisión;

b) Nombres, apellidos, firma y sello del Secretario General de la Administración Tributaria o de la Administración Aduanera, según el caso, o de la persona con delegación suficiente para emitir la misma;

c) Indicación clara y precisa de la obligación tributaria o aduanera y sus accesorios; y, d) Nombre, razón social o denominación social, Registro Tributario Nacional (RTN) y domicilio del obligado tributario.

4) El certificado de deuda que sirve como título ejecutivo a que se hace referencia en los numerales 2) y 3) anteriores, debe emitirse una vez que la Administración Tributaria o la Administración Aduanera compruebe, mediante el informe respectivo, la cantidad del adeudo correspondiente y que el mismo sea firme, de plazo vencido, líquido y exigible; y,

5) Sin perjuicio al respeto del orden de prelación para el cobro de los créditos establecidos en este Código, en el caso de concurrencia del procedimiento de cobro administrativo para la recaudación de los tributos, con otros procedimientos de ejecución sobre bienes embargados, se seguirán las reglas siguientes:

a) Cuando concurra con otros procesos o procedimientos singulares de ejecución, el procedimiento de cobro es preferente cuando el embargo efectuado en el curso del mismo sea el más antiguo; y, b) En los supuestos de concurrencia del procedimiento de cobro con procesos o procedimientos concursales o universales de ejecución, aquel procedimiento tiene preferencia para la ejecución de los bienes o derechos que hayan sido objeto de embargo en el curso del mismo, siempre que dicho embargo se hubiera efectuado con anterioridad a la fecha de inicio del proceso concursal.','127','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":127,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"135c02c02ad332fcc52b6f5d91177bde1279de85913066562f5b52dd52e19840","ubicacion":["CAPÍTULO VI","PROCEDIMIENTO DE COBRO","SECCIÓN PRIMERA","DE LA EJECUCIÓN"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a127","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','127','135c02c02ad332fcc52b6f5d91177bde1279de85913066562f5b52dd52e19840','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:128','mayalex_normativos','08_TRIBUTARIO','NATURALEZA Y NO ACUMULACIÓN DEL PROCEDIMIENTO DE COBRO. La Administración Tributaria o la Administración Aduanera debe realizar el cobro por la vía judicial civil, conforme a los procedimientos establecidos en este Código y para todo lo no dispuesto en el mismo se debe aplicar de manera supletoria el Código Procesal Civil.','128','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":128,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"d7e4b3a7db104b415a6930b431be9cc5c7b1728fb30138307c06d1026d539aad","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a128","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','128','d7e4b3a7db104b415a6930b431be9cc5c7b1728fb30138307c06d1026d539aad','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:129','mayalex_normativos','08_TRIBUTARIO','ACCIONES DE COBRANZA PERSUASIVA.

1) Previo al cobro judicial, la Administración Tributaria o la Administración Aduanera puede ejercer un cobro persuasivo, dentro de un plazo no mayor de treinta (30) días calendarios contados a partir de la fecha del vencimiento del plazo establecido en la Ley para el pago del mismo;

2) La cobranza persuasiva procede en los casos siguientes:

a) Respecto de determinaciones o liquidaciones de tributos, pagos a cuenta e intereses, recargos si aplican, generados por el obligado tributario;

b) Respecto de determinaciones o autoliquidaciones de tributos, pagos a cuenta, intereses, multas y recargos si aplican, impuestas por el Estado y consentidas por el obligado tributario;

c) Respecto de obligaciones tributarias por las que el obligado tributario hubiere solicitado facilidades de pago no cumplidas oportunamente y cuya liquidación haya adquirido el carácter de firme en instancia administrativa;

d) Respecto de pagos a cuenta por tributos vencidos; y, e) Cuando medie reconocimiento expreso de la deuda por el obligado tributario y en la medida de ese reconocimiento.

3) Las deudas líquidas, firmes y exigibles, que no hayan sido recuperadas por la vía persuasiva, deben ser trasladadas a la Procuraduría General de la República (PGR), para su cobro. Recibidas las causas ésta tiene un plazo de diez (10) días hábiles para interponer las acciones judiciales correspondientes.','129','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":129,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"0328381512521591cd1fa902b2255b06a2ee6882bb83325af8bd2f9a2b653b32","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a129","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','129','0328381512521591cd1fa902b2255b06a2ee6882bb83325af8bd2f9a2b653b32','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:130','mayalex_normativos','08_TRIBUTARIO','EXCEPCIONES A LA ACCIÓN JUDICIAL DE COBRO. Además de las contenidas en el Código Procesal Civil, son admisibles los motivos de oposición siguientes:

1) Espera documentada vigente, concedida por la Administración Tributaria o la Administración Aduanera con anterioridad a la presentación de la demanda;

2) Extinción de la obligación tributaria o aduanera;

3) Compensación de créditos;

4) Inexistencia de la obligación tributaria o aduanera, declarada por sentencia judicial firme;

5) Falsedad del título ejecutivo o del acto que le hubiere dado fuerza de tal; y,

6) La falta de agotamiento de los trámites administrativos establecidos para emitir el título ejecutivo conforme al Artículo 127 de este Código; con excepción de las autoliquidaciones.

La oposición se debe plantear y se debe sustanciar conforme al procedimiento establecido en el Código Procesal Civil.','130','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":130,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"b0e795c0f2669458f8dca711d3c0188b6bfefb257b36758ec13dc8f38117ef99","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a130","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','130','b0e795c0f2669458f8dca711d3c0188b6bfefb257b36758ec13dc8f38117ef99','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:131','mayalex_normativos','08_TRIBUTARIO','DE LAS DEUDAS TRIBUTARIAS INCOBRABLES POR RAZÓN DE COSTO BENEFICIO Y DEPURACIÓN DE LA CUENTA CORRIENTE.

1) La Administración Tributaria y la Administración Aduanera, en el ámbito de sus competencias, de oficio, en el mes de febrero de cada año, deben proceder a descargar de la cuenta corriente de los obligados tributarios, los créditos tributarios firmes a favor del Estado, cuyo monto sea igual o inferior a un (1) salario mínimo promedio vigente;

2) Asimismo, de oficio, en el mes de febrero de cada año, deben proceder a descargar de la cuenta corriente de los obligados tributarios, los montos acumulados de créditos y deudas de ejercicios fiscales anteriores ya prescritos; y,
3) Las actuaciones descritas en los numerales anteriores deben ejecutarse una vez emitido un acto administrativo por la Administración Tributaria o la Administración Aduanera.','131','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":131,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"8874974012a0a5f213f58ae8ee79cb27e0af7932caccb9ba12c5fcb55062ab30","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a131","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','131','8874974012a0a5f213f58ae8ee79cb27e0af7932caccb9ba12c5fcb55062ab30','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:132','mayalex_normativos','08_TRIBUTARIO','ORDEN DE PRIVILEGIO. La deuda tributaria o aduanera gozan de privilegio general sobre todos los bienes de los obligados tributarios y tienen prelación sobre los demás créditos con excepción de:

1) Las pensiones alimenticias, sueldos, salarios, honorarios, prestaciones, indemnizaciones laborales y por seguridad social, aportaciones en fondos de retiro, jubilación, pensión, previsión o montepío, ya sean públicos o privados; y,

2) Acreedores de dominio, prenda, hipoteca u otro derecho real, siempre que éste se haya constituido y registrado en la forma prescrita por Ley y con anterioridad a la inscripción de la medida cautelar judicialmente solicitada por la Administración Tributaria o la Administración Aduanera.','132','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":132,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"540d9a1ecbe0b121937030855afd82b07a19893acd754f400e30dbaff7fdf83a","ubicacion":["SECCIÓN SEGUNDA","PRIVILEGIO DE LA DEUDA TRIBUTARIA Y PRELACIÓN DE CRÉDITOS"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a132","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','132','540d9a1ecbe0b121937030855afd82b07a19893acd754f400e30dbaff7fdf83a','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:133','mayalex_normativos','08_TRIBUTARIO','JUICIO DE QUIEBRA, SUSPENSIÓN DE PAGOS O CONCURSO. Cuando se inicie un juicio de quiebra, suspensión de pagos o de concurso de acreedores, el juez que conozca del asunto lo debe comunicar a la Administración Tributaria o la Administración Aduanera, al momento de admitir la demanda, para que, si procede, se persone por conducto de la Procuraduría General de la República (PGR) y haga exigible los créditos que le son debidos.','133','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":133,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"dd4766baaa7bfaefed8148c852bd11606cacfd391638b08e29bbfba88db8f52c","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a133","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','133','dd4766baaa7bfaefed8148c852bd11606cacfd391638b08e29bbfba88db8f52c','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:134','mayalex_normativos','08_TRIBUTARIO','MODOS DE EXTINCIÓN DE LA OBLIGACIÓN

TRIBUTARIA Y ADUANERA. Las obligaciones tributarias o aduaneras se extinguen:

1) Por el pago cuando la obligación sea pecuniaria;

2) Por la compensación y cesión;

3) Por la confusión;

4) Por la condonación:

5) Por la prescripción; y,

6) Por el abandono, pérdida o destrucción de las mercancías en las aduanas del país.','134','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":134,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"12993e64f8aa5c6e38c164cec6580737cbff541e53817fb764aa5e309904c4b0","ubicacion":["TÍTULO QUINTO","DELCUMPLIMIENTO Y EXTINCIÓN DE LAS OBLIGACIONES TRIBUTARIAS Y","ADUANERAS","CAPÍTULO I","DISPOSICIONES GENERALES"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a134","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','134','12993e64f8aa5c6e38c164cec6580737cbff541e53817fb764aa5e309904c4b0','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:135','mayalex_normativos','08_TRIBUTARIO','OBLIGADOS AL PAGO.

1) El pago de los tributos debe ser realizado por los obligados tributarios a los que se refiere el presente Código; y,

2) También puede realizar el pago un tercero.','135','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":135,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"880af4af7dd069e1cbd82269f8d335c73ddf1d2f28a5e82980a3d3e12ab6d505","ubicacion":["CAPÍTULO II","DEL PAGO"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a135","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','135','880af4af7dd069e1cbd82269f8d335c73ddf1d2f28a5e82980a3d3e12ab6d505','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:136','mayalex_normativos','08_TRIBUTARIO','FORMAS Y MEDIOS DE PAGO. El pago de los tributos, retenciones, percepciones, pagos a cuenta o anticipados, pagos en especie, sanciones pecuniarias y demás cargos, se debe efectuar en dinero en efectivo, cheque de caja bancario, cheque certificado o transferencia u otros medios de pago legalmente reconocidos, utilizando los medios físicos o telemáticos que la Administración Tributaria o la Administración Aduanera, según corresponda, determinado conforme a la Ley.','136','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":136,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"67243c57a2791cd135585a6824a7e2281e65df7a6b98ade8b2543e36fb2f7e74","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a136","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','136','67243c57a2791cd135585a6824a7e2281e65df7a6b98ade8b2543e36fb2f7e74','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:137','mayalex_normativos','08_TRIBUTARIO','DETERMINACIÓN DE LA OBLIGACIÓN TRIBUTARIA O ADUANERA Y MOMENTO DE SU PAGO.

1) El pago de las obligaciones tributarias o aduaneras se debe hacer en la misma fecha en que se presente la autoliquidación respectiva, salvo cuando en este Código u otras leyes dispongan otra cosa;

2) Los gravámenes arancelarios se deben pagar antes que se autorice el levante de las mercancías de los recintos aduaneros, excepto en los casos permitidos por la Ley. La suma a pagar es la que determine el obligado tributario, en forma directa o a través del agente aduanero autorizado, quedando sujeto a verificación en el momento o ajuste previo al levante o, a verificación posterior mediante el proceso de fiscalización respectivo; y,

3) Si la determinación de la obligación tributaria se hubiere hecho de oficio, el obligado tributario deber hacer efectivo el pago en los plazos y en la forma que se determinen en cada caso.','137','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":137,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"2679529cfb5ad5b35438af7220c7eb190cc75b4d77d62f7a79dd7a1813e97e8f","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a137","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','137','2679529cfb5ad5b35438af7220c7eb190cc75b4d77d62f7a79dd7a1813e97e8f','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:138','mayalex_normativos','08_TRIBUTARIO','PAGO ANTICIPADO.

1) Los obligados tributarios sólo pueden cumplir anticipadamente sus obligaciones tributarias o aduaneras cuando la Ley expresamente los autorice;

2) La Administración Tributaria o la Administración Aduanera, por su parte puede exigir en forma anticipada a los obligados tributarios el pago total o parcial de un tributo cuando la Ley expresamente la faculte para ello; y,

3) Para los efectos de lo previsto en el numeral anterior, los pagos anticipados pueden hacerse mediante retención en la fuente, pagos a cuenta u otras formas de retención o percepción autorizadas por la Ley que produzcan como efecto el pago total o parcial de un tributo.','138','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":138,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"0c79a8d48abfbae6fe149cf8aee26b15fe88e06abb5fc7b6153203c758e34ce0","ubicacion":[],"constancias":[{"nota":20,"tipo":"FE_DE_ERRATAS","texto":"Artículo 138. Numeral 3) Se corrige la palabra “puede” por la palabra “pueden”. Mediante Fe de Errata publicada en el Diario Oficial La Gaceta No.34,347 de fecha 25 de mayo de 2017.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a138","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','138','0c79a8d48abfbae6fe149cf8aee26b15fe88e06abb5fc7b6153203c758e34ce0','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:139','mayalex_normativos','08_TRIBUTARIO','IMPUTACIÓN DE PAGOS.

1) Los obligados tributarios deben determinar, al efectuar el pago, a qué deuda debe imputarse;

2) Cuando no lo hicieren o la imputación fuere defectuosa o las circunstancias especiales del caso no permitan establecer la deuda imputada, la Administración Tributaria o la Administración Aduanera, según sea el caso, debe determinar la obligación a la que se debe aplicar el pago, para lo cual debe actuar de acuerdo con las reglas siguientes:

a) Cuando la deuda esté compuesta por tributos, multas, recargos e intereses, la suma enterada se debe aplicar al pago de las multas, recargos e intereses y, si hubiere excedentes, se debe hacer abonos al tributo; y, b) Cuando se adeuden tributos y pagos a cuenta conjuntamente con multas, la suma enterada se debe aplicar al pago de las multas y, si hubiere excedentes, al pago a cuenta y al tributo por su orden.

3) Entre obligaciones de la misma naturaleza, el pago se debe imputar a la deuda más antigua que no haya prescrito y si tuvieran la misma antigüedad, a la más gravosa para el obligado tributario; y,

4) El pago de una deuda de vencimiento posterior no extingue el derecho de la Administración Tributaria o la Administración Aduanera a percibir las anteriores que no se hayan cubierto, siempre y cuando no estén prescritos.','139','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":139,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"5b9c979e6021ee106c95783b1da99f0e0dd39f3c31e83ecfcfcf7f7e0644a0ac","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a139","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','139','5b9c979e6021ee106c95783b1da99f0e0dd39f3c31e83ecfcfcf7f7e0644a0ac','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:140','mayalex_normativos','08_TRIBUTARIO','FACILIDADES DE PAGO.

1) La Administración Tributaria o la Administración Aduanera, según corresponda, previa solicitud de parte interesada, debe conceder a los obligados tributarios, facilidades de pago de los tributos y accesorios adeudados, atendiendo las circunstancias y la capacidad económica del solicitante, cuando su situación económico- financiera le impida, de forma transitoria, efectuar el pago en los plazos establecidos;

2) Estas facilidades de pagos deben consistir en aplazamientos o fraccionamientos de pago. La cantidad readecuada, que comprende los tributos y los accesorios, devenga intereses a una tasa del dos por ciento (2%) mensual, por el plazo en que se acuerde la facilidad de pago;

3) Para garantizar los aplazamientos y fraccionamientos de la deuda tributaria, la Administración Tributaria o la Administración Aduanera, según corresponda, debe exigir un pago máximo inicial de:

a) Un cinco por ciento (5%) de la cantidad adeudada cuando sea un obligado tributario pequeño;

b) Un diez por ciento (10%) de la cantidad adeudada cuando sea un obligado tributario mediano; y, c) Un veinte por ciento (20%) de la cantidad adeudada cuando sea un obligado tributario grande.

4) Si el obligado tributario presenta un estudio económico autorizado por un profesional de las ciencias económicas o una carrera afín, se puede dispensar el pago máximo de los porcentajes contenidos en el numeral anterior. Los profesionales se deben seleccionar de una lista que publique la Administración Tributaria, la cual se debe revisar y actualizar anualmente;

5) La Administración Tributaria o la Administración Aduanera puede conceder facilidades o planes de pago de tributos y sanciones pecuniarias hasta por veinticuatro (24) meses; y,

6) No cabe conceder las facilidades a que este Artículo se refiere si la obligación tributaria o aduanera se debe a tributos retenidos o percibidos y no enterados al Estado.','140','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":140,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"b77364540ec1cfc13cfead89e56e6cc3a3887fd479335e33920069cfb7be259f","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a140","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','140','b77364540ec1cfc13cfead89e56e6cc3a3887fd479335e33920069cfb7be259f','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:141','mayalex_normativos','08_TRIBUTARIO','LUGAR DE PAGO.

1) El pago de los tributos y sus accesorios se debe hacer en la Tesorería General de la República (TGR) o en las instituciones del sistema financiero que para tales efectos la Secretaría de Estado en el Despacho de Finanzas (SEFIN) suscriba convenios de percepción, estableciendo en los mismos la forma y mecanismos de percepción, el plazo para el traslado de los recursos percibidos y el pago de las comisiones que correspondan; y,

2) Ningún empleado o servidor público puede percibir tributos o sus accesorios.','141','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":141,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"12ac3561f38cdf7d88918575658d491f500ff76de06fb1fd2345fc74b5ff90ee","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a141","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','141','12ac3561f38cdf7d88918575658d491f500ff76de06fb1fd2345fc74b5ff90ee','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:142','mayalex_normativos','08_TRIBUTARIO','COMPENSACIÓN Y CESIÓN.

1) Las obligaciones tributarias o aduaneras pueden compensarse total o parcialmente con créditos por tributos, sus accesorios, líquidos, exigibles y no prescritos, siempre que sean gestionados por la Administración Tributaria o la Administración Aduanera;

2) La compensación puede realizarse por cualquiera de las formas siguientes:

a) A petición del obligado tributario; o, b) De oficio por la Administración Tributaria o la Administración Aduanera.

3) El obligado tributario puede solicitar compensación de sus saldos a favor, con deudas en concepto de tributos, anticipos, pagos a cuenta, retenciones, percepciones, intereses y sanciones pecuniarias que mantengan con la Administración Tributaria o la Administración Aduanera. El obligado tributario debe notificarlo para fines de actualización de la cuenta corriente correspondiente, operación que se debe realizar sin la necesidad de emitir una resolución; sin perjuicio de la obligación de efectuar las rectificaciones correspondientes para asegurar la debida aplicación del crédito por vía de compensación;

4) Los saldos a favor del obligado tributario que sean líquidos, sin solicitud expresa de compensación por parte del interesado, pueden ser imputados de oficio por la Administración Tributaria o la Administración Aduanera al pago de la deuda comenzando por las deudas de períodos más antiguos, referentes a períodos no prescritos y en el orden de prelación de los conceptos establecidos en este Código;

5) Los créditos líquidos, exigibles y no prescritos, para el pago de cualquier tipo de obligaciones tributarias o aduaneras, contenidas en este Código o en leyes tributarias O aduaneras generales y especiales de un obligado tributario o responsable, por pagos hechos en concepto de tributos o accesorios, pueden cederse a otros obligados tributarios o responsables a fin de que puedan ser utilizados por el cesionario con el Estado;

6) Cada cesión o transferencia debe notificarse a la Administración Tributaria o la Administración Aduanera, según corresponda, por cualquiera de las partes, mediante una simple comunicación escrita o electrónica; debiendo la institución practicar los ajustes en la cuenta corriente del cedente y cesionario, de forma automática y sin dilación. La Administración Tributaria y la Administración Aduanera deben poner en funcionamiento un sistema que le permita realizar estos ajustes de forma automatizada, de tal manera que se deje constancia de la transacción, pero sin dilación de plazos de horas o días en su perfeccionamiento o ejecución;

7) Las cesiones o transferencias surten plenos efectos jurídicos desde el momento de su notificación a la Administración Tributaria o la Administración Aduanera, según corresponda y, no requieren de autorización o aprobación mediante resolución; y,

8) Las disposiciones anteriores son aplicables sin perjuicio de las facultades legales de la Administración Tributaria o de la Administración Aduanera.','142','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":142,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"923d750d159c30215628305658d2716788c34253879d9158fa0a9284fc31e5ac","ubicacion":["CAPÍTULO III","DE LA COMPENSACIÓN"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a142","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','142','923d750d159c30215628305658d2716788c34253879d9158fa0a9284fc31e5ac','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:143','mayalex_normativos','08_TRIBUTARIO','CONDONACIÓN. La obligación de pago de los tributos o el cumplimiento de las obligaciones formales, sólo puede ser condonada mediante Ley.','143','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":143,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"549350a0c6babe9383e37c8a05f63702962c3f9047bbbd58d96df65d3d5e03e2","ubicacion":["CAPÍTULO IV","DE LA CONDONACIÓN"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a143","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','143','549350a0c6babe9383e37c8a05f63702962c3f9047bbbd58d96df65d3d5e03e2','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:144','mayalex_normativos','08_TRIBUTARIO','PRESCRIPCIÓN.

1) Por la prescripción se extinguen los derechos y acciones de la Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Administración Tributaria, la Administración Aduanera y del obligado tributario, cuando no los ejerciten dentro del plazo legalmente señalado y es efectiva cuando transcurra el plazo contenido en este Código; y,

2) La responsabilidad y la acción del obligado tributario para solicitar la devolución o repetición por tributos y accesorios, así como las acciones y facultades del Estado para verificar, comprobar, fiscalizar, investigar, practicar diligencias y exámenes, determinar y exigir el pago de las obligaciones previstas en este Código, prescriben en forma definitiva por el transcurso de:

a) Cuatro (4) años en el caso de obligaciones de importación, exportación o cualquier otra relativa a operaciones comprendidas dentro de los regímenes aduaneros;

b) Cinco (5) años en el caso de obligaciones relativas a obligados tributarios inscritos en el Registro Tributario Nacional (RTN) y;

c) Siete (7) años en los demás casos; y, d) En caso de fallecimiento del obligado tributario, la prescripción de la acción de petición para solicitar devolución o repetición se suspende a favor de los herederos, por una sola vez por el término de tres (3) años, contados a partir de la fecha del fallecimiento.','144','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":144,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"b3e5190dafea9a05632c57baa142b37e4d8d5f1948e8b0e94828c3e86fd01669","ubicacion":["CAPÍTULO V","DE LA PRESCRIPCIÓN"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a144","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','144','b3e5190dafea9a05632c57baa142b37e4d8d5f1948e8b0e94828c3e86fd01669','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:145','mayalex_normativos','08_TRIBUTARIO','INICIO DELCÓMPUTO DEL PLAZO DE PRESCRIPCIÓN.

1) La prescripción de las acciones y atribuciones legales de la Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Administración Tributaria y la Administración Aduanera, según corresponda, para determinar el tributo y sus accesorios, realizar verificaciones o fiscalizaciones o para exigir el pago, debe comenzar a computarse a partir del día hábil siguiente en que se presente la declaración o que deba presentarse la misma o, cuando sea firme la resolución determinativa de una obligación tributaria o aduanera dictada por la Administración Tributaria o la Administración Aduanera;

2) La prescripción de la acción para exigir y hacer efectiva una multa debe comenzara computarse a partir del día hábil siguiente a la fecha en que se cometió la infracción o en que haya adquirido el carácter de firme la resolución administrativa o la sentencia judicial recaída; y,

3) La prescripción de la acción del obligado tributario para solicitar la devolución o repetición por tributos y accesorios debe comenzar a computarse a partir del día hábil siguiente en que se realizó el pago o entero en exceso.','145','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":145,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"7455ca60941078e1566ceff9b17a5e3d6e809c62228a2495f41d10f4026b7d1b","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a145","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','145','7455ca60941078e1566ceff9b17a5e3d6e809c62228a2495f41d10f4026b7d1b','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:146','mayalex_normativos','08_TRIBUTARIO','DECLARACIÓN DE LA PRESCRIPCIÓN.

1) La prescripción produce sus efectos legales una vez transcurridos los plazos establecidos en este Código; y,

2) Cuando la obligación tributaria o aduanera formal o material, haya prescrito al 30 de junio de cada año, según el procedimiento de depuración de la cuenta corriente establecido por la Administración Tributaria o Administración Aduanera, según corresponda, debe realizarse el descargo de oficio, en la medida que revise y actualice la cuenta corriente de los obligados tributarios. No obstante lo anterior, el obligado tributario tiene el derecho a solicitar que se limpie su cuenta corriente de sus obligaciones prescritas, y la Administración Tributaria o Administración Aduanera, según corresponda, debe ejecutarlo solicitado en el plazo establecido en el presente Código.','146','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":146,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"4b9ba7b8b1cc7a4a8a22461053fd0ebf0b6d1550b2c704c995c684f2579063bd","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a146","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','146','4b9ba7b8b1cc7a4a8a22461053fd0ebf0b6d1550b2c704c995c684f2579063bd','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:147','mayalex_normativos','08_TRIBUTARIO','EFECTOS DE LA PRESCRIPCIÓN.

1) La prescripción beneficia por igual a todos los obligados tributarios en sus obligaciones formales y materiales, salvo que se hubiese interrumpido el curso de la prescripción en beneficio para cualquiera de ellos;

2) La Administración Tributaria o la Administración Aduanera no pueden solicitar, obtener o utilizarla información sobre hechos o situaciones prescritos; salvo que el obligado tributario esté de acuerdo en entregar la información y documentación, y ésta obre en su poder;

3) La única información sobre períodos prescritos que puede ser requerida y obtenida por la Administración Tributaria o la Administración Aduanera, comprende los casos en que la misma sea necesaria para la comprobación de gastos por depreciaciones o amortizaciones e Impuesto Sobre Venta, que afecten a períodos fiscales no prescritos;

4) Lo pagado para satisfacer una obligación fiscal prescrita no dará derecho a repetir, aunque el pago se hubiera efectuado con o sin conocimiento de la prescripción; y,

5) La prescripción de la obligación tributaria o aduanera principal extingue todas las obligaciones accesorias.','147','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":147,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"161e04a67a5b91a4bf8c06430f234ca7702289e08f5576a167c634542f0bbddf","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a147","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','147','161e04a67a5b91a4bf8c06430f234ca7702289e08f5576a167c634542f0bbddf','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:148','mayalex_normativos','08_TRIBUTARIO','INTERRUPCIÓN DE LA PRESCRIPCIÓN.

1) El curso de la prescripción se interrumpe por las causas siguientes:

a) A partir del día hábil siguiente a la fecha de la notificación, del inicio del procedimiento encaminado a determinar o liquidar el tributo o a establecer la infracción que da lugar a la sanción o la existencia de la misma. Se entiende no producida la interrupción del curso de la prescripción, si las actuaciones no se inician en un plazo máximo de treinta (30) días, contados a partir de la fecha de la notificación o si, una vez iniciadas, se suspenden por más de sesenta (60) días;

b) A partir del día hábil siguiente de la interposición del recurso legal que proceda;

c) A partir del día hábil siguiente a cualquier actuación del obligado tributario dirigida a regularizar su situación:

d) A partir del día hábil siguiente a la notificación de la resolución que confirme los ajustes del tributo o sanciones y que contenga la cantidad liquida exigible; y, e) A partir del día hábil siguiente en que se interponga la acción judicial de cobro que corresponda.

2) La prescripción de la acción de devolución al obligado tributario se interrumpe:

a) Por la presentación del recurso correspondiente; y, b) Por la interposición de la demanda ante la autoridad judicial competente, salvo desistimiento o caducidad de la instancia.

3) Producida la interrupción, se debe iniciar de nuevo el cómputo del plazo de prescripción.','148','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":148,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"1be51442b09480ae3011e4f405872fb92cc5889157eb917b2e6c014b098049e8","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a148","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','148','1be51442b09480ae3011e4f405872fb92cc5889157eb917b2e6c014b098049e8','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:149','mayalex_normativos','08_TRIBUTARIO','CONCEPTO Y CLASIFICACIÓN DE INFRACCIONES.

1) Por infracción se entiende toda acción u omisión que contravenga el ordenamiento jurídico tributario o aduanero, siempre que se encuentre tipificada como tal en el presente Código Tributario o en otras leyes tributarias o aduaneras vigentes y aplicables;

2) La infracción debe ser siempre determinada en forma objetiva y sancionada administrativamente, siguiendo el debido proceso y garantizando el derecho a la defensa;

3) Las infracciones se clasifican en faltas y en delitos:

a) Constituye falta todo incumplimiento de normas tributarias o aduaneras, por comisión o por omisión, que esté tipificado y sancionado en este Código o en las leyes tributarias o aduaneras vigentes; y, b) Los delitos tributarios están contenidos en el Código Penal y su sanción corresponde exclusivamente a los Juzgados y Tribunales de Justicia.','149','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":149,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"d5d5f2a8c19e36ef5576858e395c3823bfe23986db009f0e48476a7ea39f2266","ubicacion":["TÍTULO SEXTO","LAS INFRACCIONES Y SANCIONES TRIBUTARIAS","CAPÍTULO I","DISPOSICIONES GENERALES SECCIÓN PRIMERA","DISPOSICIONES PRELIMINARES"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a149","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','149','d5d5f2a8c19e36ef5576858e395c3823bfe23986db009f0e48476a7ea39f2266','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:150','mayalex_normativos','08_TRIBUTARIO','TIPOS DE FALTAS. Son faltas tributarias o aduaneras el incumplimiento de las obligaciones formales y materiales de los obligados tributarios.','150','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":150,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"04188680dd537b253c9cbe9384cc87dfc16bf9af456c6702668820d76d1fac50","ubicacion":["SECCIÓN SEGUNDA","NORMAS GENERALES SOBRE FALTAS"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a150","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','150','04188680dd537b253c9cbe9384cc87dfc16bf9af456c6702668820d76d1fac50','OLA9_CTRIB_2024_01',now())
