INSERT INTO public.biblioteca_vectores (id,coleccion,materia,contenido,num_articulo,fuente,metadata,embedding,jurisdiccion,fuente_tipo,es_norma_vigente,revision_pendiente,instrumento_id,num_articulo_norm,hash_contenido,ingest_batch,ingested_at) VALUES
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:151','mayalex_normativos','08_TRIBUTARIO','PRINCIPIOS Y NORMAS APLICABLES.

1) Las disposiciones de este Título se aplican a todas las faltas tributarias y aduaneras;

2) De conformidad con el Artículo 95 de la Constitución de la República, ningún obligado tributario puede ser sancionado por infracciones y faltas no establecidas previamente en la Ley. Las faltas, sus características y circunstancias deben estar tipificadas en este Código y la Ley;

3) A falta de normas expresas sobre faltas, no pueden aplicarse normas supletorias, extensivas o análogas;

4) Las normas reglamentarias dictadas por los órganos de la Administración Pública, no pueden crear faltas o infracciones y se limitan solamente a desarrollar de manera específica los procedimientos asociados con la aplicación de las mismas respetando el debido proceso y el derecho a la defensa; y,

5) Las normas reglamentarias o actos administrativos de cualquier naturaleza que contravengan lo anteriormente expuesto, son nulos de pleno derecho inaplicables a los obligados tributarios. El funcionario autorizante de dichas normas o quien las aplique, es responsable conforme a lo dispuesto en el Código Penal.','151','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":151,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"8c30132e5b5d54da933360425a89a656e97f88a3c81431f7ba3247a104d150e5","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a151","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','151','8c30132e5b5d54da933360425a89a656e97f88a3c81431f7ba3247a104d150e5','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:152','mayalex_normativos','08_TRIBUTARIO','PRINCIPIO DE NO CONCURRENCIA.

1) El Principio de No Concurrencia implica evitarla doble persecución cuando se aprecia identidad del sujeto, hecho y fundamento, tanto en la relación entre infracciones administrativas y delitos, como a lo interno mismo de las infracciones administrativas;

2) En las conductas objetivamente tipificadas y que pudieran ser constitutivas de delitos tributarios, la Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Administración Tributaria o la Administración Aduanera, debe trasladar el expediente a conocimiento del Ministerio Público (MP) y abstenerse de concluir el procedimiento administrativo, mientras la autoridad judicial no dicte sentencia y esta adquiera el carácter de firme, tenga lugar el sobreseimiento o el archivo de las actuaciones o se produzca la devolución o el archivo por el Ministerio Público. A estos efectos, la sanción de la autoridad judicial producto de una sentencia condenatoria excluye la imposición de la sanción administrativa establecida en la Ley;

3) De no haberse estimado la existencia de la comisión de un posible delito, la Secretaría Estado en el Despacho de Finanzas, la Administración Tributaria y la Administración Aduanera, de acuerdo al ámbito de su competencia, debe continuar el expediente sancionador si procede, en base a los hechos que los Tribunales hayan considerado probados y se debe reanudar el cómputo del plazo de prescripción en el momento procesal en el que estaba cuando se suspendió. Las actuaciones administrativas realizadas durante el período de suspensión se tienen por inexistentes,

4) En los casos constitutivos de delito, además de las sanciones pecuniarias que correspondan aplicar en la vía penal, se debe exigir, de acuerdo con el numeral anterior, el pago de los tributos omitidos, sin que ello afecte el proceso penal;

5) Una misma acción u omisión que deba aplicarse como criterio de graduación de una falta no puede ser sancionada como falta independiente. La multa o sanción principal no causa intereses;

6) La realización de varias acciones u omisiones constitutivas de varias faltas supone la imposición de las sanciones que procedan por todas ellas. En este sentido, se consideran faltas separadas la reincidencia de incumplimientos formales precedidos de distintos requerimientos administrativos. Sin embargo, si las acciones u omisiones que conforman el tipo de una infracción o falta pueden ser considerados como preparatorios de o incluidos en otro tipo de infracción o falta, sólo procede la sanción correspondiente a este último, salvo que la sanción por la falta subsumida sea mayor, en cuyo caso es ésta la aplicable; y,

7) En caso que el mismo hecho infractor transgreda más de un tipo de infracción o falta administrativa, sin que la aplicación de uno excluya la aplicación del otro, debe aplicarse la sanción más grave.','152','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":152,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"bcc710ace615fac679004e56e8f0f48cd96769839912e7d6e04a1305b8dc21f0","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a152","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','152','bcc710ace615fac679004e56e8f0f48cd96769839912e7d6e04a1305b8dc21f0','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:153','mayalex_normativos','08_TRIBUTARIO','APLICACIÓN DE SANCIONES POR FALTAS TRIBUTARIAS O ADUANERAS.

1) La investigación, determinación y sanción de las faltas, corresponde a la Administración Tributaria, Administración Aduanera o a la Secretaría de Estado en el Despacho de Finanzas (SEFIN), en el ámbito de sus competencias;

2) Cada falta se debe sancionar en forma independiente de cualesquiera otras en un solo acto administrativo, siempre que esté tipificada en este Código o demás leyes tributarias o aduaneras; y,

3) La aplicación de estas sanciones y su cumplimiento no liberan al infractor de la responsabilidad de la obligación tributaria o aduanera, incluyendo intereses.','153','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":153,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"b165779d9106b248bff3b34c95077ac3d43086482fedb3cf811b4443b93e3fc0","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a153","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','153','b165779d9106b248bff3b34c95077ac3d43086482fedb3cf811b4443b93e3fc0','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:154','mayalex_normativos','08_TRIBUTARIO','SUJETOS INFRACTORES.

1) Son sujetos infractores las personas naturales o jurídicas y demás relacionadas en el presente Código, que realicen acciones u omisiones tipificadas como faltas en las leyes; y,

2) Por la concurrencia de varios sujetos infractores en la realización de una falta tributaria o aduanera, éstos son solidariamente responsables frente a la Administración Tributaria, Administración Aduanera o a la Secretaría de Estado en el Despacho de Finanzas (SEFIN), para el pago de la sanción, cuando ésta sea pecuniaria. Para que dicha responsabilidad se pueda exigir, debe notificarse a los sujetos responsables a quienes se les pretende imponer la sanción, a efectos que puedan hacer uso de los recursos contenidos en el presente Código.','154','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":154,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"df1dc7f56aefdc36c76b59226d589e2f15f4e80d210279965c8060cee94d66ba","ubicacion":["SECCIÓN TERCERA","DE LA RESPONSABILIDAD"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a154","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','154','df1dc7f56aefdc36c76b59226d589e2f15f4e80d210279965c8060cee94d66ba','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:155','mayalex_normativos','08_TRIBUTARIO','CAUSANTES O COLABORADORES.

1) Son causantes o colaboradores de una falta a todas las personas no incluidas en el Artículo anterior que directamente estén relacionadas con una falta, en particular:

a) Los cómplices e instigadores, considerándose como tales a los que con conocimiento instiguen o ayuden de cualquier manera al autor, según el caso;

b) El que, para su provecho personal o de un tercero, adquiera o tenga en su poder, oculte, venda o colabore en la venta o negociación de mercaderías, productos u objetos respecto de los cuales sepa o deba saber, conforme a las circunstancias, que se ha cometido una falta; y, c) Los terceros que, aun cuando no tuvieran obligaciones tributarias o aduaneras a su cargo, faciliten por dolo o culpa una falta, ya sea que obtengan o no un beneficio personal.

2) Los causantes o colaboradores son responsables solidarios de la sanción junto a los sujetos infractores, según lo dispuesto en este Código, una vez que la resolución judicial que declare el grado de participación como causante o colaborador, en el proceso penal, adquiera el carácter de firme; y,

3) Las conductas y personas referidas en los numerales anteriores sólo pueden ser sancionadas conforme a los tipos penales y procedimientos contenidos en el Código Penal y Código Procesal Penal. La responsabilidad penal corresponde investigarla al Ministerio Público y juzgarla a los Tribunales competentes.','155','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":155,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"f9624aaf1bb790b4cfd4145f8d0ab50c5f578a3ddccb252a220e9deb5999ddd1","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a155","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','155','f9624aaf1bb790b4cfd4145f8d0ab50c5f578a3ddccb252a220e9deb5999ddd1','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:156','mayalex_normativos','08_TRIBUTARIO','RESPONSABILIDAD SUBJETIVA.

1) En el caso de personas jurídicas, la responsabilidad subjetiva se configura en tanto se compruebe que, dentro de su organización interna, se ha faltado al deber de cuidado que hubiera impedido la falta, sin necesidad de determinar la responsabilidad concreta de sus administradores, directores, curadores, fiduciarios y demás personas naturales involucradas; y,

2) Las personas jurídicas y los patronos en general, son responsables por las sanciones pecuniarias aplicables a las faltas cometidas por sus dependientes en su actuación como tales, en tanto se compruebe su falta al deber de vigilancia sobre éstos que hubiera impedido la falta.','156','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":156,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"bd8ef08d48241c4d61b185c0d341c1c24a2a04f62e398a21d184366dff5d4a57","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a156","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','156','bd8ef08d48241c4d61b185c0d341c1c24a2a04f62e398a21d184366dff5d4a57','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:157','mayalex_normativos','08_TRIBUTARIO','EXIMENTES DE RESPONSABILIDAD. Las acciones u omisiones tipificadas en las leyes no dan lugar a responsabilidad por falta tributaria o aduanera, en los supuestos siguientes:

1) Cuando se realicen por quienes carezcan de capacidad de obrar en el ejercicio en el orden tributario o aduanero;

2) Cuando concurra caso fortuito o fuerza mayor;

3) Cuando deriven de una decisión colectiva, para quienes hubieran salvado su voto o no hubieran asistido a la reunión en que se adoptó la misma;

4) Cuando se haya actuado bajo subordinación jerárquica, siempre que la orden no revista el carácter de una evidente falta;

5) Cuando se haya actuado con la diligencia necesaria en el cumplimiento de las obligaciones tributarias o aduaneras. Entre otros supuestos, se entiende que se ha puesto la diligencia necesaria cuando el obligado tributario haya actuado amparándose en una interpretación razonable de la norma. También se entiende que se ha puesto la diligencia necesaria cuando se haya determinado o valorado elementos del hecho generador o de la base imponible con fundamento técnico suficiente, aunque luego se considere que ha mediado error; y,

6) Cuando sean imputables a una deficiencia técnica de los programas informáticos de asistencia facilitados por la autoridad competente para el cumplimiento de las obligaciones tributarias o aduaneras.','157','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":157,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"ac9948b1d5ebd14f38c2f6bb67b7784b7fce6cc899bbb6ebd820fd50c91955e2","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a157","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','157','ac9948b1d5ebd14f38c2f6bb67b7784b7fce6cc899bbb6ebd820fd50c91955e2','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:158','mayalex_normativos','08_TRIBUTARIO','TIPOS DE SANCIONES. Las sanciones administrativas aplicables son:

1) Principal:

a) Multa: Es aplicable al incumplimiento de obligaciones formales y no causa intereses; y, b) Intereses: Son aplicables por el incumplimiento de obligaciones materiales, tal y como se encuentra regulado en este Código.

2) Accesorias, aplicables adicionalmente a la multa que corresponda:

a) La pérdida del derecho a gozar de beneficios, privilegios, prerrogativas o incentivos tributarios o aduaneros, cuando incumplan sus obligaciones por dos (2) años consecutivos o alternos;

b) El decomiso en materia aduanera;

c) La clausura del establecimiento;

d) La suspensión del Registro Tributario Nacional (RTN); y, e) La pérdida del derecho de obtener subvenciones públicas o la inhabilitación para participar en licitaciones públicas, cuando haya sido autor o colaborador en una falta material.','158','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":158,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"39ca2257d2591164a9707ef67e51851a90135c1e1ba48952bef656dd9953b6c6","ubicacion":["SECCIÓN CUARTA","SANCIONES"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a158","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','158','39ca2257d2591164a9707ef67e51851a90135c1e1ba48952bef656dd9953b6c6','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:159','mayalex_normativos','08_TRIBUTARIO','SANCIÓN INDEPENDIENTE DE FALTAS MATERIALES Y

FORMALES. Las faltas formales se deben sancionar siempre en forma independiente de las faltas materiales, sin perjuicio de lo dispuesto para los casos excepcionales prescritos en este Código.','159','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":159,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"4128a817c264eaee79cef7f2df5a4b26e09ff1207cd784cbf9b9f31af92110a5","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a159","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','159','4128a817c264eaee79cef7f2df5a4b26e09ff1207cd784cbf9b9f31af92110a5','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:160','mayalex_normativos','08_TRIBUTARIO','CÁLCULO DE LA SANCIÓN POR FALTAS FORMALES.

1) Las sanciones a la infracción de las obligaciones formales contenidas en el presente Código, se debe calcular conforme a la tabla siguiente:

Rango de Ingresos Brutos Anuales Sanción

Debe aplicar una multa equivalente al

De L 0.01 Hasta L 250,000.00 10% de un salario mínimo promedio vigente.

Debe aplicar una multa equivalente al

De L 250,000.01 Hasta L 500,000.00 25% de un salario mínimo promedio vigente.

Debe aplicar una multa equivalente al

De L 500,000.01 Hasta L. 1,000,000.00 50% de un salario mínimo promedio vigente.

Debe aplicar una multa equivalente a

De L 1,000,000.01 Hasta L 5,000,000.00 un salario mínimo promedio vigente.

Debe aplicar una multa equivalente a

De L 5,000,000.01 Hasta L 10,000,000.00 dos salarios mínimos promedio vigente.

Debe aplicar una multa equivalente a

De L 10,000,000.01 Hasta L 50,000,000.00 cinco salarios mínimos promedio vigente.

Debe aplicar una multa equivalente a

De L 50,000,000.01 Hasta L.100,000,000.00 diez salarios mínimos promedio vigente.

Más de L 100,000,000.00 Debe aplicar una multa equivalente a diez salarios mínimos promedio vigente, más el 1% de un salario mínimo promedio vigente a razón de L 500,000.00 de ingresos brutos adicionales a L 100,000,000.00.

2) Cuando se trate del Impuesto Sobre la Renta, la falta de declaración o la presentación fuera de tiempo, se debe sancionar en forma no acumulativa de la manera siguiente:

a) Con una multa proporcional a los días transcurridos, equivalente al cinco por ciento (5%) del impuesto causado, si el retraso ocurre dentro del primer mes;

b) Con una multa proporcional a los días transcurridos, equivalente al diez por ciento (10%) del impuesto causado, si el retraso ocurre dentro del segundo mes;

c) Con una multa proporcional a los días transcurridos, equivalente al quince por ciento (15%) del impuesto causado, si el retraso ocurre dentro del tercer mes;

d) Con una multa proporcional a los días transcurridos, equivalente al veinte por ciento (20%) del impuesto causado, si el retraso ocurre dentro del cuarto mes; y, e) Con una multa proporcional a los días transcurridos, equivalente al veinticinco por ciento (25%) del impuesto causado, si el retraso ocurre dentro del quinto mes y en adelante.

3) En el caso que se trate de cualquier otro impuesto conexo o cedular relacionado con el Impuesto Sobre la Renta, se está a lo dispuesto en las leyes especiales y, en su defecto, a la gradualidad del numeral anterior;

4) Cuando se trate del Impuesto Sobre Ventas, la multa es igual al uno por ciento (1%) del respectivo tributo, si la declaración se presenta dentro de los cinco (5) días posteriores a la fecha de presentación y pago; después de este plazo la multa es de dos por ciento (2%) por cada mes o fracción de atraso, hasta un máximo del veinticuatro por ciento (24%);

5) Cuando se trate de las infracciones previstas en la Ley de Aduanas y demás disposiciones legales en materia aduanera, son sancionadas con una multa del veinticinco por ciento (25%) sobre el valor de los tributos dejados de percibir, exceptuando las faltas por clasificación aduanera, las cuales deben generar una multa del diez por ciento (10%) sobre el valor de los tributos dejados de percibir;

6) Cuando no haya tributo aduanero a pagar, se debe aplicar una multa equivalente a dos (2) salarios mínimos promedio vigente;

7) Cuando por cualquier causa imputable se destruya o deteriore bienes o mercancías que se encuentren en un recinto fiscal, se debe imponer al responsable una multa igual al valor que el Estado deba restituir al propietario en concepto de daños y perjuicios, independientemente de la responsabilidad penal en que incurra;

8) A los efectos de este Capítulo, se deben considerar los ingresos brutos declarados o, determinados por la Administración Tributaria en el último ejercicio fiscal cerrado a la fecha de la comisión de la infracción. Cuando el obligado tributario hubiera iniciado actividad menos de doce (12) meses antes de la comisión de la falta, se debe aplicar un veinticinco por ciento (25%) de un salario mínimo promedio vigente como sanción y no se debe tener en cuenta la tabla del numeral 1) de este Artículo;

9) Existe reincidencia siempre que el sancionado por sentencia o resolución firme cometiere una nueva infracción del mismo tipo dentro del plazo de veinticuatro (24) meses contados a partir de la comisión de aquél. La reincidencia se debe castigar con la sanción prevista para la infracción más un incremento del veinticinco por ciento (25%) de la misma; y,

10) La sanción a la infracción de las obligaciones formales contenidas en los artículos 69, 70 y 71 del presente Código, es de tres (3) salarios mínimos promedio vigente y la destitución del cargo por su superior inmediato, sin responsabilidad de cualquier tipo para el Estado.','160','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":160,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"50c928f05ef29a1d08d053f2c5192ee1648a382aa64933cf56c05cf5f10aeacd","ubicacion":["CAPÍTULO II","SANCIONES APLICABLES A LAS FALTAS TRIBUTARIAS O ADUANERAS","FORMALES"],"constancias":[{"nota":21,"tipo":"FE_DE_ERRATAS","texto":"Artículo 160. Numeral 6) Se corrigen las palabras “Cuando no haya ingreso bruto anual” por las palabras “Cuando no haya tributo aduanero a pagar”. Mediante Fe de Errata publicada en el Diario Oficial La Gaceta No.34,347 de fecha 25 de mayo de 2017.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a160","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','160','50c928f05ef29a1d08d053f2c5192ee1648a382aa64933cf56c05cf5f10aeacd','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:161','mayalex_normativos','08_TRIBUTARIO','SANCIÓN DE CIERRE TEMPORAL DE UN ESTABLECIMIENTO.

1) La sanción de cierre de un establecimiento, oficina o el sitio donde se ejerza la actividad comercial, profesional u oficio se debe aplicar:

a) Cuando no expida documento fiscal, estando obligado a ello o expedirlo sin cumplir con los requisitos establecidos en el marco legal vigente aplicable;

b) Cuando un documento fiscal expedido por aquel no se encuentra registrado en la contabilidad;

c) Cuando no presente los registros de ventas, compras, costeo y retenciones requeridos por la Administración Tributaria o la Administración Aduanera; y, d) Cuando el obligado tributario lleve doble contabilidad o utilice doble facturación, sin perjuicio de las demás sanciones estipuladas en el presente Código y demás leyes aplicables.

2) El cierre es temporal cuando se evidencie cualquiera de las circunstancias descritas en los incisos del numeral anterior, excepto el inciso d);

3) La aplicación de la sanción del cierre de un establecimiento, oficina o el sitio donde se ejerza la actividad comercial, profesional u oficio se debe realizar conforme al procedimiento siguiente:

a) Por el incumplimiento de los incisos del numeral 1) del presente Artículo, excepto el inciso d), se debe imponer una multa según el rango de ingresos brutos anuales del obligado tributario infractor, conforme a lo establecido en el presente Código. Seis (6) días hábiles después de haber aplicado la citada sanción, la autoridad competente, debe verificar y comprobar que el obligado tributario haya regularizado su situación;

b) Por la primera reincidencia de una misma falta, exceptuando lo establecido en el referido inciso d) del numeral 1) del presente Artículo, se debe imponer una multa según el rango de ingresos brutos anuales del obligado tributario infractor, conforme a lo establecido en el presente Código, incrementada en un cincuenta por ciento (50%) del valor de la multa que corresponda. Seis (6) días hábiles después de haber aplicado la citada sanción, la autoridad competente debe verificar y comprobar que el obligado tributario haya regularizado su situación;

c) Por reincidencia de una misma falta tributaria, se debe proceder al cierre temporal, por un período indefinido, sin perjuicio del pago de las multas ya impuestas. El cierre indefinido debe durar hasta que el obligado tributario regularice su situación; y, d) Por reincidencia, se debe entender, incurrir por segunda o ulterior vez, en el incumplimiento de la misma obligación tributaria o aduanera dentro de un mismo período fiscal anual.

4) El servidor de la Administración Tributaria o la Administración Aduanera que identifique la infracción, debe consignarla en un acta de constatación de hechos y notificarla al obligado tributario dentro de veinticuatro (24) horas hábiles;

5) Para efectuar la aplicación del cierre de un establecimiento, oficina o el sitio donde se ejerza la actividad comercial, profesional u oficio, la Administración Tributaria o la Administración Aduanera, según corresponda, debe utilizar fajas o cintas, debidamente selladas, en señal de cierre o clausura. En caso de ruptura de las mismas se debe interponer la denuncia penal en contra del obligado tributario infractor,

6) La imposición de las sanciones contenidas en este Artículo, corresponden sin perjuicio de la obligación del obligado tributario de pagar o enterar los tributos que haya dejado de recaudar o que no haya enterado al Estado;

7) Las resoluciones impositivas de la sanción contenida en el literal c) del numeral 3) de este Artículo, no son susceptibles de ulterior recurso en la vía administrativa y tienen por agotada la misma, las cuales pueden ser impugnadas “per saltum”, para él solo efecto de su suspensión, sin requerir de publicación alguna, ante el Juez de Letras de lo Contencioso Administrativo competente, dentro de un plazo de tres (3) días hábiles contados a partir del día siguiente de la notificación de la misma.

En aquellos lugares en que no haya un Juzgado de la materia Contencioso Administrativo, debe conocer de la solicitud de suspensión un Juez de Letras o, en caso de no existir éste, un Juez de Paz, debiendo tramitarse conforme a lo dispuesto en los artículos 120 al 124 de la Ley de la Jurisdicción de lo Contencioso Administrativo.

8) Procede la suspensión cuando la ejecución ocasione daños o perjuicios de imposible o difícil reparación. En el trámite de la suspensión se debe dar vista a la administración demandada por un plazo de tres (3) días hábiles para que se pronuncie y acompañe el expediente correspondiente sin ningún hecho adicional a los expresados en la resolución administrativa, debiendo el juez competente emitir su resolución verbalmente, dentro del plazo improrrogable de diez (10) días hábiles contados a partir del día siguiente de la admisión de la impugnación correspondiente, salvo que de oficio dicte medidas para mejor proveer o que el impugnante solicite el ofrecimiento de pruebas.

9) El juez que no dicte la resolución en el plazo establecido en el numeral anterior, es responsable personalmente ante el Estado y el obligado tributario por los daños y perjuicios que ocasione;

10) El procedimiento contentivo en los numerales 7) y 8) anteriores, debe aplicarse sin perjuicio del trámite ordinario para impugnar las demás sanciones contenidas en los literales a) y b) del numeral 3) del presente Artículo; y,

11) La parte actora puede reclamar daños y perjuicios dentro al plazo y al procedimiento contenido en el Artículo 124 de la Ley de la Jurisdicción de lo Contencioso Administrativo o, a su elección, por la vía ordinaria contenida en la misma Ley.','161','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":161,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"4d61fc39c048564dde5b0293af0a6222421fbe27d601de0a610e539cf1a3a056","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a161","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','161','4d61fc39c048564dde5b0293af0a6222421fbe27d601de0a610e539cf1a3a056','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:162','mayalex_normativos','08_TRIBUTARIO','REDUCCIÓN DE SANCIONES POR INFRACCIONES FORMALES.

1) Cuando el infractor rectifique o subsane el incumpliendo de la obligación formal, se le debe conceder una rebaja del monto correspondiente a las multas, intereses y recargos de conformidad con los porcentajes siguientes:

a) Un cincuenta por ciento (50%), si el infractor regulariza su situación con el Estado, antes de cualquier actuación de la autoridad competente relativo a la infracción cometida;

b) Un treinta por ciento (30%) si, mediando actuación de la autoridad competente, regulariza su situación sin la presentación de recursos, antes de que aquella le determine y notifique el pago de la multa o inicie el procedimiento de cobro;

c) Un diez por ciento (10%) si regulariza su situación antes del requerimiento de pago de la multa realizado por la autoridad judicial; y, d) Si el obligado tributario está categorizado como pequeño contribuyente, tiene una reducción adicional de veinte por ciento (20%) a los porcentajes establecidos en los literales anteriores, según corresponda.

2) Para los efectos del presente Artículo, se entiende como actuación de la autoridad competente toda acción de cobro realizada y notificada al obligado tributario.','162','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":162,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"fcdd1d3271ad0eb9d00b8aa0aeedfc029425aacde7f2db6b0cc0a57a44ddb116","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a162","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','162','fcdd1d3271ad0eb9d00b8aa0aeedfc029425aacde7f2db6b0cc0a57a44ddb116','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:163','mayalex_normativos','08_TRIBUTARIO','INTERESES POR FALTA DE PAGO

1) A falta de pago en plazo de los tributos y de los pagos a cuenta, el obligado tributario debe pagar a favor del Estado:

a) El adeudo tributario o aduanero o su saldo; y, b) Los intereses moratorios del tres por ciento (3%) mensual o fracción de mes calculado sobre el tributo a pagar, acumulándose mensualmente hasta que se produzca el pago, hasta un máximo de treinta y seis por ciento (36%).

2) El no entero en los plazos establecidos de los tributos retenidos o recaudados por parte de los agentes de retención o percepción y de las retenciones por pagos en especie, obliga a éstos a pagarle al Estado:

a) Las sumas debidas; y, b) Los intereses moratorios del cinco por ciento (5%) mensual o fracción de mes calculado sobre el tributo a pagar, acumulándose mensualmente hasta que se produzca el pago, hasta un máximo de sesenta por ciento (60%).

3) Por los pagos realizados de declaraciones presentadas fuera de plazo legal, se debe conceder una rebaja del monto correspondiente a los intereses, de conformidad con los porcentajes siguientes:

a) Un cincuenta por ciento (50%), si el obligado tributario regulariza su situación con el Estado, antes de cualquier actuación de la autoridad competente; y, b) Un treinta por ciento (30%) si regulariza su situación antes del requerimiento de pago realizado por la autoridad judicial.

4) Para los efectos del literal a) del numeral 3) anterior, se entiende como actuación de la autoridad competente toda acción de cobro realizada y notificada al obligado tributario.','163','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":163,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"b36cbe964875bbb7219d2cca6a80d1e99b933de621142c7f6335a43378b8b5f5","ubicacion":["CAPÍTULO III","SANCIÓN APLICABLE A LAS FALTAS MATERIALES"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a163","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','163','b36cbe964875bbb7219d2cca6a80d1e99b933de621142c7f6335a43378b8b5f5','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:164','mayalex_normativos','08_TRIBUTARIO','SUSPENSIÓN DEL REGISTRO TRIBUTARIO NACIONAL.

La sanción de suspensión del Registro Tributario Nacional (RTN) debe aplicarse cuando un obligado tributario no se encuentre solvente en el cumplimiento de obligaciones materiales, ya sea producto de una autoliquidación o liquidación de oficio, siempre y cuando se hayan agotado todos los recursos en vía administrativa y la obligación haya adquirido el carácter de firme, líquida y exigible. Cumplidos estos supuestos se debe proceder de la forma siguiente:

1) Se debe notificar un primer aviso de cobro al obligado tributario para que proceda al pago del principal y accesorios que correspondan en un término de cinco (5) días hábiles contados a partir del día siguiente de recibida la notificación;

2) Se debe notificar un segundo aviso de cobro al obligado tributario para que proceda al pago del principal y accesorios que correspondan en un término de tres (3) días hábiles contados a partir del día siguiente de recibida la notificación;

3) Incumplidos los llamamientos realizados conforme a los numerales anteriores, la autoridad competente debe emitir la resolución mediante la cual ordene suspender el Registro Tributario Nacional (RTN) del obligado tributario; y,

4) En el momento en que regularice su situación con el Estado, inmediatamente y sin trámite alguno, de oficio o a petición del mismo obligado tributario, se debe poner fin a esta medida administrativa.','164','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":164,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"4a7ccf978298f4d5e8df0888d4a3f44e54b488253e023a2e4385abca12ff2442","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a164","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','164','4a7ccf978298f4d5e8df0888d4a3f44e54b488253e023a2e4385abca12ff2442','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:165','mayalex_normativos','08_TRIBUTARIO','CONCEPTO DE DELITOS TRIBUTARIOS. Son delitos tributarios los tipificados en el Código Penal.','165','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":165,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"0ccad9bee008414e63b19dcac9e67e6e26715a2693a56036a72f3ff62055b9d6","ubicacion":["TÍTULO SÉPTIMO","DELITOS TRIBUTARIOS"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a165","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','165','0ccad9bee008414e63b19dcac9e67e6e26715a2693a56036a72f3ff62055b9d6','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:166','mayalex_normativos','08_TRIBUTARIO','ACUSACIÓN. Para proceder penalmente por los delitos tributarios previstos en el Código Penal es necesario que la Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Administración Tributaria o la Administración Aduanera, según el caso, formule la denuncia ante el Ministerio Público (MP) o la Procuraduría General de la República (PGR), sin perjuicio de las facultades de éstos para actuar de oficio. En los casos de flagrancia no es necesaria dicha denuncia.

Lo dispuesto en el párrafo anterior no es obstáculo para que los particulares o los servidores públicos denuncien ante el Ministerio Público (MP) o la Procuraduría General de la República (PGR), la comisión de cualquiera de los delitos previsto en la Ley.','166','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":166,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"212d7d9701d3bfe96ab51183db89f87d597a77a261772ca1e387bfae3bc4dcae","ubicacion":[],"constancias":[{"nota":22,"tipo":"FE_DE_ERRATAS","texto":"Artículo 166. Se corrige la palabra “fragancia” por la palabra “flagrancia”. Mediante Fe de Errata publicada en el Diario Oficial La Gaceta No.34,347 de fecha 25 de mayo de 2017.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a166","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','166','212d7d9701d3bfe96ab51183db89f87d597a77a261772ca1e387bfae3bc4dcae','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:167','mayalex_normativos','08_TRIBUTARIO','RESPONSABILIDAD POR CUMPLIMIENTO VOLUNTARIO. Se debe formular acusación a quien hubiere omitido el pago del tributo u obtenido el beneficio indebido, salvo cuando pague el tributo con sus multas e intereses legales, antes que el Ministerio Público presente requerimiento fiscal, ya sea por pago realizado en sede fiscal, ante la Autoridad Tributaria o ante la Autoridad Aduanera correspondiente. La autoridad fiscal, tributaria o aduanera no pueden negarse a recibir el pago conforme a lo dispuesto en el presente párrafo, debiendo proceder al cierre administrativo o en su caso aplicar el criterio de oportunidad a quien corresponda, con el consecuente archivo administrativo del caso.

En igual circunstancia, debe cesar la persecución penal cuando el obligado tributario pague las obligaciones tributarias principales y accesorias, así como la multa establecida en el Código Penal, siempre y cuando el pago se realice antes de la celebración de la audiencia preliminar, aplicando para ello la figura de la conciliación judicial, la que se debe aplicar en todos los casos a petición del imputado y en la cual no se puede exigir otro tipo de indemnizaciones distintas a las referidas en el presente Artículo.

Cuando concurran los requisitos del presente párrafo y los del Código Procesal Penal, la autoridad correspondiente no debe negar en ningún caso la aplicación de la Conciliación judicial.

Sin perjuicio de lo anterior, si se hace el pago en cualquier momento del proceso, el juez debe imponer medidas sustitutivas a la prisión preventiva, en tanto se celebra la audiencia de conciliación judicial respectiva.','167','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":167,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"089de30b5fc70b3c11d8ed934334b9eb9609e3ef7404f1c12872f37c1b6e104c","ubicacion":[],"constancias":[{"nota":23,"tipo":"INTERPRETACION_AUTENTICA","texto":"Artículo 167. Interpretado por Decreto No.25-2017 de fecha 30 de mayo de 2017 y publicado en el Diario Oficial La Gaceta No.34,353 de fecha 1 de junio de 2017. “Para efectos de aplicar un criterio de oportunidad en sede fiscal y conciliación en sede judicial, debe pagarse el monto del valor dejado de percibir por el delito tributario como única multa, que está establecida en el segundo párrafo del Artículo 392-E del Código Penal, que equivale al cincuenta por ciento (50%) del valor defraudado. Lo dispuesto en el párrafo anterior es aplicable a todos los procesos que se encuentren activos a la entrada en vigencia de este decreto de interpretación y a posteriores procesos.” Artículo 167. Último Párrafo. Derogado por Código Penal, Decreto No.130-2017 de fecha 18 de enero de 2018 y publicado en el Diario Oficial La Gaceta No.34,940 de fecha 10 de mayo de 2019. Vigente a partir del 10 de mayo de 2020.","decretos":["25-2017","130-2017"]},{"nota":null,"tipo":"REVISION_PENDIENTE_CLO","decretos":["25-2017","130-2017"],"texto":"Revisión pendiente: la nota de la edición anota la interpretación auténtica del D.25-2017, que remite al art. 392-E del Código Penal de 1983 (derogado por el D.130-2017), y la derogación del «último párrafo» por el Código Penal de 2017 (La Gaceta No. 34,940), sin indicar si el texto impreso ya lo excluye. CONTEXT vigente hasta dictamen del CLO."}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a167","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":"CONTEXT","motivo":"CONTEXT vigente (propuesta D5): interpretación auténtica (D.25-2017) que remite al art. 392-E del Código Penal de 1983, derogado; último párrafo derogado por el D.130-2017 sin que la edición indique cuál es"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','167','089de30b5fc70b3c11d8ed934334b9eb9609e3ef7404f1c12872f37c1b6e104c','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:168','mayalex_normativos','08_TRIBUTARIO','DISPOSICIÓN GENERAL. Las resoluciones que determinen tributos y sus accesorios, las que impongan sanciones o las que nieguen el reintegro o devolución de tributos pueden revisarse mediante:

1) Procedimientos de revisión de oficio; y,

2) Procedimientos a través de recursos administrativos.','168','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":168,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"c8002d91525ccb92c61c97ee677b88bc328bbbc2e7e7fd7df1515b44f142cd05","ubicacion":["TÍTULO OCTAVO","LOS PROCEDIMIENTOS DE REVISIÓN DE ACTOS TRIBUTARIOS O ADUANEROS","CAPÍTULO I","PROCEDIMIENTOS DE REVISIÓN DE OFICIO"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a168","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','168','c8002d91525ccb92c61c97ee677b88bc328bbbc2e7e7fd7df1515b44f142cd05','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:169','mayalex_normativos','08_TRIBUTARIO','CLASES DE RECURSOS.

1) Los obligados tributarios, los intervinientes en un proceso, así como los terceros a los que un acto o resolución le cause directamente un perjuicio, tienen derecho a recurrirla en los términos establecidos en este Código. Quien impugne una resolución administrativa, puede desistir del recurso en cualquier momento anterior a su resolución;

2) Las resoluciones señaladas en el numeral precedente, pueden impugnarse mediante:

a) El Recurso de Reposición;

b) El Recurso de Apelación; y, c) El Recurso Extraordinario de Revisión.

3) Sólo pueden revisarse las resoluciones administrativas a que se refiere el numeral 1) cuando reconozcan derechos o establezcan obligaciones, así como los actos de trámite que resuelvan directa o indirectamente el asunto;

4) Los recursos administrativos se deben ejercer por una sola vez en cada procedimiento administrativo y nunca simultáneamente; y,

5) El error en la calificación del recurso por parte del recurrente no es obstáculo para su tramitación siempre que del escrito se deduzca su verdadero carácter.','169','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":169,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"5cad28b8bcad51a1d312b74e2e41fdf8ffd1294fd950cfd5550efa293519d8ba","ubicacion":["CAPÍTULO II","RECURSOS ADMINISTRATIVOS SECCIÓN PRIMERA","DISPOSICIONES GENERALES"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a169","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','169','5cad28b8bcad51a1d312b74e2e41fdf8ffd1294fd950cfd5550efa293519d8ba','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:170','mayalex_normativos','08_TRIBUTARIO','DE LAS RESOLUCIONES.

1) Los órganos u organismos encargados de resolver no pueden abstenerse de dictar resolución por deficiencia de la Ley;

2) Las resoluciones de los recursos deben estar debidamente motivadas y fundamentadas en Ley por el órgano u organismo que resuelva la controversia y deben pronunciarse sobre todas las cuestiones planteadas por el recurrente y las que se susciten en el expediente, así como de las pruebas producidas o elementos considerados;

3) Las resoluciones de los recursos deben estimar en todo o en parte o deben desestimar las pretensiones formuladas en ellos; y,

4) La resolución por la que se resuelve un recurso no puede empeorar la situación del recurrente respecto a la que obtuvo en la resolución recurrida, salvo que medie un error aritmético el cual puede corregir la Secretaría de Estado en el Despacho de Finanzas (SEFIN), Superintendencia Tributaria Aduanera, la Administración Tributaria o la Administración Aduanera por sí o, por requerimiento del obligado tributario.','170','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":170,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"8a8bce29b403512be6963b8588e27feb4868b8d3cf71c4d36092ca61ec6d38ba","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a170","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','170','8a8bce29b403512be6963b8588e27feb4868b8d3cf71c4d36092ca61ec6d38ba','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:171','mayalex_normativos','08_TRIBUTARIO','DISPOSICIONES COMUNES EN MATERIA DE PRUEBA.

1) Si el recurrente solicitare apertura a pruebas o si el órgano encargado de resolver no tiene por ciertos los hechos alegados por la parte interesada, puede acordarse la apertura a pruebas por un término no menor de un (1) mes; y,

2) La Secretaría de Estado en el Despacho de Finanzas (SEFIN), Superintendencia Tributaria Aduanera, la Administración Tributaria o la Administración Aduanera, en la sustanciación del recurso, deben realizarlas acciones que sean necesarias para establecer la verdad de los hechos, por lo que pueden solicitar pruebas adicionales a las propuestas o realizar investigaciones o estudios que sirvan para aquel fin, los cuales deben presentarse o evacuarse en un plazo no mayor de veinte (20) días hábiles.','171','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":171,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"d1f17479907912e1e57867165e893af8b4884a833ff338ac0f8d53f387864b2d","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a171","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','171','d1f17479907912e1e57867165e893af8b4884a833ff338ac0f8d53f387864b2d','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:172','mayalex_normativos','08_TRIBUTARIO','RECURSO DE REPOSICIÓN. OBJETO Y NATURALEZA.

1) Contra las resoluciones que dicte la Administración Tributaria, la Administración Aduanera o de la Secretaría de Estado en el Despacho de Finanzas (SEFIN), según corresponda, debe proceder el recurso de reposición, a fin de que la misma institución que los dictó pueda proceder a su reconsideración; el que debe interponerse en el acto de la notificación o dentro de los quince (15) días hábiles siguientes a la fecha de aquélla: y

2) En materia aduanera este recurso se interpondrá ante la autoridad superior de servicio aduanero, dentro de los diez (10) días siguientes a la notificación de la resolución que se impugna.','172','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":172,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"be7989317bcdfe8d934381980d354a0dcf7fdd458bd33eb58e04e4790d74e713","ubicacion":["SECCIÓN SEGUNDA","RECURSO DE REPOSICIÓN"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a172","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','172','be7989317bcdfe8d934381980d354a0dcf7fdd458bd33eb58e04e4790d74e713','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:173','mayalex_normativos','08_TRIBUTARIO','CARACTERÍSTICAS DEL RECURSO.

1) Contra las resoluciones que emita la Administración Tributaria, la Administración Aduanera o las que emita la Secretaría de Estado en el Despacho de Finanzas (SEFIN) en única instancia, procede el Recurso de Reposición;

2) En contra de la resolución que emita la Administración Tributaria o Administración Aduanera que resuelva el Recurso de Reposición procede el Recurso de Apelación ante la Superintendencia Tributaria Aduanera. No puede promoverse Recurso de Apelación hasta que el Recurso de Reposición haya sido resuelto, salvo que el plazo legal para su emisión haya transcurrido; y,

3) La resolución que emita la Secretaría de Estado en el Despacho de Finanzas en única instancia, que resuelva el Recurso de Reposición agota la vía administrativa.','173','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":173,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"29a36ecf1150b66abaf183612de3e39857fc1a54e10bbf50795dc6f265177424","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a173","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','173','29a36ecf1150b66abaf183612de3e39857fc1a54e10bbf50795dc6f265177424','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:174','mayalex_normativos','08_TRIBUTARIO','SUSPENSIÓN DE LA EJECUCIÓN.

1) Interpuesto el Recurso de Reposición se suspende la ejecución del acto administrativo impugnado hasta que la resolución del referido recurso adquiera el carácter de firme, y,

2) Si el recurso no afecta a la totalidad de la deuda tributaria o aduanera, la suspensión aplica a la parte recurrida.','174','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":174,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"7c41a8c89be3de622c3217a78d96d501891f61a6484ac96d4301dbf63b2160f8","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a174","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','174','7c41a8c89be3de622c3217a78d96d501891f61a6484ac96d4301dbf63b2160f8','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:175','mayalex_normativos','08_TRIBUTARIO','RESOLUCIÓN DEL RECURSO DE REPOSICIÓN.

1) La resolución del Recurso de Reposición corresponde al órgano que dictó el acto administrativo impugnado.

2) La resolución debe dictarse en el plazo de veinte (20) días hábiles, contados a partir del día hábil siguiente en que se haya cerrado el período probatorio o no habiéndose decretado periodo probatorio, a partir del auto de admisión del recurso. Durante el plazo que medie entre la interposición del Recurso de Reposición y hasta que la deuda adquiera el carácter de firme se debe suspender la aplicación de intereses.

3) El funcionario responsable de no emitir la resolución en el plazo establecido, es directamente responsable de resarcir al Estado los perjuicios causados; y,

4) Vencido el plazo a que se refiere el numeral anterior, el interesado debe considerar rechazado el recurso a efectos de hacer uso de los recursos que correspondan, continuando la suspensión del cómputo de los intereses.','175','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":175,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"3f5f527bcc1b5799b05669133dfe0a40bca2a40b1c742e8a5aa5bee2c496a868","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a175","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','175','3f5f527bcc1b5799b05669133dfe0a40bca2a40b1c742e8a5aa5bee2c496a868','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:176','mayalex_normativos','08_TRIBUTARIO','RECURSO DE APELACIÓN. OBJETO Y NATURALEZA.

1) Tiene como objeto la revisión tanto de los hechos dados como probados en la resolución recurrida, como de la valoración de la prueba; y,

2) Se presenta ante la Administración Tributaria dentro del término de quince (15) días hábiles y, ante la Administración Aduanera dentro del término de diez (10) días hábiles, contados a partir del día hábil siguiente de la notificación de la resolución y, éstas lo deben remitir a la Secretaría de Estado en el Despacho de Finanzas, por conducto de la Superintendencia Tributaria Aduanera, para su decisión, junto con el expediente instruido, dentro del plazo de diez (10) días hábiles, contados a partir de la fecha de admisión del recurso.','176','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":176,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"20cc91b11169b75dfaaa3f9400be969df4b47436c9bfad1f9c876f11e39bcb27","ubicacion":["SECCIÓN TERCERA","RECURSO DE APELACIÓN"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a176","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','176','20cc91b11169b75dfaaa3f9400be969df4b47436c9bfad1f9c876f11e39bcb27','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:177','mayalex_normativos','08_TRIBUTARIO','SUSPENSIÓN DE LA EJECUCIÓN. La ejecución del acto administrativo impugnado se suspende hasta la resolución del recurso y que este adquiera el carácter de firme.','177','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":177,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"da8876d16233b4a1fef3aa7e897ea279e57536d0bb90038f5eb77811a7ccd28e","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a177","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','177','da8876d16233b4a1fef3aa7e897ea279e57536d0bb90038f5eb77811a7ccd28e','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:178','mayalex_normativos','08_TRIBUTARIO','RESOLUCIÓN DEL RECURSO DE APELACIÓN.

1) La resolución que emita la Secretaría de Estado en el Despacho de Finanzas por conducto de la Superintendencia Tributaria Aduanera, agota la vía administrativa. No cabe recurso alguno contra ella en la vía administrativa, con excepción de la solicitud de corrección de errores materiales o numéricos, ampliación de la resolución sobre puntos omitidos, aclaración de algún concepto dudoso de la resolución o de la interposición del Recurso Extraordinario de Revisión. La Superintendencia Tributaria Aduanera puede proceder de oficio en tales casos;

2) Durante el plazo que medie entre la interposición del Recurso de Apelación y hasta que la deuda adquiera el carácter de firme se suspende la aplicación de intereses;

3) El funcionario responsable de no emitir la resolución en el plazo establecido, es directamente responsable de resarcir al Estado los perjuicios causados; y,

4) Vencido el plazo a que se refiere el numeral anterior, el interesado debe considerar rechazado el recurso a efectos de hacer uso de los recursos que correspondan, continuando en la suspensión del cómputo de los intereses.','178','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":178,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"68965c7df2412fc53545908d1ca005e85e22e4ebc75edbe868588677232f3331","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a178","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','178','68965c7df2412fc53545908d1ca005e85e22e4ebc75edbe868588677232f3331','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:179','mayalex_normativos','08_TRIBUTARIO','RECURSO EXTRAORDINARIO DE REVISION. Contra las resoluciones firmes puede interponerse el recurso extraordinario de revisión cuando concurra alguna de las circunstancias siguientes:

1) Que el acto se hubiese dictado con evidente y manifiesto error de hecho que afecte a la cuestión de fondo, siempre que dicho error resulte plenamente demostrado de los documentos incorporados al expediente, sin perjuicio de lo dispuesto en el Capítulo I de este Título;

2) Que después de adoptada la resolución aparezcan documentos decisivos ignorados por fuerza mayor al dictarse la resolución o de imposible aportación entonces al expediente;

3) Que la resolución hubiera recaído en virtud de documento que al tiempo de adoptarse aquélla, ignorase alguno de los interesados haber sido reconocido y declarado falso en sentencia judicial firme o cuya falsedad se reconociese o declarase después;

4) Que, habiéndose adoptado la resolución en virtud de prueba testifical, fuesen los testigos condenados en sentencia judicial firme por falso testimonio dado en las declaraciones que sirvieron a aquélla de fundamento; y,

5) Que la resolución se hubiese dictado con prevaricación, cohecho, violencia u otra maquinación fraudulenta y se haya declarado así por sentencia judicial firme.','179','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":179,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"4507932463573375c7bf4faa1ee2d95f6e4713d6cdc913b139649344e88c2a96","ubicacion":["SECCIÓN CUARTA","RECURSO EXTRAORDINARIO DE REVISION"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a179","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','179','4507932463573375c7bf4faa1ee2d95f6e4713d6cdc913b139649344e88c2a96','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:180','mayalex_normativos','08_TRIBUTARIO','TRAMITACIÓN DEL RECURSO EXTRAORDINARIO DE REVISIÓN.

1) El Recurso de Revisión contra las resoluciones firmes de la Administración Tributaria o la Administración Aduanera se debe interponer ante la Secretaría de Estado en el Despacho de Finanzas por conducto de la Superintendencia Tributaria Aduanera, dentro de los dos (2) años siguientes a la fecha de notificación de la resolución impugnada, en los supuestos a que se refiere la primera causal del Artículo anterior;

2) El Recurso de Revisión contra las resoluciones firmes de la Secretaría de Estado en el Despacho de Finanzas (SEFIN) en única instancia, se debe interponer ante dicha Secretaría de Estado, dentro de los dos (2) años siguientes a la fecha de notificación de la resolución impugnada, en los supuestos a que se refiere la primera causal del Artículo anterior, y,

3) En los demás casos, el plazo es de dos (2) meses, contados desde el día en que hubieren sido descubiertos los documentos ignorados o desde que quedó firme la sentencia judicial.','180','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":180,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"19ecbb2843b6a216c768709173c132717081cc273034445a52eb27959b7b6207","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a180","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','180','19ecbb2843b6a216c768709173c132717081cc273034445a52eb27959b7b6207','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:181','mayalex_normativos','08_TRIBUTARIO','EFECTOS DEL RECURSO EXTRAORDINARIO DE REVISIÓN. Si se estimase procedente el recurso, se debe declarar la nulidad total o parcial de la resolución impugnada, mandando que se practiquen de oficio las actuaciones que procedan.','181','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":181,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"7ce29836691e24c03ad4d4c01c1b712056dc3ad80529f9be50d1255864503e3a","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a181","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','181','7ce29836691e24c03ad4d4c01c1b712056dc3ad80529f9be50d1255864503e3a','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:182','mayalex_normativos','08_TRIBUTARIO','PLAZOS DE RESOLUCIÓN. La resolución del recurso se debe dictar dentro de los treinta (30) días hábiles siguientes a su interposición.','182','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":182,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"87c654ebc8f65567ad0ba5418130b810ab615a1376ede8fb080d2073f65fdb36","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a182","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','182','87c654ebc8f65567ad0ba5418130b810ab615a1376ede8fb080d2073f65fdb36','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:183','mayalex_normativos','08_TRIBUTARIO','CREACIÓN Y ORGANIZACIÓN DE LA SUPERINTENDENCIA TRIBUTARIA ADUANERA.

1) Créase la Superintendencia Tributaria Aduanera, como una entidad especializada y desconcentrada funcionalmente de la Secretaría de Estado en el Despacho de Finanzas (SEFIN), con autoridad y competencia propia a nivel nacional, la cual se ejerce con autonomía técnica, administrativa y financiera;

2) A la Superintendencia Tributaria Aduanera le corresponden las funciones reguladas en el Código Aduanero Único Centroamericano (CAUCA) y su Reglamento (RECAUCA) para el Tribunal Aduanero;

3) Esta entidad administrativa, altamente especializada en temas tributarios y aduaneros, en el desempeño de sus funciones tiene independencia técnica y funcional, tanto de la Administración Tributaria y de la Administración Aduanera como de la Secretaría de Estado en el Despacho de Finanzas (SEFIN), con el propósito de realizar una eficaz atención y eficiente despacho de la tramitación y resolución de los recursos administrativos a su cargo;

4) El personal de la Superintendencia Tributaria Aduanera debe ser técnico y altamente calificado, seleccionado por méritos, mediante concurso y aprobar un proceso de selección que incluya la aplicación de pruebas psicométricas, de capacidad y de confianza. Para efectos de la determinación de su política de compensación, la Superintendencia Tributaria Aduanera no está sujeta al régimen ordinario de servicio civil, ni a las limitaciones que al respecto se establezcan para los empleados del Poder Ejecutivo;

5) A la Superintendencia Tributaria Aduanera, le corresponde resolver los Recursos de Apelación y de Revisión contra las resoluciones dictadas por la Administración Tributaria y por la Administración Aduanera y, contra las resoluciones administrativas que se dicten por el procedimiento de revisión de oficio, si el interesado los interpuso, siempre y cuando hayan sido dictadas por dichas administraciones;

6) Las resoluciones de la Superintendencia Tributaria Aduanera agotan la vía administrativa;

7) La Superintendencia Tributaria Aduanera no tiene competencia para conocer y resolver los recursos interpuestos en contra de la Secretaría de Estado en el Despacho de Finanzas (SEFIN) en única instancia. Los recursos que ésta resuelva agotan la vía administrativa;

8) La Superintendencia Tributaria Aduanera es una unidad altamente especializada en temas tributarios y aduaneros;

9) La Superintendencia Tributaria Aduanera está integrada por cinco (5) miembros, con grado de licenciatura, preferiblemente especializados con posgrado en la materia tributaria, aduanera, financiera o de comercio exterior o, con experiencia mínima acreditable de cinco (5) años en la materia tributaria, aduanera o de comercio exterior. Por lo menos tres (3) de sus miembros deben ser abogados; entre éstos tres (3) el pleno debe elegir su Presidente, de forma anual y rotativa, exclusivamente para efectos de representación legal de la misma. Asimismo, se debe nombrar al menos tres (3) miembros suplentes;

10) El nombramiento de los miembros propietarios y suplentes es potestad del Presidente de la República, previo concurso público que debe llevar a cabo la Secretaría de Estado en el Despacho de Finanzas (SEFIN), los cuales duran en sus cargos por un período de cuatro (4) años.

11) Para ser miembro propietario y suplente de la Superintendencia Tributaria Aduanera, además de los requisitos y la experiencia antes referida, se requiere:

a) Ser hondureño por nacimiento;

b) Estar en el pleno goce de los derechos civiles;

c) No haber sido condenado por sentencia firme por delitos tributarios, aduaneros o comunes;

d) No ser cónyuge o tener vínculo de parentesco dentro del cuarto grado de consanguinidad o segundo de afinidad con las autoridades superiores, funcionarios, ejecutivos y gerenciales de la Administración Tributaria o Administración Aduanera o de la Secretaría de Estado en el Despacho de Finanzas (SEFIN); y, e) Haber ejercido la profesión correspondiente por no menos de quince (15) años.

12) Los miembros propietarios y suplentes de la Superintendencia Tributaria Aduanera deben desempeñar sus funciones a tiempo completo y de forma exclusiva y, no pueden ser asesores o consultores de terceros; pudiendo desempeñar única y exclusivamente labores de docencia e investigación académica;

13) La Secretaría de Estado en el Despacho de Desarrollo Económico (SEDE) y el

Banco Central de Honduras (BCH), deben designar un (1) miembro permanente por institución a la Superintendencia Tributaria Aduanera, quienes tienen voz, pero no voto en las decisiones de ésta, actuando como referentes permanentes en la materia de comercio exterior y monetaria;

14) La Superintendencia Tributaria Aduanera puede contar con la asistencia técnica de profesionales independientes, así como técnica, legal y fiscal permanente de otras instituciones del Estado como serla Secretaría de Estado en el Despacho de Desarrollo Económico (SEDE) y el Banco Central de Honduras (BCH); y,

15) El Presidente de la República, por conducto de la Secretaría de Estado en el Despacho de Finanzas (SEFIN), y previa la socialización con las entidades gremiales representativas de la empresa privada, el sector social de la economía y gremios profesionales del país, emitirá el reglamento y reformas en su caso, que desarrollen todo lo relativo a las funciones, integración, atribuciones y demás competencias de la Superintendencia Tributaria Aduanera.','183','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":183,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"6207d3eb01aecc36e7e65377658f1d414af14695529dac35aed01d6464df131a","ubicacion":["CAPÍTULO III","DE LA SUPERINTENDENCIA TRIBUTARIA ADUANERA"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a183","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','183','6207d3eb01aecc36e7e65377658f1d414af14695529dac35aed01d6464df131a','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:184','mayalex_normativos','08_TRIBUTARIO','DE LOS RECURSOS.

1) La presentación de recursos ante la Superintendencia Tributaria Aduanera no requiere de más formalidades que las señaladas en el presente Código y puede hacerse tanto mediante solicitud física como en formato digital. A tal efecto, la Superintendencia debe crear un portal electrónico que contenga los requisitos, formularios, formatos y demás herramientas necesarias para facilitarlas actuaciones del obligado tributario y dar seguimiento en línea a los procesos que se sometan a su conocimiento; y,

2) Además de lo preceptuado en este Código, los recursos presentados deben contener:

a) La información general de la persona que lo solicita, incluyendo su número del Registro Tributario Nacional (RTN) y su domicilio. En caso de ser una persona jurídica, la información de su representante legal;

b) Información, datos generales y de contacto del apoderado legal o representante procesal;

c) La designación del o los funcionarios que hayan llevado a cabo el acto objeto de recurso;

d) La relación de los hechos previos y de todas las actuaciones realizadas tanto por el obligado tributario como por la Administración Tributaria o la Administración Aduanera;

e) Las consideraciones y razonamientos legales en que se fundamenta el recurso; y, f) La petición correspondiente.','184','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":184,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"66b331cc417a173002f0c26b18879d3e38e9c53e07282508b075db42d47abd4b","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a184","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','184','66b331cc417a173002f0c26b18879d3e38e9c53e07282508b075db42d47abd4b','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:185','mayalex_normativos','08_TRIBUTARIO','DE LOS MEDIOS DE PRUEBA.

1) Al recurso presentado deben acompañarse todos los medios de prueba que acrediten los extremos alegados en el mismo, salvo las excepciones previstas en el presente Código o, si alguno de ellos no estuviese disponible o se encuentra en el expediente radicado en la Administración Tributaria o la Administración Aduanera, la designación de su ubicación;

2) Cuando los medios de prueba no fueren acompañados al recurso, se debe requerir al solicitante que los acredite en un plazo máximo de cinco (5) días hábiles, agotados los cuales, si no se hubiesen acreditado las pruebas, se debe tener por desestimado el recurso de pleno derecho y archivar sin más trámite;

3) Entre los medios de prueba, puede presentarse copia simple en papel o digital de los documentos que sustenten la petición del obligado tributario. Únicamente se requiere certificado de autenticidad de las mismas cuando se justifique que las copias no pueden ser cotejadas con un documento original en poder del Estado o del obligado tributario. Las copias no autenticadas deben cotejarse con los originales antes de ser admitidas;

4) Las pruebas documentales se tienen por evacuadas al momento de su presentación;

5) El obligado tributario puede acompañar como medios de prueba, dictámenes de expertos en la materia tanto nacionales como extranjeros, los cuales deben acreditar sus capacidades en la materia. Dichas opiniones deben ser valoradas al momento de emitirse la resolución respectiva;

6) También constituyen medios de prueba las declaraciones juradas rendidas ante Notario por parte de testigos relacionados con los hechos en que se fundamente el recurso. Dichos testigos pueden ser interrogados en audiencia oral. El interrogatorio está sujeto a las normas que al respecto establece el Código Procesal Civil y debe ser grabado en vídeo para efectos de archivo, pudiendo entregarse copia del mismo al interesado cuando así lo solicite, a su costo. En tal caso, la Superintendencia Tributaria Aduanera debe señalar el lugar y fecha para la celebración de dicha audiencia, pudiendo suspenderse la misma por una sola vez;

7) El plazo para la evacuación de las demás pruebas es de veinte (20) días hábiles que pueden ser ampliados por una sola vez por diez (10) días hábiles; y,

8) Evacuadas las pruebas y cumplidos los trámites anteriormente señalados, la Superintendencia Tributaria Aduanera debe emitir la resolución respectiva en un plazo no mayor de sesenta (60) días hábiles. El agotamiento de este plazo sin que se haya emitido la resolución habilita en forma automática al solicitante para interponer las acciones judiciales correspondientes.','185','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":185,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"d4687183c76922c0c184e61b38bb64cf5739a309887a0f3556ebdda3f3ac6725","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a185","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','185','d4687183c76922c0c184e61b38bb64cf5739a309887a0f3556ebdda3f3ac6725','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:186','mayalex_normativos','08_TRIBUTARIO','RESOLUCIÓN DEL RECURSO.

1) Además de los requisitos formales e internos de las resoluciones preceptuados en este Código, la resolución debe contener:

a) Una síntesis de los antecedentes del caso;

b) Una síntesis de los hechos y alegatos de las partes;

c) El análisis de cada uno de los medios de prueba acreditados y su valoración respectiva;

d) El razonamiento jurídico en que se funde la resolución;

e) Las medidas que deban tomarse para enmendar el acto cuando corresponda; y, f) La decisión final.

2) Las resoluciones de la Superintendencia Tributaria Aduanera sólo pueden ser revocadas o modificadas por un órgano judicial competente y una vez que queden firmes en sede judicial, constituyen precedente obligatorio cuando fuera dictada por un órgano judicial competente proferida entres (3) sentencias en el mismo sentido debiendo ser consideradas por la Administración Tributaria, la Administración Aduanera, la superintendencia misma y por los obligados tributarios para todas sus actuaciones futuras;

3) Las resoluciones firmes deben ser publicadas e indexadas en una base de datos de fácil acceso para poder ser consultadas por cualquier persona, debiendo siempre tomarse las medidas necesarias para mantener la confidencialidad de la información de carácter privado de los obligados tributarios, así como sus datos personales confidenciales.','186','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":186,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"2f99d79a671d539783b317b741af6427f4cc9610d7b06d21ffebb875bd17a140","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a186","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','186','2f99d79a671d539783b317b741af6427f4cc9610d7b06d21ffebb875bd17a140','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:187','mayalex_normativos','08_TRIBUTARIO','DE LO CONTENCIOSO ADMINISTRATIVO. Contra las resoluciones dictadas por la Superintendencia Tributaria Aduanera y la Secretaría de Estado en el Despacho de Finanzas (SEFIN) en única instancia, se puede interponer la demanda correspondiente antes los Juzgados de lo Contencioso Administrativo.','187','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":187,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"28e1881a3fd771274e19bcb423f801b4f0d2e76a3fcd832b0a3a05ed0e127149","ubicacion":["CAPÍTULO IV","ACCIONES ANTE TRIBUNALES JUDICIALES"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a187","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','187','28e1881a3fd771274e19bcb423f801b4f0d2e76a3fcd832b0a3a05ed0e127149','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:188','mayalex_normativos','08_TRIBUTARIO','FORMAS DE ASISTENCIA ADMINISTRATIVA MUTUA EN MATERIA TRIBUTARIA Y ADUANERA.

1) La Administración Tributaria o la Administración Aduanera, en el ámbito de sus competencias y en el marco de Convenios de Derecho Internacional Tributario y Aduanero, aprobados y ratificados conforme a lo dispuesto en la Constitución de la República, puede requerir o solicitar a otras Administraciones Tributarias o Aduaneras:

a) Actuaciones de intercambio de información por solicitud de cualquiera de las partes;

b) Asistencia mutua en el cumplimiento de sus tareas de verificación, comprobación, cumplimiento de las obligaciones tributarias y aduaneras, así como la prevención, control, investigación y sanción de las infracciones tributarias y aduaneras;

c) Información o evidencia para evitar la doble imposición tributaria;

d) Programas de capacitación o entrenamiento en cualquier materia relativa a este Código; y, e) Notificación de documentos.

2) Las actuaciones y procedimientos que se realicen para efecto de la asistencia administrativa mutua se rigen por las estipulaciones del Convenio respectivo y, de manera complementaria, en lo que no se oponga al Convenio, en lo dispuesto en el presente Código; y,

3) La Administración Tributaria y la Administración Aduanera, en sus respectivos ámbitos de competencia, puede suscribir Acuerdos Interinstitucionales de Implementación de los Convenios Internacionales que en materia tributaria o aduanera suscriba el Estado de Honduras, dentro de los términos y alcances permitidos por éstos, de conformidad con la Ley y según las prácticas internacionales en dichas materias.','188','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":188,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"89bfc848ee638b8ba7fc58df70ee8e618adbf155d00a73b7b9ea6c6468f93238","ubicacion":["TÍTULO NOVENO","ASISTENCIA ADMINISTRATIVA MUTUA EN MATERIA TRIBUTARIA Y ADUANERA"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a188","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','188','89bfc848ee638b8ba7fc58df70ee8e618adbf155d00a73b7b9ea6c6468f93238','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:189','mayalex_normativos','08_TRIBUTARIO','ACUERDOS NACIONALES INTERINSTITUCIONALES. Las formas de asistencia relacionadas en el Artículo anterior, también son aplicables para la suscripción de Acuerdos Nacionales Interinstitucionales entre la Administración Tributaria, Administración Aduanera y otros entes estatales.','189','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":189,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"ffae2e7437254bfc5bace8f6b636ba3315c3cda39747b3274f6fde2d43938f04","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a189","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','189','ffae2e7437254bfc5bace8f6b636ba3315c3cda39747b3274f6fde2d43938f04','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:190','mayalex_normativos','08_TRIBUTARIO','CARÁCTER RESERVADO DE LA INFORMACIÓN.

1) La información proporcionada a la Administración Tributaria o la Administración Aduanera, por Administraciones Tributarias o Aduaneras extranjeras y otros entes estatales, tiene carácter de reservado en los términos del presente Código; y,

2) Los datos, informes o antecedentes obtenidos por la Administración Tributaria o la Administración Aduanera en el desempeño de sus funciones pueden ser cedidos o comunicados a Administraciones Tributarias o Aduaneras extranjeras o a otros entes estatales del país, si la cesión tiene por objeto la colaboración con éstas a efectos de lograr el cumplimiento de las obligaciones tributarias o aduaneras en el ámbito de sus competencias y en el marco de Convenios de Derecho Internacional Tributario o Aduaneros o, Acuerdos Nacionales Interinstitucionales.','190','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":190,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"ec17bf49739240ed8c4abf77738d2e0e45e12bceb7333f40345a0965e95f1303","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a190","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','190','ec17bf49739240ed8c4abf77738d2e0e45e12bceb7333f40345a0965e95f1303','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:191','mayalex_normativos','08_TRIBUTARIO','AUSENCIA DE INTERÉS DOMÉSTICO EN EL INTERCAMBIO DE INFORMACIÓN. Cuando una Administración Tributaria o Aduanera extranjera solicite a la Administración Tributaria o a la Administración Aduanera de Honduras, información que ésta no posea, se deben realizar las actuaciones que correspondan para obtenerla, aún cuando la información solicitada no sea necesaria para la determinación de los tributos de su competencia. Lo mismo debe ocurrir cuando, en el marco de la cooperación administrativa doméstica prevista en un Acuerdo Nacional Interinstitucional, quien solicite la información sea otro ente estatal del país.','191','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":191,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"dad7ab2c64aa784ca12ed3474af830cf4c783c0a26297a91a99eb3bcfe3dcd9b","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a191","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','191','dad7ab2c64aa784ca12ed3474af830cf4c783c0a26297a91a99eb3bcfe3dcd9b','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:192','mayalex_normativos','08_TRIBUTARIO','VALIDEZ DE INFORMACIONES PROPORCIONADAS POR ADMINISTRACIONES TRIBUTARIAS O ADUANERAS EXTRANJERAS. Las pruebas o informaciones suministradas por otros Estados o entidades internacionales o supranacionales en el marco de la asistencia administrativa mutua en materia tributaria o aduanera, pueden incorporarse con el valor probatorio que proceda conforme a las normas sobre prueba del Código Procesal Civil.','192','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":192,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"43388b59618562e41e0c21cab1374f3c064f4e78c97341b9adc1e8e343ee3693","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a192","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','192','43388b59618562e41e0c21cab1374f3c064f4e78c97341b9adc1e8e343ee3693','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:193','mayalex_normativos','08_TRIBUTARIO','ASISTENCIA INTERNACIONAL EN MATERIA DE NOTIFICACIONES.

1) La Administración Tributaria o la Administración Aduanera, en virtud de lo dispuesto por un Convenio de Derecho Internacional Tributario o Aduanero, puede solicitar de la autoridad competente de otro Estado la práctica de las notificaciones de cualquier acto de aplicación de los tributos o de imposición de sanciones relativas a los mismos;

2) Las notificaciones realizadas en un Estado al amparo de lo previsto en el numeral anterior deben acreditarse mediante la comunicación de la notificación efectuada de acuerdo con la normativa propia del Estado de la autoridad que la realiza y producen los mismos efectos que si se hubieran realizado conforme a lo dispuesto en el presente Código;

3) Cuando la Administración Tributaria o la Administración Aduanera reciba una solicitud de notificación de documentos por parte de la autoridad competente de otro Estado en el marco de la asistencia administrativa mutua en materia tributaria o aduanera, es aplicable el régimen de notificaciones regulado en el presente Código; y,

4) Los documentos deben ser notificados en el idioma español.','193','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":193,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"c6c0663d6994df1f53b65be66663de523599e9e669b97e17c5715c5e59189213","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a193","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','193','c6c0663d6994df1f53b65be66663de523599e9e669b97e17c5715c5e59189213','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:194','mayalex_normativos','08_TRIBUTARIO','ASISTENCIA EN MATERIA DE RECAUDACIÓN.

1) La Administración Tributaria o la Administración Aduanera, en virtud de lo dispuesto por los Convenios de Derecho Internacional Tributario o Aduanero ratificados por el Estado de Honduras, debe prestar, a título de reciprocidad, asistencia en la recaudación de las deudas tributarias o aduaneras de interés para las Administraciones Tributarias o Aduaneras del extranjero, siguiendo los mecanismos de cobro persuasivo o ejecutivo previstos en este Código y en la medida que los Convenios respectivos no dispongan lo contrario;

2) El Convenio respectivo debe determinar el instrumento del Estado solicitante de la asistencia que habilite para el ejercicio de las actuaciones recaudatorias por parte de la Administración Tributaria o la Administración Aduanera. A partir de ahí, dichas administraciones deben asistir en la recaudación de acuerdo con la legislación aplicable a la ejecución y recaudación de sus propios tributos;

3) La Administración Tributaria o la Administración Aduanera igualmente debe prestar asistencia en la recaudación de las deudas tributarias de interés para las municipalidades del país, en virtud de lo dispuesto por Acuerdos Nacionales Interinstitucionales que prevén la cooperación administrativa doméstica. La Administración Tributaria y la Administración Aduanera, quedan habilitadas también para solicitar asistencia en materia de recaudación a las municipalidades del país.','194','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":194,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"b0bceb7d8d2c8b6b0d6c42b56033c84dae9762c923a945af34d9ae174b200b7d","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a194","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','194','b0bceb7d8d2c8b6b0d6c42b56033c84dae9762c923a945af34d9ae174b200b7d','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:195','mayalex_normativos','08_TRIBUTARIO','CREACIÓN DE LA ADMINISTRACIÓN TRIBUTARIA Y LA ADMINISTRACIÓN ADUANERA. DOMICILIO, FUNCIÓN Y MISIÓN.

1) Créase la Administración Tributaria y la Administración Aduanera como entidades desconcentradas de la Presidencia de la República, con autonomía funcional, técnica, administrativa y de seguridad nacional, con personalidad jurídica propia, responsable del control, verificación, fiscalización y recaudación de los tributos, con autoridad y competencia a nivel nacional y con domicilio en la Capital de la República;

2) La función primordial de la Administración Tributaria y la Administración Aduanera es administrar el sistema tributario y aduanero de la República de Honduras; y sus denominaciones son acordadas por el Poder Ejecutivo; y,

3) Su misión de la Administración Tributaria y de la Administración Aduanera debe estar orientada a optimizar la recaudación, mediante la administración, aplicación, fiscalización, supervisión, revisión, control eficiente y eficaz, ejecución de cobro, de los tributos internos y aduaneros, la orientación y facilitación del cumplimiento voluntario, promover el cumplimiento veraz y oportuno de las obligaciones tributarias, ejercerla cobranza y sanción de los que incumplen de acuerdo a lo que establece este Código, las leyes y normas tributarias y aduaneras vigentes, con excepción de los tributos que por Ley administran, recaudan y fiscalizan las Corporaciones Municipales y otras entidades del Estado, salvo en aquellos casos en que la Administración Tributaria o la Administración Aduanera celebre convenios de cooperación de conformidad con lo establecido en el presente Código.','195','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":195,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"54f4b1a6eac5c70667049038363495e5095cd0414acdf2103e596ab7801bbdc7","ubicacion":["TÍTULO FINAL","DISPOSICIONES GENERALES, TRANSITORIAS Y FINALES","CAPÍTULO I","DISPOSICIONES GENERALES","LA ADMINISTRACION TRIBUTARIA Y LA ADMINISTRACIÓN ADUANERA"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a195","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','195','54f4b1a6eac5c70667049038363495e5095cd0414acdf2103e596ab7801bbdc7','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:196','mayalex_normativos','08_TRIBUTARIO','CREACIÓN DEL CONSEJO CONSULTIVO DE LA ADMINISTRACIÓN TRIBUTARIA Y DE LA ADMINISTRACIÓN ADUANERA.

1) Créase un Consejo Consultivo de la Administración Tributaria y de la Administración Aduanera. Dicho Consejo tiene las funciones de asesoramiento a ambas administraciones;

2) El Consejo Consultivo está integrado por:

a) El Secretario de Estado en el Despacho de Finanzas (SEFIN), quien lo preside y tiene voto de calidad;

b) El Secretario de Estado en el Despacho de Desarrollo Económico (SEDE);

c) El Presidente del Banco Central de Honduras (BCH); y, d) El Presidente de la Comisión Nacional de Bancos y Seguros (CNBS).

3) La Administración Tributaria y la Administración Aduanera deben participar en el Consejo Consultivo con voz pero sin voto y anualmente actuarán como Secretario del Consejo rotativamente por designación del mismo. El respectivo suplente debe ser quien la Administración Tributaria o la Administración Aduanera designe dentro de su estructura orgánica;

4) Los integrantes del Consejo Consultivo desempeñan sus funciones bajo su exclusiva responsabilidad de acuerdo con este Código y la Ley y actúan con absoluta independencia de criterio, así como de cualquier interés distinto al de la Administración Tributaria y la Administración Aduanera;

5) Las sesiones ordinarias mensuales y las extraordinarias del Consejo deben ser convocadas por su Presidente. El Consejo sesiona válidamente con la asistencia de por lo menos tres (3) de sus integrantes, dentro de los cuales debe encontrarse el Presidente o quien éste designe y con la presencia obligatoria de la Administración Tributaria y de la Administración Aduanera o quien la represente. Sus recomendaciones deben ser adoptadas por mayoría de los presentes. No puede realizarse más de una sesión en el mismo día; y,

6) El Consejo Consultivo puede, cuando así lo considere necesario, invitar a sus sesiones a asesores ocasionales para que participen con voz pero sin voto, en la discusión de temas específicos, sin perjuicio de presentar sus opiniones por escrito.','196','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":196,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"38191dc604b4f7b095ad178faa6f0f7b4dc861794c84eb91a8ea3d6dd2123224","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a196","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','196','38191dc604b4f7b095ad178faa6f0f7b4dc861794c84eb91a8ea3d6dd2123224','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:197','mayalex_normativos','08_TRIBUTARIO','DEFINICIÓN DE LA ADMINISTRACIÓN TRIBUTARIA Y DE LA ADMINISTRACIÓN ADUANERA.

1) La Administración Tributaría y la Administración Aduanera están a cargo de un (a) Director (a) Ejecutivo (a), nombrado por el Presidente de la República, por conducto de la Secretaría de Estado en el Despacho de Finanzas (SEFIN), con rango Ministerial. El (la) Director (a), de cada una de ellas, es la máxima autoridad y el representante legal de la institución, responsable de definir y ejecutar las políticas, estrategias, planes y programas administrativos y operativos, metas y resultados, conforme a la política económica, fiscal y tributaria del Estado. Ambas administraciones deben contar con su respectivo Subdirector(a) Ejecutivo(a) quien le sustituye en su ausencia;

2) Las relaciones entre la Administración Tributaria y la Administración Aduanera y su respectivo personal se rigen por el régimen laboral que al efecto se apruebe por la máxima autoridad de cada institución. Dicho régimen debe contener como normas mínimas los subsistemas para una adecuada administración del talento humano; y,

3) La remuneración del personal de ambas administraciones, debe responder a la responsabilidad de los cargos y la estructura posicional dentro de cada institución, sin que en ellos incidan restricciones de algún tipo. El personal debe ser técnico y altamente calificado, sujeto a pruebas de certificación de confianza.','197','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":197,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"30920abddc29a08a2abb1618a1acb5c8b339b588344cc571225e0c3d8e566800","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a197","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','197','30920abddc29a08a2abb1618a1acb5c8b339b588344cc571225e0c3d8e566800','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:198','mayalex_normativos','08_TRIBUTARIO','ATRIBUCIONES DE LA ADMINISTRACIÓN TRIBUTARIA Y LA ADMINISTRACIÓN ADUANERA.

1) Cumplir y hacer cumplir las disposiciones de la Constitución de la República, Convenios Internacionales en materia Tributaria o Aduanera, el Código Tributario, las Leyes y demás normas de carácter tributario o aduanero, según corresponda;

2) Fiscalizar el cumplimiento de las obligaciones tributarias y aduaneras, a efecto de combatir las infracciones y los delitos tributarios;

3) Crear planes y programas de gestión administrativa acorde con los lineamientos de la política económica y metas de recaudación anuales acordadas;

4) Promover la cultura tributaria y aduanera en la población por medio de programas de asistencia, orientación y educación en su materia;

5) Establecer y mantener relaciones con instituciones, organismos nacionales e internacionales y agencias de cooperación vinculadas a la Administración Tributaria y la Administración Aduanera, de conformidad con lo establecido en el presente Código;

6) Administrar el sistema tributario y el sistema aduanero, ejerciendo todas las atribuciones y facultades establecidas en el Código Tributario, Código Aduanero Uniforme Centroamericano (CAUCA) y su reglamento, leyes y reglamentos relacionados con la materia tributaria y aduanera, según corresponda;

7) Gestionar la recaudación de los tributos y gravámenes establecidos en las leyes tributarias y aduaneras;

8) Recuperar las deudas tributarias y aduaneras;

9) Requerir de terceros públicos o privados la información necesaria para el cumplimiento de funciones investigativas, de control y fiscalizadoras de conformidad con el presente Código Tributario, Código Aduanero Uniforme Centroamericano (CAUCA) y la Ley;

10) Designar agentes de percepción o de retención de cualquier tributo de conformidad con el presente Código;

11) Imponer las sanciones conforme a lo dispuesto en el Código Tributario y en las leyes vigentes;

12) Aprobar Acuerdos para la aplicación eficiente de las disposiciones en materia tributaria y aduanera, de conformidad con el presente Código, Código Aduanero Uniforme Centroamericano (CAUCA) y la Ley;

13) Resolverlos procedimientos iniciados de oficio o a instancia de parte en el marco de sus competencias;

14) Establecer y operar procedimientos y sistemas ágiles y simplificados, para facilitar el cumplimiento voluntario de las obligaciones tributarias y aduaneras; así como implementar y operar la tramitación expedita de las operaciones tributarias o aduaneras, formales o materiales; y,

15) Cualquier otra facultad o atribución que establezca la Ley, en sus respectivas competencias.','198','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":198,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"79e5cca8a3fd7a019bfa93e022c6648d8917297ad04052d187778782bc691375","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a198","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','198','79e5cca8a3fd7a019bfa93e022c6648d8917297ad04052d187778782bc691375','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:199','mayalex_normativos','08_TRIBUTARIO','ATRIBUCIONES DE LAS DIRECCIONES EJECUTIVAS DE LA ADMINISTRACIÓN TRIBUTARIA Y DE LA ADMINISTRACIÓN ADUANERA. Las Direcciones Ejecutivas de la Administración Tributaria y la Administración Aduanera, en su respectivo ámbito de competencias, tienen las atribuciones siguientes:

1) Ejercer la representación legal y administración general, dirección y manejo de la institución;

2) Aprobarlas políticas institucionales;

3) Aprobar el Plan Estratégico Institucional;

4) Aprobar el Plan Operativo Anual y Plurianual, estados financieros y memoria institucional para su presentación a las instancias correspondientes y supervisar la ejecución de los mismos;

5) Delegar las funciones en los funcionarios competentes;

6) Aprobar los acuerdos que contengan las normas internas de la institución, incluyendo aquellos instrumentos, normas y manuales que regulan la estructura organizacional y funcional, su régimen laboral, de remuneraciones y de contrataciones; así como los relacionados con la implementación de los reglamentos de la materia tributaria y aduanera, según corresponda;

7) Seleccionar, nombrar, contratar, evaluar, promover y remover al personal de acuerdo a las normas legales aplicables;

8) Elaborar el presupuesto anual dentro del techo presupuestario asignado y remitirlo a la Secretaría de Estado en el Despacho de Finanzas (SEFIN) para su incorporación en el Presupuesto General de Ingresos y Egresos de la República;

9) Resolver los Recursos de Reposición, según el Código Tributario o el Código Aduanero Uniforme Centroamericano (CAUCA), según corresponda;

10) Celebrarlos actos y contratos que sean de su competencia;

11) Verificar el cumplimiento de las obligaciones tributarias o aduaneras, a efecto de prevenir la defraudación y el contrabando;

12) Preparar planes y programas de gestión administrativa acorde con los lineamientos de la política económica y metas de recaudación anuales acordadas; y,

13) Las demás funciones que le confieran el presente Código y las leyes aplicables.','199','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":199,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"9af342baea4c0f3984c6982342ff64b164bafc59077405116216209ca3a7220f","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a199","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','199','9af342baea4c0f3984c6982342ff64b164bafc59077405116216209ca3a7220f','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:200','mayalex_normativos','08_TRIBUTARIO','REQUISITOS PARA DESEMPEÑAR LAS DIRECCIONES EJECUTIVAS DE LA ADMINISTRACIÓN TRIBUTARIA Y DE LA ADMINISTRACIÓN ADUANERA.

1) Ser hondureño por nacimiento, mayor de treinta (30) años;

2) Estar en el goce y en el ejercicio de sus derechos civiles y políticos;

3) Ser profesional universitario de reconocida capacidad e idoneidad;

4) No tener deudas o cuentas pendientes con el Estado;

5) No tener parentesco dentro del cuarto grado de consanguinidad o segundo de afinidad ni ser cónyuge del Presidente de la República, Magistrados de la Corte Suprema de Justicia, Magistrados del Tribunal Superior de Cuentas, Fiscal General, Fiscal General Adjunto, Director de Fiscales y Fiscales Especiales del Ministerio Público, Procurador General y Subprocurador General de la República; Comisionado Nacional de los Derechos Humanos; Secretarios o Subsecretarios de Estado; Presidente y Directores del Banco Central de Honduras; y Comisionados de la Comisión Nacional de Bancos y Seguros; y,

6) No estar desempeñando otro cargo público remunerado, con excepción de la docencia universitaria, la investigación y de salud. El desempeño del cargo de la Dirección Ejecutiva es de carácter exclusivo y tiene anexa jurisdicción.','200','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":200,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"9bb9e25a6e2a70213f424e6731eea732275a13abe920fbc4398417379841cf0e","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a200","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','200','9bb9e25a6e2a70213f424e6731eea732275a13abe920fbc4398417379841cf0e','OLA9_CTRIB_2024_01',now())
