INSERT INTO public.biblioteca_vectores (id,coleccion,materia,contenido,num_articulo,fuente,metadata,embedding,jurisdiccion,fuente_tipo,es_norma_vigente,revision_pendiente,instrumento_id,num_articulo_norm,hash_contenido,ingest_batch,ingested_at) VALUES
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:201','mayalex_normativos','08_TRIBUTARIO','PATRIMONIO DE LA ADMINISTRACIÓN TRIBUTARIA Y LA ADMINISTRACIÓN ADUANERA.

1) Las asignaciones presupuestarias aprobadas por el Congreso Nacional, de hasta el dos punto cinco por ciento (2.5%) del total de la recaudación de tributos internos para la administración tributaria y de hasta el dos punto cinco por ciento (2.5%) del total de la recaudación de tributos aduaneros para la administración aduanera, ambos del período fiscal anual inmediatamente anterior;

2) Ingresos propios, como ser los provenientes de la prestación de servicios de cualquier índole. Así como los recursos provenientes de las subastas o remates, de los servicios por transporte de datos y otros, en el caso de la Administración Aduanera;

3) Herencias, legados y donaciones de otras fuentes públicas o privadas, nacionales o extranjeras y los provenientes de programas de cooperación internacional; y,

4) Transferencias y bienes que se les transfieran acordadas por la Secretaría de Estado en el Despacho de Finanzas (SEFIN).','201','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":201,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"85186eed42a5442aa3c3a70f51ed093c0828d3c6f1ba381842acd02852cc839f","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a201","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','201','85186eed42a5442aa3c3a70f51ed093c0828d3c6f1ba381842acd02852cc839f','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:202','mayalex_normativos','08_TRIBUTARIO','ESCUELAS TRIBUTARIA Y ADUANERA.

1) Créase la Escuela Tributaria y la Escuela Aduanera, como dependencias de la Administración Tributaria y la Administración Aduanera respectivamente, con especialización funcional y técnica, las cuales están encargadas de diseñar, implementar, socializar y ejecutar los planes y programas de capacitación y entrenamiento tributario y aduanero, a nivel nacional, en todos los niveles de educación formal, informal y no formal, con cobertura a todas las personas y sectores sociales y económicos de la República;

2) La Secretaría de Estado en el Despacho de Educación y el Consejo de Educación Superior, en coordinación con la Secretaría de Estado en el Despacho de Finanzas (SEFIN), la Administración Tributaria y la Administración Aduanera, debe incluir en la currícula nacional el contenido de la materia tributaria y aduanera en los planes y programas de estudio; y,

3) Se faculta a la Administración Tributaria y a la Administración Aduanera, para que dispongan todo lo relacionado con la estructura, presupuesto, metodologías y demás funciones de la Escuela Tributaria y de la Escuela Aduanera, respectivamente, así como cualquier otro requerimiento que pueda en el futuro contribuir al desarrollo de estas escuelas.','202','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":202,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"34eb68cf83e9bc79ac3835081b2e52d7c612e6bf8df8d89558eee1a7194dab2c","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a202","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','202','34eb68cf83e9bc79ac3835081b2e52d7c612e6bf8df8d89558eee1a7194dab2c','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:203','mayalex_normativos','08_TRIBUTARIO','EXPEDIENTES EN TRAMITACIÓN. Los expedientes relacionados con tributos que se estén tramitando en la vía administrativa o judicial, a la fecha de entrar en vigencia este Código, se concluirán conforme a las leyes con base en las cuales se iniciaron.','203','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":203,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"aca93bd60d24179fb49fd85746a40b70d1ab4a82e3d29f16741b709497655f7a","ubicacion":["CAPÍTULO II","DISPOSICIONES TRANSITORIAS"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a203","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','203','aca93bd60d24179fb49fd85746a40b70d1ab4a82e3d29f16741b709497655f7a','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:204','mayalex_normativos','08_TRIBUTARIO','TRANSICIÓN A LA SUPERINTENDENCIA TRIBUTARIA ADUANERA. Hasta tanto entre en funcionamiento la Superintendencia Tributaria Aduanera a que hace referencia este Código, la Secretaría de Estado en el Despacho de Finanzas (SEFIN) es la encargada de resolver los Recursos de Apelación y de Revisión.','204','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":204,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"667e903a2eed36e3d14d72b5f8213d052695c0d235adb73c0a25049256977abd","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a204","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','204','667e903a2eed36e3d14d72b5f8213d052695c0d235adb73c0a25049256977abd','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:205','mayalex_normativos','08_TRIBUTARIO','READECUACIONES Y REESTRUCTURACIÓN.

1) Se autoriza a la Administración Tributaria, a la Administración Aduanera y a la Secretaría de Estado en el Despacho de Finanzas (SEFIN) para que realicen los ajustes a sus procedimientos, sistemas, registros y demás aplicativos, para que se adecuen a las disposiciones del presente Código. El Presidente de la República, en Consejo de Secretarios de Estado, puede disponer de las partidas y recursos necesarios para cumplir con este objetivo; y,

2) El Poder Ejecutivo por conducto de la Secretaría de Estado en el Despacho de Finanzas (SEFIN) con apoyo de la Administración Tributaria y de la Administración Aduanera, por todos los medios existentes y disponibles, debe informar, comunicar, instruir y capacitar sobre el contenido y alcances del presente Código, debiendo auxiliarse de las organizaciones gremiales, profesionales y empresariales, del Sector Social de la Economía, Cámaras de Comercio y colegios profesionales, para esos efectos.','205','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":205,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"42aa132a147150218b24fa0599b056ab62fff58cdd5e0b66cff8b07b1c1426df","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a205","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','205','42aa132a147150218b24fa0599b056ab62fff58cdd5e0b66cff8b07b1c1426df','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:206','mayalex_normativos','08_TRIBUTARIO','TRIBUNALES EN MATERIA TRIBUTARIA Y ADUANERA.

1) El Poder Judicial debe adoptar las medidas necesarias para el fortalecimiento técnico, especializado y presupuestario de los Tribunales de la Jurisdicción de lo Contencioso Administrativo, en materia tributaria y aduanera;

2) Por un período improrrogable de cinco (5) años, contados a partir de la entrada de vigencia del presente Código, para la admisión de una demanda ante los tribunales la Jurisdicción de lo Contencioso Administrativo en materia tributaria y aduanera, se requerirá que el demandante acredite rendir ante el Juez garantía suficiente a favor del Estado conforme a la tabla siguiente:

a) Pequeños contribuyentes: cinco por ciento (5%) de la cuantía de la demanda;

b) Medianos contribuyentes: diez por ciento (10%) de la cuantía de la demanda; y, c) Grandes contribuyentes: veinte por ciento (20%) de la cuantía de la demanda.

3) Transcurrido el plazo de cinco (5) años establecido en este Artículo, los jueces de los Tribunales de la Jurisdicción de lo Contencioso Administrativo no pueden exigir garantía alguna para admitir las demandas en materia tributaria o aduanera.','206','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":206,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"a8377a69e2397bcd8679587ce3239f7b5d784cacebf22029c123f6584f46bf79","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a206","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','206','a8377a69e2397bcd8679587ce3239f7b5d784cacebf22029c123f6584f46bf79','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:207','mayalex_normativos','08_TRIBUTARIO','TEXTOS CONSOLIDADOS DE LEYES TRIBUTARIAS O ADUANERAS. El Poder Ejecutivo, por conducto de la Secretaría de Estado en el Despacho de Finanzas (SEFIN), con la asistencia de la Administración Tributaria y de la Administración Aduanera, en un plazo de un (1) año contado a partir de la entrada en vigencia del presente Código, debe presentar al Congreso Nacional los nuevos proyectos de Ley del Impuesto Sobre la Renta, Ley del Impuesto Sobre Ventas y un proyecto de ley que consolide las leyes de los demás tributos vigentes, así como las medidas antievasión correspondientes, mismos que deben ser congruentes con los objetivos y principios contenidos en este Código.','207','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":207,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"2c867694ece6356200464ef36790d35d13ae986170b69877b8d978884ef75157","ubicacion":["CAPÍTULO III","DISPOSICIONES FINALES"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a207","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','207','2c867694ece6356200464ef36790d35d13ae986170b69877b8d978884ef75157','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:208','mayalex_normativos','08_TRIBUTARIO','MONOTRIBUTO O TRIBUTO ÚNICO. El Poder Ejecutivo, por conducto de la Secretaría de Estado en el Despacho de Finanzas (SEFIN), con la asistencia de la Administración Tributaria y la Administración Aduanara y en consulta con los sectores involucrados, en un plazo de un (1) año contados a partir de la entrada en vigencia del presente Código, debe presentar al Congreso Nacional un proyecto que desarrolle el Monotributo o Tributo Único, creado en el presente Código.','208','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":208,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"b6cd14ab2aec0e77a7096ddd7e4d7b92538bbc399255e64cf3208c8de63bba2a","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a208","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','208','b6cd14ab2aec0e77a7096ddd7e4d7b92538bbc399255e64cf3208c8de63bba2a','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:209','mayalex_normativos','08_TRIBUTARIO','CONVENIOS PARA EVITAR LA DOBLE TRIBUTACIÓN. Se faculta al Poder Ejecutivo, por conducto de la Secretaría de Estado en el Despacho de Finanzas (SEFIN), con la asistencia de la Administración Tributaria y la Administración Aduanera, para suscribir Convenios con el Estado u otros Estados para Evitar la Doble Tributación en Materia de Impuesto Sobre la Renta y el Patrimonio, siguiendo el procedimiento regulado en la Constitución de la República.','209','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":209,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"1dc299568e8aa5fb9da6f0e44c47552c9cd150edc7fd631554fec4be185fba74","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a209","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','209','1dc299568e8aa5fb9da6f0e44c47552c9cd150edc7fd631554fec4be185fba74','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:210','mayalex_normativos','08_TRIBUTARIO','REGLAMENTO BUZÓN ELECTRÓNICO. La Secretaría de Estado en el Despacho de Finanzas (SEFIN) con la asistencia de la Administración Tributaria y la Administración Aduanera, y con fundamento en el Artículo 22 numeral 11) de la Ley General de la Administración Pública, propondrán para aprobación el proyecto de Reglamento que regulará todo lo concerniente al buzón electrónico, para la aprobación del Presidente de la República en Consejo de Secretarios de Estado.','210','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":210,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"337f13e43cecda06709e7a43809730ed56e33a99ea3fdb36709fd0db7d18b4b1","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a210","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','210','337f13e43cecda06709e7a43809730ed56e33a99ea3fdb36709fd0db7d18b4b1','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:211','mayalex_normativos','08_TRIBUTARIO','REFORMAS E INTERPRETACIONES. Reformar e interpretar, correspondientemente, las disposiciones legales siguientes:

1) Reformar los artículos: 39 reformado por el Decreto No.266-2013; 50 adicionándole un párrafo segundo; y, 66, todos de la LEY DE LA JURISDICCIÓN DE LO CONTENCIOSO ADMINISTRATIVO, contenida en el Decreto No.189-87, de fecha 20 de Noviembre de 1987, los que en adelante se leerán así:

“ARTÍCULO 39.- La cuantía de la acción se fijará en la demanda sobre la base del daño efectivamente causado. La acción judicial únicamente puede ser admitida si el demandante rinde una caución equivalente al Veinte por ciento (20%) del valor reclamado, y en materia tributaria se regirá conforme a lo dispuesto por el Código Tributario.

Esta caución no es requerida... Cuando no se fijare cuantía... Si el demandado...”

“ARTÍCULO 50.- Presentada la demanda... Adicionalmente, cuando la demanda verse sobre la denegación presunta de un recurso por la Superintendencia Tributaria Aduanera o la Secretaría de Estado en el Despacho de Finanzas, el Juzgado comunicará en el mismo plazo a dichas dependencias, según corresponda, la interposición de la demanda a los efectos oportunos.”

“ARTÍCULO 66.- Las defensas previas no suspenden el plazo para contestar la demanda. Sin embargo, la pieza principal de la demanda se debe mantener en suspenso hasta que el Órgano Jurisdiccional resuelva las defensas previas interpuestas.”

2) Reformar los artículos: 4 numeral 4), reformado por el Decreto 278-2013; y, 29 de la LEY DE EFICIENCIA EN LOS INGRESOS Y EL GASTO PÚBLICO, contenida en el Decreto No.113-2011 de fecha 24 de Junio de 2011, publicado en el Diario Oficial “La Gaceta” del 8 de Julio de 2011, los cuales en adelante se leerán así.

“ARTÍCULO 4.- Complementación...

1) Los emisores...;

2) Los OTCD...;

3) Los comercios...;

4) Los Concesionarios de Servicios de Tarjetas de Crédito y Debido (OTCD) deben aplicar un quince por ciento (15%) de manera automática sobre el monto total cuando no exista discriminación del impuesto causado en las transacciones de bienes y servicios gravados de sus afiliados;

5) Los establecimientos...;

6) Los Emisores...;

7) Los Emisores.”

“ARTÍCULO 29.- Control. La Secretaría de Estado en el Despacho de Finanzas (SEFIN) podrá firmar convenios con instituciones del sistema financiero nacional para automatizar y controlarlos beneficios tributarios que se otorgan a personas naturales o jurídicas.

La Secretaría de Estado en el Despacho de Finanzas (SEFIN) es el ente facultado para establecer las formas, medios y controles que deben aplicarse en el reconocimiento de beneficios tributarios; no obstante puede requerir que la Administración Tributaria colabore y apoye en el cumplimiento de esta facultad, ya sea mediante la verificación y fiscalización de lo requerido.”

3) Reformar el Artículo 57 del Decreto No. 17-2010 contentivo de la LEY FORTALECIMIENTO DE LOS INGRESOS, EQUIDAD SOCIAL Y RACIONALIZACIÓN DEL GASTO PÚBLICO, del 28 de Marzo de 2010, publicado en el Diario Oficial “La Gaceta” del 22 de Abril de 2010, el cual en adelante se leerá así:

“ARTÍCULO 57. Se instituye...

La Secretaría de Estado en el Despacho de Finanzas (SEFIN) es la facultada para emitirlos reglamentos necesarios para regular la emisión los tipos de documentos de carácter fiscal y sus requisitos, la regulación de la factura electrónica, las personas naturales o jurídicas que deben inscribirse, las obligaciones y prohibiciones de éstas, infracciones y sanciones administrativas.”

4) Interpretar de manera auténtica y legal de las disposiciones legales siguientes:

a) Interpretar el Artículo 23 del Decreto 113-2011 de fecha 24 de Junio de 2011 contentivo de la LEY DE EFICIENCIA EN LOS INGRESOS Y EL GASTO PÚBLICO, en el sentido que las disposiciones de dicho Artículo no son aplicables para los reclamos administrativos y/o jurisdiccionales contra el Estado de Honduras por concepto de intereses adeudados, daño emergente y lucro cesante, cuando dichos reclamos sean de naturaleza tributaria o impositiva; y, b) Interpretar el Artículo 28, párrafo segundo, del Decreto 113-2011 de fecha 24 de Junio de 2011 contentivo de la LEY DE EFICIENCIA EN LOS INGRESOS Y EL GASTO PÚBLICO, en el sentido que la solvencia que el beneficiario debe acreditar con el Estado, es por las obligaciones tributarias distintas a la dispensa del pago de tributos solicitados.','211','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":211,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"16b315997225a8644ddbfbfd51806122be42ced3ae8d8c52490eee73b6965946","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a211","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','211','16b315997225a8644ddbfbfd51806122be42ced3ae8d8c52490eee73b6965946','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:212','mayalex_normativos','08_TRIBUTARIO','TRANSITORIOS.

1) Se autoriza a la Secretaría de Estado en el Despacho de Finanzas (SEFIN) para que emita las resoluciones de años anteriores a las fechas de publicación del presente Decreto cuando los beneficiarios de las resoluciones hayan cumplido con los requisitos establecidos en el marco legal aplicable, incluyendo lo dispuesto en el párrafo anterior, así mismo se faculta a la Secretaría de Estado en el Despacho de Finanzas (SEFIN) emitir los instructivos necesarios para la aplicación del Artículo 28 del Decreto No. 113- 2011 de fecha 24 de Junio de 2011 publicado en el Diario Oficial “La Gaceta” el 8 de Julio del 2011 y las disposiciones contenidas en los párrafos anteriores.

2) Se ordena a la Secretaría de Estado en el Despacho de Finanzas (SEFIN) para que en el plazo de tres (3) meses contados a partir de la fecha de entrada en vigencia de este Decreto, emita las disposiciones reglamentarias pertinentes al Artículo 57 del Decreto No.17-2010, reformado por este Decreto, mismo que debe incluir la boleta de compra.','212','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":212,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"0f6c9ce8492afa8a83de1f79a414f151ebbf9c631c9d4ab147371cdbd52f6133","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a212","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','212','0f6c9ce8492afa8a83de1f79a414f151ebbf9c631c9d4ab147371cdbd52f6133','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:213','mayalex_normativos','08_TRIBUTARIO','AMNISTIA TRIBUTARIA Y ADUANERA.- Se concede el beneficio de amnistía y regularización tributaria y aduanera, de acuerdo a las condiciones contenidas en los párrafos siguientes:

1. Durante el periodo comprendido desde el 1 de Enero de 2017 hasta el 30 de septiembre de 2017, los obligados tributarios podrán:

a) Presentar las declaraciones tributarias y aduaneras incluyendo manifiestos, tránsitos y demás documentos aduaneros, que se hayan omitido los obligados tributarios, referente a obligaciones y pagos hasta el 31 de Diciembre de 2016, sobre obligaciones tributarias o aduaneras referentes a periodos fiscales anuales o mensuales no prescritos correspondiente a los años 2012, 2013, 2014, 2015 y 2016;

b) Hacer las rectificaciones a las declaraciones ya sean tributarias o aduaneras, incluyendo manifiestos, tránsitos y demás documentos aduaneros que los obligados tributarios hubieren presentado con error y éstos hayan estado obligados o no a presentarlas;

c) Pagar cuando corresponda los tributos relacionados con las declaraciones a que se refieren los numerales a) y b) anteriores, sin multas, recargos o intereses, aplicables conforme el Código Tributario anterior;

d) En el caso de las Tasaciones de Oficio o del Tributo Adicional determinado de Oficio a las declaraciones presentadas por los obligados tributarios al 31 de Diciembre de 2016 y que no se encuentren firmes, pueden pagar los tributos que correspondan al total o la parte que hayan sido aceptadas por los obligados tributarios, sin multas, intereses ni recargos, aplicables conforme al Código Tributario anterior. Las Administraciones Tributaria y Aduanera harán los ajustes correspondientes en sus sistemas para registrar los pagos antes referidos;

e) Los obligados tributarios deben cancelar la deuda tributaria y aduanera que se encuentren firmes y pendientes de pago al 31 de Diciembre de 2016, sin intereses, multas ni recargos, estén o no amparadas en planes de pago;

f) Este beneficio de amnistía también se concederá a los obligados tributarios que hayan presentado sus declaraciones, determinativas e informativas, anuales, mensuales o indistintamente del período, hasta el 31 de Diciembre de 2016, en forma extemporánea y cuya deuda tributaria o aduanera estén constituidas por multas, recargos o intereses como sanción accesoria y que no deban el tributo causado en la declaración que la originó. Este beneficio comprende a las Declaraciones, Manifiestos, Tránsitos y demás documentos aduaneros de cualquier tipo, inclusive aquellas que aplican en regímenes suspensivos de tributos, pero que generen multas;

g) El beneficio de amnistía, es aplicable a lo concerniente al Impuesto sobre Ventas; excepto, al Impuesto Sobre Ventas originado por la venta de bienes y servicios, que ha sido recaudado por los responsables y no enterado en tiempo y forma ante el fisco, por lo tanto aplican a este beneficio de amnistía, todo lo concerniente al Impuesto Sobre Ventas, distinto a lo antes descrito en este párrafo; y, h) El beneficio de amnistía contenido en cualquiera de los literales del presente numeral, se gozará de manera automática sin necesidad de presentación de solicitudes o peticiones ante la Administración Tributaria o Administración Aduanera; por lo cual éstas deberán realizarlos ajustes en sus sistemas para garantizar el fiel cumplimiento de lo dispuesto en el presente Decreto.

2. Los obligados tributarios que no se encuentren en mora y hayan presentado sus declaraciones a la Administración Tributaria y la Administración Aduanera; indistintamente que hayan sido o no objeto de fiscalización tributaria o aduanera, así como del estado del proceso de fiscalización notificados o no notificados, que mantengan recursos administrativos o judiciales respecto de obligaciones no aceptadas voluntariamente y que no se encuentran firmes, líquidas y exigibles; durante cualquiera de los períodos fiscales no prescritos correspondientes a los años 2012, 2013, 2014, 2015 y 2016, podrán acogerse al beneficio de amnistía consistente en la regularización tributaria y aduanera de finiquito o sello definitivo por los períodos fiscales antes descritos, debiendo realizar un pago único del uno punto cinco por ciento (1.5%) sobre ingresos brutos obtenidos según la Declaración Jurada del Impuesto Sobre la Renta. Para tal efecto se tomará en relación el monto más alto reportado en cualquiera de estos periodos. Con el pago único también se regularizarán los años prescritos anteriores al año 2012.

También podrán regularizarse los años anteriores al 2012 que tengan acciones judiciales o administrativas pendientes, pagando otro monto igual al uno punto cinco por ciento (1.5%), calculado conforme a lo descrito en el párrafo anterior.

La tramitación para la obtención del finiquito y sello definitivo se hará separadamente ante la Administración Tributaria y la Administración Aduanera y lo recaudado por el pago único del uno punto cinco por ciento (1.5%) referido en el párrafo anterior, será reconocido como recaudación en partes iguales para ambas Administraciones. La tramitación consistirá únicamente en la presentación de una solicitud de emisión de finiquito y sello definitivo, la cual deberá acompañarse del Recibo de Pago TGR-1 a partir de la vigencia de este decreto o recibo de pago extendido por la administración aduanera o tributaria para los pagos efectuados antes de la vigencia de este decreto, correspondiente al pago único del uno punto cinco por ciento (1.5%) sobre los ingresos brutos obtenidos según la Declaración Jurada del Impuesto Sobre la Renta, según los parámetros indicados en el párrafo anterior. La Administración Tributaria y Aduanera, sin necesidad de emitir dictámenes y opiniones técnicas o legales, deberán emitir en un plazo de diez (10) días hábiles, la resolución que contenga el finiquito y sello definitivo la cual será amplia dando por cumplidas todas las obligaciones materiales y formales del Obligado Tributario, así como lo concerniente a todos los tributos que administran y recaudan tanto la Administración Tributaria como la Administración Aduanera para los periodos fiscales antes referidos, con tan solo constatar que el obligado tributario no tiene mora pendiente en sus declaraciones determinativas e informativas.

No podrán acogerse a este beneficio los obligados tributarios que se encuentren en mora al 31 de Diciembre de 2016. Los obligados tributarios que tengan valores pendientes de pagar al Fisco antes mencionados, previo a acogerse al beneficio establecido en este numeral deberán pagar los valores adeudados y que se encuentran firmes. Este beneficio surtirá efectos a partir de la vigencia del presente Decreto hasta el 30 de Septiembre de 2017.

Los obligados tributarios comprendidos en este numeral no serán objeto de fiscalización posterior por los periodos señalados, para lo cual la Administración Tributaria y la Administración Aduanera, emitirán inmediatamente y sin requisito alguno el finiquito o sello definitivo y quedarán exentos de toda responsabilidad administrativa, civil y penal por los actos y hechos relacionados con la amnistía tributaria y aduanera; asimismo, deberán indicar tal extremo en sus sistemas de tal forma que los obligados tributarios regularizados no sean incorporados en los planes de control y fiscalización relacionados con los periodos fiscales contenidos en la presente amnistía.

Para acogerse al beneficio de actualización tributaria y aduanera, las instituciones de seguro deberán de realizar el pago único del uno punto cinco por ciento (1.5%) sobre el año que obtuvo los mayores ingresos por primas netas de cancelaciones y devoluciones, más los ingresos financieros y las comisiones por reaseguro cedido.

3. Se faculta a la Administración Tributaria y a la Administración Aduanera, en el marco de sus atribuciones y competencias, para suscribir convenios o acuerdos de pago, exentos de multas, intereses y recargos, con los obligados tributarios que tengan obligaciones pendientes de pago en la vía administrativa o judicial al 31 de Diciembre de 2016, con la limitación que dichos convenios o acuerdos de pago tendrán vigencia hasta el 30 de Septiembre de 2017.

Los obligados tributarios pagarán la prima que la situación económica real le permita, pudiendo convenir cuotas razonables siempre y cuando se cancele la totalidad de la deuda tributaria a más tardar el 30 de Septiembre de 2017.

En los casos que en convenio de pago tenga relación con el pago único del uno punto cinco por ciento (1.5%) relacionados en los numerales anteriores, el finiquito y sello definitivo no se emitirá hasta haber completado la totalidad del pago.

Los pagos que se enteren al Fisco se realizarán por conducto de las instituciones bancarias autorizadas para ello, utilizando el Recibo Oficial de Pago (ROP) y el Recibo Aduanero de Pago (RAP) correspondiente, salvo que se realice en el acto de presentación de alguna Declaración. En el caso del pago del uno punto cinco por ciento (1.5%) sobre los ingresos brutos referido en el numeral 2, se hará utilizando el Recibo TGR-1 a partir de la vigencia de este Decreto o recibo de pago extendido por la Administración Aduanera o Tributaria para los pagos efectuados antes de la vigencia de este Decreto.

4. Conforme a este Decreto la Administración Tributaria y Aduanera deberán regularizar a todos aquellos contribuyentes que así lo soliciten que cumplan con todos los supuestos acá establecidos sin estar en mora debiendo ser ésta firme incluyendo a todos aquellos que mantengan expedientes en curso, solicitando la regularización bajo el Artículo 213 del Decreto No.170-2016.','213','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":213,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"ae01cd9c9ef040896c035a212f1e9340b3a9308d9f22b67463a0de19f113145d","ubicacion":[],"constancias":[{"nota":24,"tipo":"INTERPRETACION_AUTENTICA","texto":"Artículo 213. Reformado por Decreto No.32-2017 de fecha 31 de mayo de 2017 y publicado en el Diario Oficial La Gaceta No.34,376 de fecha 28 de junio de 2017. Artículo 213. Interpretado por Decreto No.98-2018 de fecha 6 de septiembre de 2018 y publicado en el Diario Oficial La Gaceta No.34,759 de fecha 2 de octubre de 2018. “el finiquito y el sello definitivo implica que los periodos fiscales se consideran cerrados; por lo tanto, se entiende satisfechos todos los derechos y obligaciones que emanan de dichos periodos, tanto para el obligado tributario como para la Administración Tributaria y Aduanera, así como en el Decreto No.129-2017 de fecha 18 de enero del 2018.”","decretos":["32-2017","98-2018","129-2017"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a213","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (interpretación auténtica anotada): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','213','ae01cd9c9ef040896c035a212f1e9340b3a9308d9f22b67463a0de19f113145d','OLA9_CTRIB_2024_01',now()),
('OLA9_CTRIB_2024_01:CODIGO_TRIBUTARIO:214','mayalex_normativos','08_TRIBUTARIO','DEROGACIONES. Se derogan las Disposiciones Legales Siguientes:
1) Decreto No.22-97 de fecha 8 de Abril de 1997 que contiene el CÓDIGO TRIBUTARIO, publicado en el Diario Oficial “La Gaceta” el 30 de Mayo de 1997 y sus reformas;

2) El literal d) del Artículo 61; y el Artículo 132 de la LEY DE PROCEDIMIENTO ADMINISTRATIVO, contenida en el Decreto No.152-87, de fecha 28 de Septiembre de 1987;

3) El literal d) del Artículo 47; y el Artículo 104, de la LEY DE LA JURISDICCIÓN DE LO CONTENCIOSO ADMINISTRATIVO, contenida en el Decreto No.189-87, de fecha 20 de Noviembre de 1987;

4) Artículo 35 de la LEY DE EQUILIBRIO FINANCIERO Y LA PROTECCIÓN SOCIAL, contenida en el Decreto No. 194-2002 de fecha 15 de Mayo de 2002;

5) Artículo 20 del Decreto 113-2011 contentivo de la LEY DE EFICIENCIA EN LOS INGRESOS Y EL GASTO PÚBLICO del 24 de Junio de 2011; y,

6) Los demás Decretos, Leyes y Reglamentos que se opongan a las disposiciones del presente Código.','214','Código Tributario de Honduras (Decreto No. 170-2016)','{"norm_id":"HN:CODIGO_TRIBUTARIO","instrumento_id":"CODIGO_TRIBUTARIO","ingest_batch":"OLA9_CTRIB_2024_01","ola":"OLA9","ordinal":214,"decreto":"170-2016","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Codigo Tributario (2024).pdf» (Word 2019, 2-sep-2024), con notas al pie de fe de erratas y reformas publicadas en La Gaceta.","pdf_sha256":"f0afc853e49abca6aeb60217791abde434c203ad71d13b62b54389ea871911fc","article_sha256":"ab84dac6ddf38aebe0c45aef2d13cbfc65f1a2bc5d1fd3633969105b9937e8b2","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:tributario_2016_a214","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRIBUTARIO','214','ab84dac6ddf38aebe0c45aef2d13cbfc65f1a2bc5d1fd3633969105b9937e8b2','OLA9_CTRIB_2024_01',now()),
